INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e0e44c45-65a3-5bbb-a8e3-ed3afaf2e7b9', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 7, 12, '“እንደ ሕጉም እግዚአብሔርን የሚፈራ ሐናንያ የሚባል አንድ ሰው ነበረ፤ በደማስቆም የሚኖሩ አይሁድ ሁሉ ያመሰግኑት ነበር።'),
  ('5b6c5f2c-47ce-53a7-aa64-f770d2cc4a15', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 8, 13, 'ወደ እኔም መጥቶ በፊቴ ቆመና፦ ‘ወንድሜ ሳውል ሆይ፥ እይ’ አለ፤ ያንጊዜም ወደ እርሱ አየሁ።'),
  ('2404c450-27a9-50a6-ae3d-25ba10d976db', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 9, 14, 'እንዲህም አለኝ፤ ‘የአባቶቻችን አምላክ ፈቃዱን ታውቅና ጽድቁንም ታይ ዘንድ፥ ቃሉንም ከአንደበቱ ትሰማ ዘንድ መረጠህ።'),
  ('4b31987d-3514-53fd-a639-ebcbfca859b2', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 10, 15, 'በሕዝብም ሁሉ ዘንድ ባየኸውና በሰማኸው ምስክር ትሆነዋለህ።'),
  ('4056d9c9-fa5e-54a3-a666-5c5938c6c5bb', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '04f2b468-2842-55cf-a068-3754d62ea0b0', 11, 16, 'አሁንም የምታደርገውን ልንገርህ፦ ተነሥ ስሙን እየጠራህ ተጠመቅ፤ ከኀጢአትህም ታጠብ።’'),
  ('f4034542-438c-530d-aed0-57b716ca07a9', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 1, 17, '“ከዚህም በኋላ ወደ ኢየሩሳሌም ተመልሼ በቤተ መቅደስ ስጸልይ ተመስጦ መጣብኝ።'),
  ('6b6b3042-722f-5af2-a234-1c345fbf03ff', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 2, 18, '‘ስለ እኔ የምትመሰክረውን ምስክርነት አይቀበሉህምና ከኢየሩሳሌም ፈጥነህ ውጣ’ ሲለኝ አየሁት።'),
  ('f10050a3-36d8-5938-a378-ea7415ede556', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 3, 19, 'እኔም እንዲህ አልሁት፦ ‘ጌታዬ ሆይ፥ በአንተ የሚያምኑትን በየምኵራቦቻቸው ሳስራቸውና ስደበድባቸው የነበርሁ እኔ እንደ ሆንሁ እነርሱ ያውቃሉ።'),
  ('c06da211-9bca-5636-a6d3-3976f757944c', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 4, 20, 'ሰማዕትህን እስጢፋኖስን በገደሉትም ጊዜ እኔ እዚያ አብሬአቸው ነበርሁ፤ የገዳዮችንም ልብስ እጠብቅ ነበር።’'),
  ('79962671-5099-510d-ace0-dc086fca0c39', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 5, 21, 'እርሱም፦ ‘ሂድ ርቀው ወደ አሉ አሕዛብ እልክሃለሁና’ ” አለኝ።'),
  ('4fa72faf-20f6-57d7-a926-90d723ff6eed', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 6, 22, 'ከጳውሎስም ይህን ነገር በሰሙ ጊዜ “ይህ በሕይወት ሊኖር አይገባውምና እንዲህ ያለውን ሰው ከምድር አስወግደው” እያሉ ጮሁ።'),
  ('0babc4f0-543c-5fa1-a234-23f3dbc7ab58', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 7, 23, 'እነርሱም እየጮሁና ልብሳቸውንም እየወረወሩ ትቢያውን ወደ ላይ ሲበትኑ፥'),
  ('3836e8c7-01ec-5de1-a347-3a9dd3d31fb8', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 8, 24, 'የሻለቃው የሚጮሁበት ስለ ምን እንደ ሆነ ያውቅ ዘንድ ወደ ወታደሮች ሰፈር እንዲያገቡትና እየገረፉ የሠራውን እንዲመረምሩት አዘዘ።'),
  ('225e50cc-5008-5fa9-a903-eabd6f50d4a0', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 9, 25, 'ሊገርፉትም በአጋደሙት ጊዜ ጳውሎስ በአጠገቡ የነበረውን የመቶ አለቃ፥ “የሮማን ሰው ያለ ፍርድ ልትገርፉ ይገባችኋልን?” አለው።'),
  ('c57e3b46-bc19-5249-ae23-bb2d3bf62880', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 10, 26, 'የመቶ አለቃውም ይህን በሰማ ጊዜ፥ ወደ ሻለቃው ሄደና፥ “ይህ ሰው ሮማዊ ነው፥ የምታደርገውን ዕወቅ” ብሎ ነገረው።'),
  ('6253fd84-8e93-5837-ab88-a7e62d468097', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 11, 27, 'የሻለቃውም ወደ እርሱ ቀርቦ፥ “አንተ ሮማዊ ነህን? እስኪ ንገረኝ” አለው፤ ጳውሎስም፥ “አዎን” አለው።'),
  ('f2f47383-f05e-51be-a9c1-1201fe253799', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 12, 28, 'የሻለቃውም መልሶ፥ “እኔ ይህችን ዜግነት ያገኘኋት ብዙ ገንዘብ ሰጥቼ ነው” አለው፤ ጳውሎስም፥ “እኔማ የተወለድሁ በዚያው ነው” አለው።'),
  ('26042e31-2217-5e92-a5cd-140bd4d2a356', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 13, 29, 'ከዚህም በኋላ ይመረምሩት ዘንድ የሚሹት ተዉት፤ የሻለቃውም ሮማዊ መሆኑን በዐወቀ ጊዜ“ ለምን አሰርሁት?” ብሎ ፈራ።'),
  ('2ddd4743-eb83-5d8e-a9ae-d3301e5752a7', '1f3df3f2-eafd-56eb-a1fc-d9db34fd3103', '57554f62-0b99-5079-ac58-b4e8cd055e04', 14, 30, 'በማግሥቱም የሻለቃው አይሁድ የሚከሱት ስለ ምን እንደሆነ ያውቅ ዘንድ ወደደና ከእስራቱ ፈታው፤ ሊቃነ ካህናቱና ሸንጎውም ሁሉ እንዲመጡ አዘዘ፤ ጳውሎስንም አምጥቶ በፊታቸው አቆመው።'),
  ('4f5b2b53-817d-50cd-aa86-7ae431bc3661', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 1, 1, 'ጳውሎስም በአደባባዩ ወደአሉት ሰዎች አተኵሮ ተመለከተና፥ “እናንተ ሰዎች ወንድሞች፥ እኔስ እስከዚች ቀን ድረስ በመልካም ሕሊና ሁሉ እግዚአብሔርን ሳገለግል ኑሬአለሁ” አላቸው።'),
  ('54e965ba-64b5-5469-aab2-19c1cd6adbf6', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 2, 2, 'ሊቀ ካህናቱ ሐናንያ ግን ጳውሎስን አፉን እንዲመቱት በአጠገቡ ቆመው የነበሩትን አዘዘ።'),
  ('9844edce-f169-5ada-a5ba-18e910d630fe', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 3, 3, 'ጳውሎስም መልሶ፥ “አንተ የተለሰነ ግድግዳ በሕግ ልትፈርድብኝ ተቀምጠህ ሳለ ያለ ሕግ እመታ ዘንድ ታዝዛለህን? እግዚአብሔር በቍጣው መቅሠፍት ይመታሃል” አለው።'),
  ('b1490070-f3bd-5b8a-afe7-dfa96b591c4a', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 4, 4, 'በአጠገቡ ቆመው የነበሩትም ጳውሎስን፥ “እግዚአብሔር የሾመውን ሊቀ ካህናት እንዴት ትሳደባለህ?” አሉት።'),
  ('50fbb48c-de4a-538f-a7c9-42cb19732f1d', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 5, 5, 'ጳውሎስም፥ “ወንድሞች፥ ሊቀ ካህናት መሆኑን አላውቅም መጽሐፍ ‘በሕዝብህ አለቃ ላይ ክፉ አትናገር’ ይላልና” አላቸው።'),
  ('96ae1bbd-adb4-5412-a0cc-75da292012ad', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 6, 6, 'ጳውሎስም እኩሌቶቹ ሰዱቃውያን እኩሌቶቹም ፈሪሳውያን እንደ ሆኑ ዐውቆ፥ “እኔ ፈሪሳዊ የፈሪሳዊ ልጅ ነኝ፤ ስለ ተስፋና ስለ ሙታን መነሣትም ይፈረድብኛል” ብሎ በአደባባይ ጮኸ።'),
  ('1626f2e9-46f9-51b1-aae8-2829d787c993', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 7, 7, 'እንዲህም ባለ ጊዜ ፈሪሳውያንና ሰዱቃውያን ተጣሉ፤ ሸንጎውም ተከፋፈለ።'),
  ('a67ac5a2-e1a7-5445-a4fa-b58c3152d9f8', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 8, 8, 'ሰዱቃውያን፥ “ሙታን አይነሡም፤ መልአክም የለም፤ መንፈስም የለም” ይላሉና፤ ፈሪሳውያን ግን ይህ ሁሉ እንዳለ ያምናሉ።'),
  ('4a5940ce-868f-5627-afdf-584ae5a987eb', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 9, 9, 'ታላቅ ውካታም ሆነ፤ ከፈሪሳውያንም ወገን የሆኑ ጸሐፍት ተነሥተው ይጣሉና ይከራከሩ ጀመሩ፤ “በዚህ ሰው ላይ ያገኘነው ክፉ ነገር የለም፤ መንፈስ ወይም መልአክ ተናግሮት እንደ ሆነ እንጃ፥ ከእግዚአብሔር ጋር አንጣላ” አሉ።'),
  ('7799fe13-cc13-55d4-a471-d567ed6a625f', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 10, 10, 'እጅግም በታወኩ ጊዜ ጳውሎስን እንዳይነጥቁት የሻለቃው ፈራና መጥተው ከመካከላቸው አውጥተው ወደ ወታደሮች ሰፈር ይወስዱት ዘንድ ወታደሮቹን አዘዘ።'),
  ('81662f30-6ea0-584a-a2d4-24e6ba4aa913', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 11, 11, 'በሁለተኛዪቱም ሌሊት ጌታችን ለጳውሎስ ተገልጦ፥ “ጽና፥ በኢየሩሳሌም ምስክር እንደ ሆንኸኝ እንዲሁ በሮም ምስክር ትሆነኛለህ” አለው።'),
  ('68f5a132-50cb-5a17-a1b3-dc729c78efd3', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 12, 12, 'በነጋም ጊዜ አይሁድ ተሰብስበው፥ ጳውሎስን እስኪገድሉት ድረስ እንዳይበሉና እንዳይጠጡ ተስማምተው ተማማሉ።'),
  ('a6cc1234-437a-5140-a6c1-0b8173a11328', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 13, 13, 'ይህንም ለማድረግ የተማማሉት ሰዎች ከአርባ ይበዙ ነበር።'),
  ('5d62f667-fec3-53b4-a61e-897acf65a0d4', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 14, 14, 'እነርሱም ወደ ሊቃነ ካህናትና ወደ መምህራን ሄደው እንዲህ አሉአቸው፥ “ጳውሎስን እስክንገድለው ድረስ እነሆ፥ እንዳንበላና እንዳንጠጣ ፈጽመን ተማምለናል።'),
  ('806ec3c7-6356-5940-ab41-cc256c1bbdf9', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 15, 15, 'አሁንም እናንተ ከሸንጎው ጋር ወደ ሻለቃው ሂዱና የምትመረምሩትና የምትጠይቁት አስመስላችሁ ጳውሎስን እንዲያመጣው ንገሩት፤ እኛ ግን ወደ እናንተ ከመድረሱ አስቀድሞ ልንገድለው ቈርጠናል።”'),
  ('753da2a6-4cab-57bf-a6f2-cbad887998b4', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 16, 16, 'የጳውሎስም የእኅቱ ልጅ ምክራቸውን በሰማ ጊዜ ሄዶ ወደ ወታደሮች ሰፈር ገባና ለጳውሎስ ነገረው።'),
  ('006e1753-ae70-54cb-ad6d-f23cb44f002a', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 17, 17, 'ጳውሎስም ከመቶ አለቆች አንዱን ጠርቶ፥ “የሚነግረው ነገር አለና ይህን ልጅ ወደ የሻለቃው አድርስልኝ” አለው።'),
  ('e224b31c-aa75-5b18-a41e-852ba16b2dec', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 18, 18, 'የመቶ አለቃውም ልጁን ይዞ ወደ የሻለቃው ወሰደውና፥ “የሚነግርህ ስለ አለው እስረኛው ጳውሎስ ይህን ልጅ ወደ አንተ እንዳደርሰው ለመነኝ” አለው።'),
  ('fefed478-7981-5d8a-ae3f-001be07496f3', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 19, 19, 'የሻለቃውም ልጁን በእጁ ይዞ ለብቻው ገለል አድርጎ፥ “የምትነግረኝ ነገሩ ምንድነው?” አለው።'),
  ('3cea8660-af31-54c1-a7a9-d5a70df6bf93', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 20, 20, 'ልጁም እንዲህ አለው፥ “አይሁድ አጥብቀህ የምትመረምረው መስለህ ጳውሎስን ነገ ወደ ሸንጎ ታወርድላቸው ዘንድ ሊማልዱህ እንዲህ መክረዋል።'),
  ('37c21f24-e1cc-5865-a4b8-c9711e139c4e', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 21, 21, 'አንተ ግን እሽ አትበላቸው፤ ሊገድሉት ሽምቀዋልና፤ እስኪገድሉትም ድረስ እንዳይበሉና እንዳይጠጡ እንዲህ የተማማሉ ሰዎች ከአርባ ይበዛሉ፤ አሁንም እስክትልክላቸው ይጠብቃሉ እንጂ እነርሱ ቈርጠዋል።”'),
  ('92e7d448-2cfc-544f-a252-8006637fa51d', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 22, 22, 'ከዚህም በኋላ፤ የሻለቃው፥ “ይህን ነገር ለእኔ መንገርህን ለማንም እንዳትገልጽ” ብሎ አሰናበተው።'),
  ('75c33963-9a5c-5fbc-a680-7e24bd47c5fc', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 23, 23, 'ከመቶ አለቆችም ሁለቱን ጠርቶ፥ “ከወታደሮች ሁለት መቶ ሰውና ሰባ ፈረሰኞች፥ ሁለት መቶ ቀስተኞችም ምረጡ፤ ከሌሊቱም በሦስት ሰዓት ወደ ቂሣርያ ይሂዱ” አላቸው።'),
  ('d4e8f3c4-0ad6-5163-a5d2-65c1129ec428', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 24, 24, 'አህያም አምጥተው ጳውሎስን በዚያ አስቀምጠው ወደ ቂሣርያ አገረ ገዢ ወደ ፊልክስ እንዲወስዱት አዘዛቸው።'),
  ('2ca93440-6d13-510a-a9b0-b1807868034b', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 25, 25, 'እንዲህ የምትል ደብዳቤም ጻፈለት።'),
  ('c339bd0f-ed15-5c6a-ae4c-49d4c788901f', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 26, 26, '“ከሉስዮስ ቀላውዴዎስ፥ ለክቡር አገረ ገዢ ፊልክስ፥ ሰላም ለአንተ ይሁን።'),
  ('4029a880-6113-5155-afb8-ff73bced486d', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 27, 27, 'ይህን ሰው አይሁድ ያዙት፤ ሊገድሉትም ፈለጉ፤ ከወታደሮችም ጋር ተከላከልሁለት፥ የሮም ሰው መሆኑንም ዐውቄ አዳንሁት።'),
  ('ba4af441-7ea3-52dd-a112-8be18b102b3d', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 28, 28, 'በምን ምክንያትም እንደሚከሱት በደሉን አውቅ ዘንድ ወደ ሸንጎ አቅርቤ መረመርሁት።'),
  ('f68925cd-38a0-50d9-a94c-7bdb9c8522a4', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 29, 29, 'ስለ ሕጋቸውም ብቻ እንደ ከሰሱት ተረዳሁ፤ ለሞትና ለመታሰር የሚያበቃ ሌላ በደል ግን የለበትም።'),
  ('36392f6b-77bd-5327-a960-da537d001883', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 30, 30, 'አይሁድም በዚህ ሰው ላይ በመሸመቅ የሚያደርጉትን በዐወቅሁ ጊዜ ወደ አንተ ላክሁት፤ ከሳሾቹንም ወደ አንተ እንዲመጡና በፊትህ እንዲፋረዱት አዝዣቸዋለሁ፤ ደኅና ሁን።”'),
  ('b057d0f2-ab41-5939-ab2b-56d4a603d7c8', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 31, 31, 'ጭፍሮችም እንዳዘዛቸው አደረጉ፤ ጳውሎስንም በሌሊት ወሰዱት፤ ወደ አንቲጳጥሪስም አደረሱት።'),
  ('5a957c16-0b93-5832-ac3f-4d05970beb67', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 32, 32, 'በማግሥቱም ከእርሱ ጋር ይሄዱ ዘንድ ፈረሰኞችን ትተው እነርሱ ወደ ሰፈር ተመለሱ።'),
  ('b715a1e6-39bc-5a41-ad84-19ac7ae99d91', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 33, 33, 'ከዚህም በኋላ ወደ ቂሣርያ ገቡ፤ ወደ አገረ ገዢውም ደረሱ፤ የተላከውንም ደብዳቤ ለአገረ ገዢው ሰጡት፤ ጳውሎስንም ወደ እርሱ አቀረቡት።'),
  ('d6f143c0-81ca-55f4-af4c-282d9d6123fc', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 34, 34, 'ደብዳቤውንም ካነበበ በኋላ ከማን ግዛት እንደ ሆነ ጠየቀው። ከኪልቅያ የመጣ መሆኑንም ባወቀ ጊዜ፦'),
  ('ca4838c2-78a7-58c0-abd1-36f7e9123690', '348341a9-2fe8-5722-af1c-f0dc0283b253', 'a1e8f18d-81ac-5b8a-aea8-0ee784fc4f45', 35, 35, '“እንኪያስ ከሳሾችህ ሲመጡ እንሰማሃለን” አለው፤ በሄሮድስም ግቢ እንዲጠብቁት አዘዘ።'),
  ('e271a214-d07f-53e8-a399-dbf885e4a6d8', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 1, 1, 'በአምስተኛውም ቀን ሊቀ ካህናቱ ሐናንያ ከመምህራኑና ጠርጠሉስ ከሚባል አንድ ጠበቃ ጋር ወረደ፤ ጳውሎስንም በአገረ ገዢው ዘንድ ከሰሱት።'),
  ('5c59fb0a-968b-520e-a2cb-8c048568ad01', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 2, 2, 'ጳውሎስም በቀረበ ጊዜ ጠርጠሉስ እንዲህ እያለ ይከስሰው ጀመረ፤'),
  ('76097f43-bc87-5fce-ac40-813184042596', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 3, 3, '“ክቡር ፊልክስ ሆይ፥ በዘመንህ ብዙ ሰላምን አግኝተናል፤ በጥበብህም በየጊዜው በየሀገሩ የሕዝቡ ኑሮ የተሻሻለ ሆኖአል፤ ሥርዐትህንም በሁሉ ዘንድ ስትመሰገን አግኝተናታል።'),
  ('24112a43-ca99-525e-aa38-9ee6dc42df3a', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 4, 4, 'ነገር ግን ነገር እንዳላበዛብህ በአጭሩ ትሰማኝ ዘንድ እለምንሃለሁ።'),
  ('0578e50a-137c-5bb8-a0f4-fcbf6698f652', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 5, 5, 'ይህን ሰው ሲሳደብና ወንጀል ሲሠራ፥ አይሁድንም ሁሉ በየሀገሩ ሲያውክ፥ ናዝራውያን የተባሉት ወገኖች የሚያስተምሩትንም ክህደት ሲያስተምር አግኝተነዋል።'),
  ('a8a83786-c270-5dc3-ac7c-31ccffdef7c6', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 6, 6, 'ቤተ መቅደስንም ሊያረክስ ሲሞክር ያዝነው፤ እንደ ሕጋችንም ልንፈርድበት ፈልገን ነበር።'),
  ('32d89223-44b5-59ed-ad5a-85230ea0cea7', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 7, 7, 'ነገር ግን የሻለቃው ሉስዮስ መጥቶ በብዙ ጭንቅ ከእጃችን ነጥቆ ወደ አንተ ላከው።'),
  ('63b35c73-8441-544d-af86-55d566ce32d0', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 8, 8, 'ከሳሾቹንም ወደ አንተ እንዲመጡ አዘዛቸው፤ የከሰስንበትንም ነገር ሁሉ መርምረህ ከእርሱ ልትረዳ ትችላለህ።”'),
  ('21d6fab4-d624-5867-aab1-d7a761359fbe', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '8ea92e6b-53ea-5d60-ac2f-6f7ac4378ba0', 9, 9, 'አይሁድም፥ “እውነት ነው፤ እንዲሁ ነው” ብለው መለሱ።'),
  ('e744228f-8e2a-5a83-ae2b-e1bae2a6e4d5', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 1, 10, 'ሀገረ ገዢውም እንዲናገር ጳውሎስን ጠቀሰው፤ ጳውሎስም እንዲህ አለ፥ “ከብዙ ዘመን ጀምሮ የዚህ ሕዝብ አስተዳዳሪ እንደ ሆንህ አውቃለሁ፤ ጠባያቸውንም ታውቃለህ። አሁንም ደስ እያለኝ ክርክሬን አቀርባለሁ።'),
  ('d5b2bec2-6426-50ab-a07c-9a90e1f3ae02', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 2, 11, 'እሰግድ ዘንድ ወደ ኢየሩሳሌም ከወጣሁ ዐሥራ ሁለት ቀን እንደማይሆን ልታውቀው ትችላለህ፤'),
  ('554aa224-6e9a-5267-aaae-f9e685ae1b8d', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 3, 12, 'በምኵራብ ቢሆን፥ በቤተ መቅደስም ቢሆን፥ በከተማም ቢሆን ሕዝብን ሳውክ፥ ከማንም ጋር ስከራከር አላገኙኝም።'),
  ('ceafaeba-6cc6-5202-af1d-3f0b9f1e81a4', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 4, 13, 'በሚከስሱኝ ሁሉ በፊትህ ማስረጃ ማቅረብ አይችሉም።'),
  ('d392e609-f0e9-5a96-a81c-7ba2c6c09c5b', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 5, 14, 'ነገር ግን ይህን አረጋግጥልሃለሁ፤ እኔ በሕግ ያለውን፥ በነቢያትም የተጻፈውን ሁሉ አምኜ እነርሱ ክህደት ብለው በሚጠሩት ትምህርት የአባቶችን አምላክ አመልከዋለሁ።'),
  ('7b4466c0-5ceb-5b90-a911-5e7d47f2ca58', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 6, 15, 'እነርሱም ለጻድቃንና ለኃጥኣን የሙታን ትንሣኤ ይሆን ዘንድ እንደሚጠብቁ ለእኔም እንዲሁ በእግዚአብሔር ዘንድ ተስፋ አለኝ።'),
  ('7ba16fd1-1148-52f6-a3c3-b605a3e10083', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 7, 16, 'እንዲሁ እኔም በእግዚአብሔርና በሰው ፊት ሁልጊዜ የማታወላውል ሕሊና ትኖረኝ ዘንድ እጋደላለሁ።'),
  ('2468f380-a11b-5658-a2bb-0ecc829200c1', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 8, 17, 'ከብዙ ዓመታትም በኋላ ለወገኖች ምጽዋትንና መሥዋዕትን ላደርግ መጣሁ።'),
  ('f0fba707-4bb8-538b-acbe-aea0d41a456a', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 9, 18, 'በዚያም ጊዜ ከእስያ የመጡ አይሁድ ከሕዝብ ጋር በመከራከር፥ ወይም በፍጅት ሳይሆን በመቅደስ ስነጻ አገኙኝ።'),
  ('ed4554dc-98e2-55bb-a09e-7dcb96a220f1', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 10, 19, 'አሁንም በእኔ ላይ ነገር ከአላቸው ወደ አንተ ይምጡና ይክሰሱኝ።'),
  ('6c3953a8-1e14-53f9-aa39-bce2191ba355', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 11, 20, 'ወይም እኔ በሸንጎ ቆሜ ሳለሁ ያገኙብኝ በደል እንደ አለ እነዚህ ራሳቸው ይመስክሩ።'),
  ('b1fe9a40-8212-58d3-a6e5-4ba9c4685b0e', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 12, 21, 'በመካከላቸው ቆሜ ከአስተማርኋት አንዲት ትምህርት በቀር ያደረግሁት ክፉ ነገር የለም። ‘ሙታን ይነሣሉ’ በማለቴም ዛሬ በአንተ ዘንድ በእኔ ይፈረድብኛል።”'),
  ('39e6fce6-ea8f-580e-acd7-e67f3dc5c5de', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 13, 22, 'ፊልክስ ግን አይሁድ ከጥንት ጀምሮ የክርስቲያንን ወገኖች ሕግና ትምህርት እንደሚቃወሙ ያውቅ ነበር፤ ስለዚህም “እንኪያስ የሺ አለቃው ሉስዮስ በመጣ ጊዜ ነገራችሁን እናውቅ ዘንድ እንመረምራለን” ብሎ ቀጠራቸው።'),
  ('563d5226-8167-5045-af39-fe3dcece2522', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 14, 23, 'የመቶ አለቃውንም ጳውሎስን እንዲጠብቀው፥ በሰፊ ቦታም እንዲያኖረው፥ እንዳያጠብበትም፥ ሊያገለግሉት በመጡ ጊዜም ከወዳጆቹ አንዱን ስንኳ እንዳይከለክልበት አዘዘ።'),
  ('4f81cad6-66ea-562d-ad9c-a3a1876cb4a5', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 15, 24, 'ከጥቂት ቀንም በኋላ ፊልክስ ከአይሁዳዊት ሚስቱ ከድሩሲላ ጋር መጣ። ልኮም ጳውሎስን አስጠራው፤ በኢየሱስ ክርስቶስ ስለ ማመንም የሚናገረውን ነገር ሰማው።'),
  ('8ae23032-7acb-5637-a83d-1848f3a983bf', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 16, 25, 'እርሱም ስለ ጽድቅና ስለ ንጽሕና፥ ስለሚመጣውም ኵነኔ በነገራቸው ጊዜ በዚህ የተነሣ ፊልክስ ፈራና ጳውሎስን፥ “አሁንስ ሂድ፤ በተመቸኝም ጊዜ ልኬ አስጠራሃለሁ” አለው።'),
  ('a20bcd02-1086-5dd2-ae3b-32af7245a105', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 17, 26, 'ፊልክስም እንዲፈታው ጳውሎስ ገንዘብ የሚሰጠው መስሎት ነበር፤ ስለዚህ ዘወትር ይጠራውና ያነጋግረው ነበር።'),
  ('eb365011-c08d-556a-ab49-f48acd967ef4', '8f644007-7d8c-5415-a571-dcf48fb8ff33', '71b31023-e826-57ec-a3c8-3d7400f87416', 18, 27, 'ሁለት ዓመትም ካለፈ በኋላ፥ ፊልክስ ተሻረና ጶርቅዮስ ፊስጦስ የሚባል ሌላ ሀገረ ገዢ በእርሱ ቦታ መጣ፤ ፊልክስም በግልጥ ለአይሁድ ሊያዳላ ወደደ፤ ስለዚህም ጳውሎስን እንደ ታሰረ ተወው።'),
  ('8cf1899d-8512-512e-a131-e21e219e0de3', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 1, 1, 'ፊስጦስም ወደ ቂሣርያ ደርሶ ሦስት ቀን ሰነበተ፤ ከዚህም በኋላ ወደ ኢየሩሳሌም ወጣ።'),
  ('57beab73-2e5f-5b27-a377-7eba0498939b', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 2, 2, 'ሊቃነ ካህናትና የአይሁድ ሽማግሎችም ከበቡት፤ የጳውሎስንም ነገር ነገሩት።'),
  ('55ae9a87-ca2d-5460-aea0-b45ea3c4b6af', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 3, 3, 'ልኮም ወደ ኢየሩሳሌም አደባባይ እንዲያስመጣውና እንዲሰጣቸው ለመኑት፤ እነርሱ ግን ወደዚያ ሄደው በመንገድ ሸምቀው ሊገድሉት ፈልገው ነበር።'),
  ('4a91b5e8-021c-5dfd-aade-5d681419b6e2', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 4, 4, 'ፊስጦስም ጳውሎስን በቂሣርያ እንደሚጠብቁት፥ እርሱም ራሱ ወደዚያው በቶሎ እንደሚሄድ መለሰላቸው።'),
  ('b2435e81-0970-52c7-aab5-a109ce4849c6', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 5, 5, 'አይሁድንም፥ “ከመካከላችሁ የሚችሉ ካሉ ከከሰሳችሁት ከዚያ ሰው ጋር እንዲከራከሩ ከእኔ ጋር ይውረዱ” አላቸው።'),
  ('eb0f7398-b95d-5d1e-afdc-fa933025c65f', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 6, 6, 'ስምንት ወይም ዐሥር ቀን በእነርሱ ዘንድ ከሰነበተ በኋላ ወደ ቂሣርያ ሄደ፤ በማግሥቱም በፍርድ ወንበር ተቀምጦ ጳውሎስን እንዲያመጡት አዘዘ።'),
  ('f448c861-0c3c-5ccd-a455-464f35d8a517', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 7, 7, 'ጳውሎስም በቀረበ ጊዜ ከኢየሩሳሌም የወረዱ አይሁድ ከብበውት ቆሙ፤ ሊረቱ በማይችሉበትም ብዙና ከባድ ክስ ከሰሱት።'),
  ('3a119a7b-27d8-54d6-a565-a432e3358f6c', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 8, 8, 'ጳውሎስም ሲመልስ፥ “በአይሁድ ሕግ ላይ ቢሆን፥ በቤተ መቅደስም ላይ ቢሆን፥ በቄሣር ላይም ቢሆን አንዳች የበደልሁት የለም” አለ።'),
  ('5fcdd539-4db2-530b-ac08-8aaec86a810a', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 9, 9, 'ፊስጦስ ግን አይሁድ እንዲያመሰግኑት ወዶ ጳውሎስን፥ “ወደ ኢየሩሳሌም ወጥተህ ስለዚህ ነገር በዚያ ከእኔ ዘንድ ልትከራከር ትሻለህን?” አለው።'),
  ('613d7e42-4d9b-5f81-aa01-fc8ddb6c3eae', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 10, 10, 'ጳውሎስም መልሶ እንዲህ አለው፤ “እኔ ወደ ቄሣር ዙፋን ችሎት እቀርባለሁ፤ ፍርዴም በዚያ ሊታይልኝ ይገባል፤ በአይሁድም ላይ የበደልሁት በደል እንደሌለኝ ከሰው ሁሉ ይልቅ አንተ ራስህ ታውቃለህ።'),
  ('bac497e3-6180-5ca7-a57a-42c357c12d0f', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 11, 11, 'ከበደልሁ ወይም ለሞት የሚያበቃኝ የሠራሁት ክፉ ሥራ ካለ ሞት አይፈረድብኝ አልልም፤ ነገር ግን እነዚህ በደል የሌለብኝን በከንቱ የሚከስሱኝ ከሆነ፥ ለእነርሱ አሳልፎ ሊሰጠኝ ለማን ይቻለዋል? እኔ ወደ ቄሣር ይግባኝ ብያለሁ።”'),
  ('1a35701a-8a6e-5b5b-ae68-99d68bdc754a', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '6033557c-4cdd-5ac6-a985-722970e86955', 12, 12, 'ከዚህም በኋላ ፊስጦስ ከአማካሪዎቹ ጋር ተማክሮ፥ “ወደ ቄሣር ይግባኝ ካልህ ወደ ቄሣር ትሄዳለህ” አለው።'),
  ('4e4d4a59-a7aa-5929-aebd-80ed764fb2ac', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 1, 13, 'ከጥቂት ቀን በኋላም ንጉሥ አግሪጳና በርኒቄ ወደ ቂሣርያ ወርደው ፊስጦስን ተገናኙት።'),
  ('649f5b53-710e-5fb5-ab4b-0068be63ccc5', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 2, 14, 'በእርሱ ዘንድ ብዙ ቀን ከቈዩ በኋላ ፊስጦስ የጳውሎስን ነገር ለንጉሡ ነገረው፤ እንዲህም አለው፥ “ፊልክስ በእስር ቤት ትቶት የሄደ አንድ እስረኛ ሰው በእዚህ አለ።'),
  ('666ab846-32dc-5f0a-a10b-ec8b2090f801', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 3, 15, 'በኢየሩሳሌም ሳለሁም ሊቃነ ካህናትና የአይሁድ ሽማግሌዎች ወደ እኔ መጥተው እንድፈርድበት ማለዱኝ።'),
  ('adcd3374-ac0a-5a14-a66a-62a077dbf8a5', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 4, 16, 'እኔም፦ ተከሳሹ በከሳሾቹ ፊት ሳይቆም፥ ለተከሰሰበትም ምላሽ ይሰጥ ዘንድ ፋንታ ሳያገኝ ማንም ቢሆን አሳልፎ መስጠት የሮማውያን ሕግ አይደለም ብየ መለስሁላቸው።'),
  ('b7f48ee9-5aec-54b0-a130-8ce1c6e1237b', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 5, 17, 'ከዚህም በኋላ፤ በዚሁ በተሰበሰቡ ጊዜ ሳልዘገይ በማለዳ በፍርድ ወንበር ተቀምጬ፥ ያን ሰው እንዲያመጡት አዘዝሁ።'),
  ('cde704db-1ebf-54f5-a847-0c3bd774a779', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 6, 18, 'የከሰሱትም በቆሙ ጊዜ፥ እኔ እንደ አሰብሁት በከሰሱት ክስ የሠራው ምንም ነገር የለም።'),
  ('12c309bf-4897-5b41-aa12-c7661788c5d8', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 7, 19, 'ስለ ሃይማኖታቸው ከሆነው ክርክርና ስለ ሞተው፥ ጳውሎስ ግን ሕያው ነው ስለሚለው ሰው ስለ ኢየሱስ ከሆነው ክርክር በቀር፤'),
  ('5398ee69-3703-5134-a3af-30ba73952411', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 8, 20, 'ስለ ክርክራቸውም የማደርገውን አጥቼ ጳውሎስን ወደ ኢየሩሳሌም ሄደህ በዚያ ልትከራከር ትወዳለህን? አልሁት።'),
  ('e3e147d2-b705-5ccd-a00d-ea6713c8ea7c', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 9, 21, 'ጳውሎስ ግን እንቢ ብሎ፥ እንዲድን ወደ ቄሣር ይግባኝ አለ፤ ከዚህም በኋላ ወደ ቄሣር እስክልከው ድረስ እንዲጠብቁት አዘዝሁ።”'),
  ('1a8c3f26-34eb-5b32-a501-3d74f274f3cd', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 10, 22, 'አግሪጳም ፊስጦስን፥ “እኔም ያን ሰው ልሰማው እወዳለሁ” አለው፤ ፊስጦስም፥ “እንግዲያስ ነገ ትሰማዋለህ” አለው።'),
  ('d420b218-ce0e-56c0-ab44-6764ef7e4449', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 11, 23, 'በማግሥቱም አግሪጳና በርኒቄ በብዙ ግርማ መጡ፤ ከመሳፍንቱና ከከተማው ታላላቅ ሰዎች ጋርም ወደ ፍርድ ቤት ገቡ፤ ፊስጦስም ጳውሎስን እንዲያመጡት አዘዘ።'),
  ('80fb982c-5822-577d-a859-c4a8b4d3b779', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 12, 24, 'ፊስጦስም እንዲህ አለ፥ “ንጉሥ አግሪጳ ሆይ፥ እናንተም ከእኛ ጋር ያላችሁ ወንድሞቻችን ሁላችሁ፥ ስሙ፤ አይሁድ ከእንግዲህ ወዲህ በሕይወት ይኖር ዘንድ እንዳይገባው በኢየሩሳሌምም ሆነ በዚህ እየጮሁ የለመኑኝ ይህ የምታዩት ሰው እነሆ።'),
  ('a314877b-2267-5e29-a96c-537fa263d58a', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 13, 25, 'እኔ ግን ለሞት የሚያደርሰው በደል እንዳልሠራ እጅግ መርምሬ፥ እርሱም ራሱ ወደ ቄሣር ይግባኝ ማለትን ስለወደደ እንግዲህ ልልከው ቈርጫለሁ።'),
  ('54288a93-75b3-5abd-afab-0f3c1b6c5eac', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 14, 26, 'ነገር ግን ስለ እርሱ ወደ ጌታዬ የምጽፈው የታወቀ ነገር የለኝም። ስለዚህ ከተመረመረ በኋላ የምጽፈውን አገኝ ዘንድ ወደ እናንተ ይልቁንም ንጉሥ አግሪጳ ሆይ ወደ አንተ አመጣሁት።'),
  ('f68910f5-3f16-5e63-a1fd-49ee8fe32874', '15823682-6bc8-5e7f-a404-e2d433d0b9e3', '17c6611d-68bb-52cd-a8f8-1c20d3ad1379', 15, 27, 'የበደሉ ደብዳቤ ሳይኖር እስረኛን ወደ ንጉሥ መላክ አይገባምና፤ ለእኔም ነገሩም ሆነ አስሮ መላኩ አስቸግሮኛል።”'),
  ('6c181e4d-c005-5993-a5a6-198c807b0127', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 1, 1, 'አግሪጳም ጳውሎስን፥ “ስለ ራስህ ትናገር ዘንድ ፈቅደንልሃል” አለው፤ ከዚህም በኋላ ጳውሎስ እጁን አነሣና ይነግራቸው ጀመር፤ እንዲህም አለ፦'),
  ('2755ff10-db09-5fac-a5da-9d96df07ebba', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 2, 2, '“ንጉሥ አግሪጳ ሆይ፥ አይሁድ እኔን ስለ ከሰሱበት ነገር ሁሉ ዛሬ በአንተ ዳኝነት እከራከር ዘንድ ስለ ተገባኝ ራሴን እንደ ተመሰገነ አድርጌ እቈጥረዋለሁ።'),
  ('3ac50fb5-da72-514d-acbd-e66d42244ef3', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 3, 3, 'የአይሁድን ጠባያቸውንና ክርክራቸውን አጥብቀህ ታውቃለህና ታግሠህ ታደምጠኝ ዘንድ እለምንሃለሁ።'),
  ('ab20bf26-73ed-5ced-a7e4-fd57584864d2', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 4, 4, '“ከልጅነቴ ጀምሮ በወገኖች መካከል በኢየሩሳሌም የኖርሁትን ኑሮ አይሁድ ሁሉ ያውቃሉ።'),
  ('43039bb8-8136-5684-abf1-679d3f7dc047', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 5, 5, 'ሊመሰክሩም ከወደዱ እኔ ፈሪሳዊ ሆኜ በአባቶቻችን ሕግ እንደምኖር ከጥንት ጀምሮ እነርሱ ያውቁልኛል።'),
  ('83f8c6d7-dfd9-51f2-a54c-e0a5f6b8e687', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 6, 6, 'አሁንም ከጥንት ጀምሮ በእግዚአብሔር ዘንድ ለአባቶቻችን የተሰጠውን ተስፋ በመታመን ከፍርድ በታች ቆሜአለሁ።'),
  ('00c340ed-a6e4-5703-a23f-518009d12d77', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 7, 7, 'ንጉሥ አግሪጳ ሆይ፥ ዐሥራ ሁለቱ ነገዶቻችን በመዓልትም በሌሊትም እርሱን እያገለገሉ ወደ እርስዋ ይደርሱ ዘንድ ተስፋ ያደርጋሉ፤ አይሁድም የሚከስሱኝ ስለዚህ ተስፋ ነው።'),
  ('ee890b21-dc9d-5d71-ab20-01681d8e617a', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 8, 8, 'እንዴትስ እግዚአብሔር ሙታንን እንደሚያስነሣቸው በእናንተ ዘንድ የማይታመን ሆኖ ይቈጠራል?'),
  ('b56ffccf-4d33-5a09-a698-9f335d4447c8', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 9, 9, '“እኔም ብዙ ጊዜ በናዝሬቱ በኢየሱስ ስም ላይ ክፉ ነገር ላደርግ ቈርጬ ነበር።'),
  ('0649b720-edb6-53b5-abca-f58286b56fce', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 10, 10, 'ይህንም በኢየሩሳሌም አደረግሁት፤ ከሊቃነ ካህናትም ሥልጣን ተቀብዬ ከቅዱሳን ብዙዎችን ወደ ወኅኒ ቤት አስገባኋቸው፤ ሲገድሏቸውም አብሬ እመክር ነበርሁ።'),
  ('b2c527c4-e037-5091-a9a8-253cc95f176d', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '83c5f183-b383-57d8-a2ce-a1980ff8e867', 11, 11, 'በየምኵራቡ ሁሉ የማስገደጃ ማዘዣ አምጥቼ፥ በግድ የኢየሱስን ስም እንዲሰድቡ ዘወትር መከራ አጸናባቸው ነበር፤ ይልቁንም ወደ ሌሎች ከተማዎች እያሳደድሁ ከፋሁባቸው።'),
  ('8ce6be87-7acc-56ca-add2-a495a4f6df82', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 1, 12, '“ይህንም ለመፈጸም ከሊቃነ ካህናት ሥልጣን ተቀብዬ ወደ ደማስቆ ከተማ ሄድሁ።'),
  ('bcd7a740-cb1b-5a77-ac6f-ebf00453d155', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 2, 13, 'ንጉሥ ሆይ፥ እኩል ቀን በሆነ ጊዜ በመንገድ ስሄድ ከፀሐይ ይልቅ የሚበራ መብረቅ በእኔና ከእኔ ጋር ይሄዱ በነበሩት ላይ ከሰማይ ሲያንፀባርቅ አየሁ።'),
  ('127ee8b5-7821-5538-ac61-bfd1184762cc', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 3, 14, 'ሁላችንም በምድር ላይ በወደቅን ጊዜ በዕብራይስጥ ቋንቋ፦ ‘ሳውል ሳውል ለምን ታሳድደኛለህ? በሾለ ብረት ላይ መርገጥ ለአንተ ይብስሃል’ የሚለኝን ቃል ሰማሁ።'),
  ('812eea9e-7734-597d-ab89-994cf881131c', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 4, 15, 'እኔም፦ ‘አቤቱ አንተ ማነህ?’ አልሁ፤ ጌታም አለኝ፦ ‘እኔ አንተ የምታሳድደኝ ኢየሱስ ነኝ።'),
  ('9601a1dd-2a33-54fd-a43c-ea2c1896d957', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 5, 16, 'ነገር ግን ተነሣና በእግርህ ቁም፤ እኔን ባየህበትና ወደፊትም በምታይበት ነገር አገልጋይና ምስክር አድርጌ ልሾምህ ስለዚህ ተገልጬልሃለሁና።'),
  ('ab91d5eb-5032-57c3-aa87-bae50de91415', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 6, 17, 'እኔም ከሕዝቡና ወደ እነርሱ ከምልክህ ከአሕዛብ አድንሃለሁ።'),
  ('d456bdb1-ba27-5e12-aeae-152c7e6fd0a4', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', 'f2334b05-24c9-5e76-a875-9999c9bac41c', 7, 18, 'ይኸውም ዐይናቸውን ትከፍትላቸው ዘንድ፥ ከጨለማም ወደ ብርሃን፥ ሰይጣንን ከማምለክም ወደ እግዚአብሔር ትመልሳቸው ዘንድ፥ ኀጢአታቸውም ይሰረይላቸው ዘንድ፥ በስሜም በማመን ከቅዱሳን ጋር አንድነትን ያገኙ ዘንድ ነው።’'),
  ('2aeac922-60d2-5e40-a5d4-5eda12aabac8', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 1, 19, '“አሁንም ንጉሥ አግሪጳ ሆይ፥ ከሰማይ የተገለጠልኝን ራእይ አልካድሁም።'),
  ('b4b2e8dd-e00a-54eb-a41f-00d08185127b', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 2, 20, 'አስቀድሜ በኢየሩሳሌምና በደማስቆ ላሉት፥ ለይሁዳ አውራጃዎችም ሁሉ ነገርኋቸው፤ ለአሕዛብም ንስሓ ገብተው ወደ እግዚአብሔር ይመለሱ ዘንድ፥ ለንስሓቸውም የሚገባ ሥራን ይሠሩ ዘንድ አስተማርኋቸው።'),
  ('395419e5-1ba4-5e28-aed9-b0ec42cd232e', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 3, 21, 'ሰለዚህም ብቻ አይሁድ በመቅደስ ያዙኝ፤ ሊገድሉኝም ወደዱ።'),
  ('6049df3a-e416-58f2-ac8f-8cf1deb4a5be', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 4, 22, 'እግዚአብሔርም አዳነኝና ለታላቁም፥ ለታናሹም እየመሰከርሁ እስከ ዛሬ ደረስሁ፤ ይደረግ ዘንድ ካለው፥ ነቢያት ከተናገሩት፥ ሙሴም ከተናገረው ሌላ ያስተማርሁት የለም።'),
  ('1aabd535-8c90-5340-a3a8-2c1020be065f', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 5, 23, 'ክርስቶስ እንደሚሞት፥ ከሙታን ተለይቶም አስቀድሞ እንደሚነሣ፥ ለሕዝብና ለአሕዛብ ሁሉ፥ ለመላውም ዓለም እንደሚያበራ።”'),
  ('33fa022e-7976-5116-af10-f0ba3681ce9a', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 6, 24, 'ይህንም ስለ ራሱ ሲናገር ሀገረ ገዢው ፊስጦስ መለሰ፤ ድምፁንም ከፍ አድርጎ፥ “ጳውሎስ ሆይ፥ ልታብድ ነውን? ብዙ ትምህርት እኮ ልብን ይነሣል” አለው።'),
  ('007658c6-ab84-5aa0-a19e-0d90281e6973', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 7, 25, 'ጳውሎስም እንዲህ አለው፥ “ክቡር ፊስጦስ ሆይ፥ እውነትና የተጣራ ነገርን እናገራለሁ እንጂ ዕብደትስ የለብኝም።'),
  ('302d43ee-d597-5c5e-a249-74b398c515e8', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 8, 26, 'በፊቱ ገልጬ የምናገርለት እርሱ ራሱ ንጉሥ አግሪጳ ያውቅልኛል፤ ከዚህም የሚሳተው ነገር ያለ አይመስለኝም፤ ወደ ጎን የተሰወረ አይደለምና።'),
  ('76c41bf4-ce99-52c6-a8f3-11675955e62f', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 9, 27, 'ንጉሥ አግሪጳ ሆይ፥ እነሆ፥ በነቢያት ቃል ታምናለህን? እንደምታምንም አውቃለሁ።”'),
  ('3c844070-8358-5efa-a501-7652a4fc659d', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 10, 28, 'አግሪጳም ጳውሎስን፥ “አሁንስ ወደ ክርስቲያንነት ልታገባኝ ጥቂት ብቻ ቀርቶሃል” አለው።'),
  ('6bc0f9c4-6939-5a96-a573-d64199243f8b', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '2357f865-cfa2-5251-ab85-8dadd124a5ff', 11, 29, 'ጳውሎስም፥ “በጥቂትም ቢሆን፥ በብዙም ቢሆን አንተ ብቻ ሳትሆን ዛሬ የሚሰሙኝ ሁሉ ደግሞ ከዚህ ከእስራቴ በቀር እንደ እኔ እንዲሆኑ ወደ እግዚአብሔር እጸልያለሁ።”'),
  ('132e9893-14c3-57f2-acf0-f336097a417d', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '3d50d8a5-fbc2-55ae-acba-406e3d887a50', 1, 30, 'ከዚህም በኋላ ንጉሡ፥ ሀገረ ገዥውም፥ በርኒቄም፥ ሹሞቻቸውም ተነሡ።'),
  ('a9bef9a9-52fe-52b1-a6fb-9588ebbda3de', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '3d50d8a5-fbc2-55ae-acba-406e3d887a50', 2, 31, 'ለብቻቸውም ገለል ብለው እርስ በርሳቸው እንዲህ ብለው ተነጋገሩ፥ “ይህ ሰው እንዲሞት ወይም እንዲታሰር የሚያበቃ የሠራው በደል የለም።”'),
  ('671c92eb-6492-5c89-ad17-ef7d00cb253b', 'd529fd9b-76d0-5439-a0c2-0c77dab5858a', '3d50d8a5-fbc2-55ae-acba-406e3d887a50', 3, 32, 'አግሪጳም ፊስጦስን፥ “ወደ ቄሣር ይግባኝ ባይል ኖሮ ይህ ሰው ይፈታ ዘንድ በተገባ ነበር” አለው።'),
  ('feee5aff-6693-536a-aa32-b4f250e4ba03', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 1, 1, 'ከዚህም በኋላ ፊስጦስ ወደ ቄሣር ወደ ኢጣልያ በመርከብ እንሄድ ዘንድ ባዘዘ ጊዜ ጳውሎስ ከሌሎች እስረኞች ጋር አብሮ የአውግስጦስ ጭፍራ ለነበረ ዩልዮስ ለሚባል የመቶ አለቃ ተሰጠ።'),
  ('efa52535-7728-5b99-a9d6-160069e03ac9', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 2, 2, 'በተነሣንም ጊዜ ወደ እስያ በምትሄድ በአድራማጢስ መርከብ ተሳፈርን፤ የተሰሎንቄ ሀገር ሰው የሚሆን መቄዶንያዊው አርስጥሮኮስም አብሮን ሄደ።'),
  ('cb18167a-d087-5e29-a8a1-14a36b200041', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 3, 3, 'በማግሥቱም ወደ ሲዶና ደረስን፤ ዩልዮስም ለጳውሎስ አዘነለት፤ ወደ ወዳጆቹ እንዲሄድና በእነርሱ ዘንድ እንዲያርፍም ፈቀደለት።'),
  ('a8a3c88d-055f-5bbe-a0a9-d8a680df704c', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 4, 4, 'ከዚያም ወጥተን ነፋስ ፊት ለፊት ነበርና በቆጵሮስ በኩል ዐለፍን።'),
  ('383f5001-f17d-5fa9-a983-0ed4263018b0', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 5, 5, 'ወደ ኪልቅያና ወደ ጵንፍልያ ባሕርም ገብተን የሉቅያ ክፍል ወደምትሆነው ወደ ሙራ ሄድን።'),
  ('f2b1179b-5054-5a9b-aaad-d0919e9f53d0', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 6, 6, 'በዚያም የመቶ አለቃው ወደ ኢጣልያ የምትሄድ የእስክንድርያን መርከብ አገኘ፤ ወደ እርስዋም አስገባን።'),
  ('b0fa9492-2b19-5e5f-aeac-697124d07190', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 7, 7, 'ብዙ ቀንም እያዘገምን ሄድን፤ በጭንቅም ወደ ቀኒዶስ አንጻር ደረስን፤ ወደዚያም በቀጥታ ለመድረስ ነፋስ ቢከለክለን በቀርጤስ በኩል በሰልሙና ፊት ለፊት ዐለፍን።'),
  ('d9bd8ae0-3e6c-5f44-a26b-97830efe82eb', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 8, 8, 'ባጠገብዋም በጭንቅ ስናልፍ ላሲያ ለምትባለው ከተማ አቅራቢያ ወደ ሆነችው መልካም ወደብ ወደምትባለው ቦታ ደረስን።'),
  ('917d3158-7ff9-5146-a3d8-393164fdf468', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 9, 9, 'በዚያም ብዙ ቀን ቈየን፤ የአይሁድም የጾም ወራት አልፎ ስለ ነበረ በመርከብ ለመሄድ የሚያስፈራ ነበርና ጳውሎስ እንዲህ ብሎ መከራቸው።'),
  ('931783b5-7286-5677-a401-5157a9981a5c', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 10, 10, '“እናንተ ሰዎች ሆይ፥ ስሙኝ፤ ጕዞአችን በብዙ ጭንቀትና በከባድ ጥፋት ላይ ሆኖ አያለሁ፤ ይህንም የምለው ጥፋቱ በራሳችንም ሕይወት እንጂ በጭነቱና በመርከቡ ብቻ ስላልሆነ ነው።”'),
  ('60efdb4b-fcc3-54de-abad-09c0c295e9e5', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 11, 11, 'የመቶ አለቃው ግን ለመርከቡ ባለቤትና ለመሪው ይታዘዝ ነበር፤ የጳውሎስን ቃል ግን አይቀበልም ነበር።'),
  ('b678b24f-58cc-542f-a77d-bffee9d98283', '9ebc4423-c93e-5219-a00b-d4a83696f106', '8c675374-9997-5828-a94a-94dbbdcc65ad', 12, 12, 'ያም ወደብ ክረምቱን ሊከርሙበት የማይመች ነበር፤ ስለዚህም ብዙዎች ከዚያ ይወጡ ዘንድ ይቻላቸው እንደ ሆነ በቀኝ በኩል ወደ አለው ፊንቄ ወደሚባለው ወደ ሁለተኛው የቀርጤስ ወደብ ይደርሱ ዘንድ ወደዱ።'),
  ('2a9ce9ee-882c-552e-a853-0f2526332e0d', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 1, 13, 'ልከኛ የአዜብ ነፋስም ነፈሰ፤ እነርሱም እንደ ወደዱ የሚደርሱ መስሎአቸው ነበር፤ መልሕቁንም አነሡ፤ በቀርጤስም አጠገብ ሄዱ።'),
  ('be96fe19-5cb9-5b57-a57f-4ac9c9497c1f', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 2, 14, 'ከጥቂት ጊዜ በኋላም አውራቂስ የሚሉት ጽኑዕ ዓውሎ ነፋስ መጣ።'),
  ('83d800d6-b705-57c7-a290-7a3e08f9ceba', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 3, 15, 'መርከባችንም ተመትታ ተነጠቀች፤ ቀዛፊዎችም በነፋሱ ፊት ለፊት መቆም አልተቻላቸውምና ተዉአት፤ ብቻዋንም ሄደች።'),
  ('69cd58ce-e860-594b-a6c4-545439017b64', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 4, 16, 'ከዚህም በኋላ ቄዳ ወደምትባል ደሴት እስክንገባ ድረስ ነፋሱ ነፈሰ፤ በጭንቅም ታንኳችንን ለመግታት ቻልን።'),
  ('8299b767-00da-5c1c-a4a7-8144329dbbdf', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 5, 17, 'ከዚህ በኋላ ተጋግዘን በገመድ አጠናከርናት፤ ከዚህም ቀጥሎ ቀዛፊዎች ወደ ጥልቁ ባሕር እንዳይወድቁ በፈሩ ጊዜ ሸራውን አወረዱ፤እንዲሁም እንድንሄድ አደረግን።'),
  ('931b752c-8299-5203-a688-7af51a640bc2', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 6, 18, 'በማግሥቱም ማዕበል ጸናብን፤ ከጭነቱም ወደ ባሕር ጣልን።'),
  ('85b65880-2901-54ac-aee0-974a1fe10e6d', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 7, 19, 'በሦስተኛውም ቀን በመርከብ ያለውን ሁሉ በእጃችን እያነሣን በባሕር ላይ ጣልን።'),
  ('f660bc50-80e4-5e79-a0da-616938884c6f', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'acef7fca-f019-572d-a0e2-5a53a4777efb', 8, 20, 'ብዙ ቀንም ፀሐይንና ጨረቃን ከዋክብትንም ሳናይ ማዕበሉ ጸናብን፤ ለመዳንም ተስፋ ቈርጠን ነበር።'),
  ('f62b0563-71a0-5d21-ab83-3821096f737f', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 1, 21, 'ከእኛም መብል የበላ አልነበረም። ጳውሎስም ተነሥቶ በመካከል ቆመና እንዲህ አላቸው፥ “እናንተ ሰዎች ሆይ፥ ቀድሞ ቃሌን ሰምታችሁኝ ቢሆን ከቀርጤስም ባትወጡ ኖሮ ከዚህ ጕዳትና መከራ በዳናችሁ ነበር።'),
  ('2da11e7a-18e9-5ced-a09d-ed84993d7dce', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 2, 22, 'አሁንም እላችኋለሁ፤ መርከባችን እንጂ ከመካከላችን አንድ ሰው ስንኳ አይጠፋምና አትፍሩ።'),
  ('0994eb79-3bcf-554a-ac9f-d414acaff996', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 3, 23, 'እኔ ለእርሱ የምሆንና የማመልከው እግዚአብሔር የላከው መልአክ በዚች ሌሊት በአጠገቤ ቆሞ ነበርና።'),
  ('711b486a-6482-55ee-a27a-8e75db780633', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 4, 24, 'እርሱም እንዲህ አለኝ፦ ‘ጳውሎስ ሆይ፥ አትፍራ፤ በቄሣር ፊት ልትቆም ይገባሃል፤ ከአንተም ጋር የሚሄዱትን ሁሉ እነሆ፥ እግዚአብሔር ለአንተ ሰጥቶሃል።’'),
  ('f192ced3-1f76-503d-a473-1ee711a5ad47', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 5, 25, 'አሁንም ወንድሞች ሆይ፥ ደስ ይበላችሁ፤ እንደ ነገረኝ እንደሚሆን በእግዚአብሔር አምናለሁና።'),
  ('d47080c2-c055-53a4-acea-82fa4fb089a6', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 6, 26, 'ነገር ግን ወደ አንዲት ደሴት እንደርሳለን።”'),
  ('af897a2f-3b6b-59a7-a3e6-98fab5ac87f6', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 7, 27, 'በዐሥራ አራተኛውም ቀን በመንፈቀ ሌሊት በአድርያ ባሕር ስንጓዝ ቀዛፊዎች ወደ የብሱ የደረሱ መሰላቸው።'),
  ('f56782bc-4e8d-5b3c-a42f-ba08a7999048', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 8, 28, 'መለኪያ ገመድ ጣሉ፤ በሰው ቁመትም ሃያ አገኙ፤ ከዚያም ጥቂት ፈቀቅ ብለው ዳግመኛ ጣሉ፤ በሰው ቁመትም ዐሥራ አምስት አገኙ።'),
  ('aaf01740-250f-584a-a6cc-730d92d15401', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 9, 29, 'ድንጋያማ በሆነ ቦታም እንዳይወድቁ ፈሩ፤ ስለዚህም ከመርከቡ በስተኋላ አራት መልሕቅ በባሕሩ ላይ ጣሉ፤ ፈጥኖ እንዲነጋም ጸለዩ።'),
  ('91e20d4e-55a1-581d-a0d9-82b789bfe372', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 10, 30, 'ከዚህ በኋላም ቀዛፊዎቹ ከመርከብ ሊኮበልሉ በወደዱ ጊዜ ወደ ኋላ ሊመለሱ ከምድር ላይ ሆነው መርከባቸውን የሚያጠናክሩ መስለው ጀልባቸውን ወደ ባሕር አወረዱ።'),
  ('a54529f0-4fe6-5e1d-a519-dfc07ef5bf32', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 11, 31, 'ጳውሎስም ይህን ባየ ጊዜ ለመቶ አለቃውና ለወታደሮቹ፥ “እነዚህ ቀዛፊዎች በመርከብ ውስጥ ከሌሉ መዳን አትችሉም” አላቸው።'),
  ('2f8e03ef-568b-51f4-a82f-15a68b0fd944', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 12, 32, 'ወታደሮችም ወዲያውኑ ተነሥተው የታንኳዪቱን ገመድ ቈርጠው ትወድቅ ዘንድ ተዉአት።'),
  ('b1023604-b337-52d6-aa06-81bca47dcf31', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 13, 33, 'ሊነጋም በጀመረ ጊዜ ጳውሎስ እህል እንዲበሉ ሁሉንም ማለዳቸው፤ እንዲህም አላቸው፥ “እህል ከተዋችሁ ዛሬ ዐሥራ አራት ቀን ነው።'),
  ('3ac88449-b96a-5f07-a02f-a9515002a0be', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 14, 34, 'አሁንም እሺ በሉኝና ምግብ ብሉ፤ ራሳችሁንም አድኑ፥ ከእናንተ ከአንዱ የራስ ጠጕር እንኳ አትጠፋምና።”'),
  ('953ba811-9487-5b32-a584-f585e15e3327', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 15, 35, 'ይህንም ተናግሮ ኅብስቱን አንሥቶ በሁሉም ፊት እግዚአብሔርን አመሰገነ፤ ቈርሶም ይበላ ዘንድ ጀመረ።'),
  ('1adf8cf5-2465-55b0-ade9-e1656d2871ac', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 16, 36, 'ሁሉም ተጽናኑ፤ እህልም ቀመሱ።'),
  ('9ec18e93-c814-5873-ab63-2c7c591ba70d', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 17, 37, 'በመርከቡ ውስጥ የነበሩትም ቍጥራቸው ሁለት መቶ ሰባ ስድስት ነፍስ ነበር።'),
  ('218aec34-dde2-5099-a484-31d7ecfe2d51', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 18, 38, 'በልተውም በጠገቡ ጊዜ በመርከቡ ውስጥ የነበረውን ስንዴ ወደ ባሕር ጣሉት፤ መርከቡንም አቃለሉ።'),
  ('4a652897-2066-5d55-aad4-38e8fbeb73a0', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 19, 39, 'በነጋ ጊዜም ቀዛፊዎች ቦታውን አልለዩም፤ የሚሄዱበትንም አላወቁም፤ ነገር ግን ለባሕሩ አቅራቢያ የሆነውን የደሴት ተራሮች አዩ፤ መርከባቸውንም ወደ እዚያ ሊያስጠጉ ፈለጉ።'),
  ('394a786e-ac3c-5884-a030-59ecd2dfa98d', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 20, 40, 'መልሕቁንም ፈትተው በባሕር ላይ ጣሉት፤ የሚያቆሙበትንም አመቻችተው እንደ ነፋሱ አነፋፈስ መጠን ትንሹን ሸራ ሰቀሉ፤ ወደ ባሕሩ ዳርቻም ሄድን።'),
  ('a08204df-5ccc-5129-a37f-e3451f7c32a3', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 21, 41, 'መርከቢቱም በሁለት ታላላቅ ድንጋዮች መካከል ተቀረቀረች፤ ባሕሩም ጥልቅ ነበረ። ከወደፊቷም ተያዘች፤ አልተንቀሳቀሰችምም፤ ከሞገዱም የተነሣ በስተኋላ በኩል ጎንዋን ተሰብራ ተጐረደች፤ ቀዛፊዎችም ወደፊት ሊገፉአት አልቻሉም።'),
  ('b03e1130-99bb-59fc-a22d-325cbfc303a2', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 22, 42, 'ወታደሮቹም ዋኝተው እንዳያመልጡ እስረኞችን ለመግደል ተማከሩ።'),
  ('a9ba1bb4-0c71-52a4-a970-d1852e920177', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 23, 43, 'የመቶ አለቃው ግን ጳውሎስን ሊያድነው ወድዶአልና ምክራቸውን እንቢ አለ፤ ዋና የሚያውቁትንም ዋኝተው ወደ ምድር እንዲወጡ አዘዛቸው።'),
  ('ecb91d3e-2484-5b75-ae64-572c40ae20d6', '9ebc4423-c93e-5219-a00b-d4a83696f106', 'c41470cc-a70d-5fd5-ad51-ad94d3a24c39', 24, 44, 'የቀሩትም በመርከቡ ስብርባሪ ዕንጨትና በሳንቃው ላይ ተሻገሩ፤ ሌሎችም በመርከቡ ገመድ ላይ እየተንጠላጠሉ ተሻገሩ፤ ሁሉም እንዲህ ባለ ሁኔታ በደኅና ወደ ምድር ደረሱ።'),
  ('45292957-ecad-56f1-a5ec-75230bc205bf', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 1, 1, 'ከዚህም በኋላ በደኅና በደረስን ጊዜ ደሴቲቱ መላጥያ እንደምትባል ዐወቅን።'),
  ('b7d7307f-7de1-5919-a85c-d55c9f78e861', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 2, 2, 'በዚያ የሚኖሩት አረማውያንም አዘኑልን፤ መልካም ነገርንም አደረጉልን፤ ከቍሩም ጽናትና ከዝናሙ ብዛት የተነሣ እሳት አንድደው እንድንሞቅ ሁላችንንም ሰበሰቡን።'),
  ('dcfa3752-b95a-59c7-a2e2-a7dd24a60407', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 3, 3, 'ጳውሎስም ብዙ ጭራሮ ሰብስቦ በእሳቱ ላይ ጨመረው፤ እፉኝትም ከእሳቱ ወላፈን የተነሣ ወጥታ ጳውሎስን እጁን ነደፈችው።'),
  ('c03bd0ff-7101-5a43-acdf-a76ad503fb81', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 4, 4, 'አረማውያንም እፉኝቱ በጳውሎስ እጅ ላይ ተንጠልጥላ ባዩ ጊዜ እርስ በርሳቸው፥ “ይህ ሰው ነፍሰ ገዳይ ይመስላል፤ ከባሕር እንኳ በደኅና ቢወጣም በሕይወት ይኖር ዘንድ የእግዚአብሔር ፍርድ አልተወውም” አሉ።'),
  ('2955d15f-f5e7-59bc-ad97-43081b47299c', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 5, 5, 'ጳውሎስ ግን እጁን አራግፎ እፉኝቱን በእሳት ውስጥ ጣላት፤ ጕዳትም አላገኘውም።'),
  ('a4c92555-5829-55fc-ac3f-990680ea0caf', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 6, 6, 'እነርሱ ግን ወዲያውኑ የሚያብጥ ወይም ሞቶ የሚወድቅ መስሎአቸው ነበር። እያዩትም ብዙ ሰዓት ቆሙ፤ አንዳችም እንደ አልጐዳው በአዩ ጊዜም፥ “ይህስ አምላክ ነው” ብለው ቃላቸውን ለወጡ።'),
  ('e329e045-bb6f-50c0-a518-a7976ad93b06', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 7, 7, 'በዚያ ቦታም አጠገብ ስሙን ፑፕልዮስ የሚሉት የደሴቲቱ አለቃ መሬት ነበር፤ እርሱም ሦስት ቀን ሙሉ በደስታ በቤቱ ተቀብሎ አስተናገደን።'),
  ('83f3fc94-9e5c-58ba-a81e-87ea0d825eeb', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 8, 8, 'የፑፕልዮስም አባት በንዳድና በተቅማጥ ታሞ ተኝቶ ይኖር ነበር፤ ጳውሎስም እርሱ ወዳለበት ገብቶ ጸለየለት፤ እጁንም በላዩ ጭኖ ፈወሰው።'),
  ('b57b06cf-5135-5388-a46f-dbf7ceeff690', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 9, 9, 'ያደረገውንም ይህን ተአምር ባዩ ጊዜ በዚያች ደሴት ያሉትን ድውያን ሁሉ አመጡለት፤ ፈወሳቸውም።'),
  ('b1485a44-489e-5d02-a726-bc4a8956e7f6', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '0177db4a-8129-5141-afcc-3a23235b30af', 10, 10, 'እጅግ ታላቅ ክብርም አከበሩን፤ ከእነርሱም ዘንድ ለመሄድ በተነሣን ጊዜ የሚያስፈልገንን ስንቅ ሰጡን።'),
  ('849c053e-0678-5bc2-a4d8-c07b72c2100e', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', 'e7964741-dbaf-50fa-a291-33831f688b9f', 1, 11, 'ከሦስት ወር በኋላም በዚያች ደሴት ወደ ከረመችው ወደ እስክንድርያ መርከብ ወጣን፤ በዚያች መርከብ ላይም የዲዮስቆሮስ ምልክት ነበረባት፤ ይኸውም “የመርከበኞች አምላክ” የሚሉት ነው።'),
  ('e9a7f5cd-513f-573d-a6e3-31dfcccd4cef', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', 'e7964741-dbaf-50fa-a291-33831f688b9f', 2, 12, 'ከዚያም ሄደን ወደ ሰራኩስ ደረስን፤ በዚያም ሦስት ቀን ተቀመጥን።'),
  ('1d7e170c-1035-5363-a443-6e806d65ae78', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', 'e7964741-dbaf-50fa-a291-33831f688b9f', 3, 13, 'ከዚያም ሄደን ሬቅዩን ወደምትባል ሀገር ደረስን፤ በማግሥቱም ወጣን፤ ከአንድ ቀንም በኋላ ከጐንዋ ነፋስ በነፈሰ ጊዜ በሁለተኛው ቀን ወደ ፑቲዮሉስ ደረስን።'),
  ('faa6b041-f2a7-5b48-a497-d737968441ad', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', 'e7964741-dbaf-50fa-a291-33831f688b9f', 4, 14, 'በዚያም ወንድሞችን አግኝተን ተቀበሉን፤ በእነርሱ ዘንድም ሰባት ቀን እንድንቀመጥ ለመኑን፤ ከዚያም በኋላ ሄደን ወደ ሮሜ ደረስን።'),
  ('3c837494-224d-5741-ab1b-9e449d7f9c97', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', 'e7964741-dbaf-50fa-a291-33831f688b9f', 5, 15, 'በዚያም ያሉት ወንድሞች ስለ እኛ በሰሙ ጊዜ፤ አፍዩስ ፋሩስ እስከሚባለው ገበያና እስከ ሦስተኛው ማረፊያ ድረስ ወጥተው ተቀበሉን፤ ጳውሎስም ባያቸው ጊዜ እግዚአብሔርን አመሰገነ፤ ልቡም ተጽናና።'),
  ('b3cd41a4-d708-533d-a1de-d2ea7d237437', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', 'e7964741-dbaf-50fa-a291-33831f688b9f', 6, 16, 'ወደ ሮሜም በገባን ጊዜ የመቶ አለቃው እስረኞችን ለሠራዊቱ አለቃ አስረከበ፤ ጳውሎስ ግን ከሚጠብቀው አንድ ወታደር ጋር ለብቻው ይቀመጥ ዘንድ ፈቀደለት።'),
  ('e05b0bfd-25b9-5c49-a8ad-fed1c22c7759', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 1, 17, 'ከሦስት ቀንም በኋላ ጳውሎስ የአይሁድን ታላላቅ ሰዎች ሰበሰባቸው፤ በተሰበሰቡም ጊዜ እንዲህ አላቸው፥ “ወንድሞቻችን ሆይ፥ እኔ በሕዝቡም ላይ ቢሆን፥ በአባቶቻችንም ሕግ ላይ ቢሆን ያደረግሁት ክፉ ነገር የለም፤ ነገር ግን በኢየሩሳሌም እንደ ታሰርሁ ለሮም ሰዎች አሳልፈው ሰጡኝ።'),
  ('4541cba6-0141-535a-a38e-d280ae307e87', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 2, 18, 'እነርሱም መርምረው ለሞት የሚያበቃ በደል ስለአላገኙብኝ ሊፈቱኝ ወደዱ።'),
  ('1f118d5f-e862-5e51-a703-d4fd9647480c', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 3, 19, 'አይሁድ ግን ሊቃወሙኝ በተነሡ ጊዜ ወደ ቄሣር ይግባኝ ለማለት ግድ ሆነብኝ፤ ነገር ግን ወገኖችን የምከስበት ነገር ኖሮኝ አይደለም።'),
  ('9d8f295d-e038-5559-a101-9fb8ab787c6d', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 4, 20, 'ስለዚህም ላያችሁ፥ ልነግራችሁና ላስረዳችሁ ወደ እኔ እንድትመጡ ማለድኋችሁ፤ ስለ እስራኤል ተስፋ በዚህ ሰንሰለት ታስሬአለሁና።”'),
  ('05977d7b-d55e-5680-a7ab-0af263dda7cd', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 5, 21, 'የአይሁድ ታላላቅ ሰዎችም እንዲህ አሉት፥ “ለእኛስ ከይሁዳ ሀገር ስለ አንተ መልእክት አልደረሰንም፤ ከኢየሩሳሌም ከመጡት ወንድሞችም ቢሆን አንድ ስንኳ ከዚህ አስቀድሞ ስለ አንተ ክፉ ነገር ያወራን፥ የነገረንም የለም።'),
  ('439af312-f987-54f1-aab1-c77475ff7bfd', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 6, 22, 'ነገር ግን በዚህ ነገር በየስፍራው ሁሉ እንዲጣሉ በእኛ ዘንድ ታውቋልና የአንተን ዐሳብ ደግሞ ከአንተ እንሰማ ዘንድ እንወድዳለን።”'),
  ('7272a7f9-17f8-5eb6-a2a6-b82fbc4c2176', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 7, 23, 'ከዚህም በኋላ ወደ እርሱ የሚመጡበትን ቀን ቀጠሩትና ብዙዎች ወዳረፈበት ወደ እርሱ መጡ፤ ከጥዋትም ጀምሮ እስከ ማታ ድረስ ስለ እግዚአብሔር መንግሥት እየመሰከረ ስለ ጌታችን ስለ ኢየሱስም ከሙሴ ኦሪትና ከነቢያት እየጠቀሰ ነገራቸው።'),
  ('43ef8248-ea22-5bd0-a667-582f65bde915', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 8, 24, 'ከእነርሱም እኩሌቶቹ የተናገረውን አመኑ፤ እኩሌቶቹ ግን አልተቀበሉትም።'),
  ('3934c6f2-867e-5199-ac69-10553e99668a', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 9, 25, 'እርስ በርሳቸውም ባልተስማሙ ጊዜ ጳውሎስ አንዲት ቃል ከተናገረ በኋላ ከእርሱ ተመለሱ፤ እንዲህም አላቸው፥ “መንፈስ ቅዱስ በነቢዩ በኢሳይያስ አንደበት ለአባቶቻችን በእውነት እንዲህ ብሎ መልካም ነገር ተናግሮአል።'),
  ('74a81466-a4bb-5230-a785-df2ad3e3a708', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 10, 26, '‘ወደዚህ ሕዝብ ሂድና እንዲህ በላቸው፦ መስማትን ትሰማላችሁ፤ ግን አታስተውሉም፤ ማየትንም ታያላችሁ፤ ግን አትመለከቱም።'),
  ('ff649ed5-cc07-568f-ae80-1a7b5eab5724', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 11, 27, 'በዐይናቸው እንዳያዩ፥ በጆሮአቸውም እንዳይሰሙ፥ በልባቸውም እንዳያስተውሉ፥ ወደ እኔም እንዳይመለሱና ይቅር እንዳልላቸው የዚህ ሕዝብ ልባቸው ደንድኖአልና፥ ጆሮአቸውም ደንቁሮአልና፥ ዐይናቸውንም ጨፍነዋልና’።'),
  ('89cbf94a-3a00-5f24-a9f8-6a63394797f4', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 12, 28, 'እንግዲህ ከእግዚአብሔር የተገኘች ይህቺ ድኅነት ለአሕዛብ እንደምትሆን ዕወቁ፤ እነርሱም ይሰሙታል።”'),
  ('1f7047c8-ac61-5316-a65a-c232911034d3', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 13, 29, 'ይህንም በተናገራቸው ጊዜ አይሁድ እርስ በርሳቸው እጅግ እየተከራከሩ ወጥተው ሄዱ።'),
  ('6acdccca-79d1-59a3-aac5-c0c07f319e73', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 14, 30, 'ጳውሎስም በገንዘቡ በተከራየው ቤት ሁለት ዓመት ተቀመጠ፤ ወደ እርሱ የሚመጣውንም ሁሉ ይቀበል ነበር።'),
  ('8596f513-e3ee-5d24-ad2a-e9fed784eba6', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 15, 31, 'ማንም ሳይከለክለው የእግዚአብሔርን መንግሥት ይሰብክ ነበር፤ ስለ ጌታችን ስለ ኢየሱስ ክርስቶስም እጅግ ገልጦ ያስተምር ነበር።'),
  ('060ca67f-1968-59ba-a947-bb45e7f97bc5', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 16, 32, 'ጳውሎስም በመጀመሪያ ጊዜ ወደ ኔሮን ቄሣር ገብቶ ነበርና ረትቶ በሰላም ሄደ፤ ከዚህም በኋላ ሁለት ዓመት ኖሮ ከሮም ወጣ።'),
  ('0e3fe55c-c010-5406-aa18-5d2617ea26a5', '9f937bdc-49d7-579a-a3e8-f39ddeebd909', '45ea31c6-5b88-52f9-a7b5-9bb2b782cf20', 17, 33, 'ከዚህም በኋላ ወደ ሮም ተመልሶ የኔሮን ቄሣር ዘመዶችን አጠመቀ፤ በኔሮን ትእዛዝም በሰይፍ ተመትቶ መከራውንም ታግሦ ሰማዕት ሆነ።'),
  ('f8e09bda-e61f-54b1-ae01-de68fd64b1d8', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 1, 1, 'የእግዚአብሔርን ወንጌል ለማስተማር ተለይቶ ከተጠራ ሐዋርያ፥ የጌታችን የኢየሱስ ክርስቶስ አገልጋይ ከሚሆን ከጳውሎስ፥'),
  ('49b43ac0-3910-518b-a8b1-904dcf14eabc', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 2, 2, 'በነቢያቱ ቃልና በቅዱሳት መጻሕፍት አስቀድሞ በተስፋ ያናገረው፥'),
  ('5e4941f9-0250-5528-a7c1-3964aa85931a', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 3, 3, 'ከዳዊት ዘር ሰው ሆኖ በሥጋ ስለ ተወለደ ስለ ልጁ፥'),
  ('ab2b4ea2-8c4e-51fc-ad08-d70b21bc15a5', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 4, 4, 'የእግዚአብሔር ልጅ እንደ ሆነ በኀይሉና በመንፈስ ቅዱስ፥ ከሙታንም ተለይቶ በመነሣቱ ስለ አሳየ ስለ ጌታችን ኢየሱስ ክርስቶስ፥'),
  ('6b5c08ff-c52c-517c-ac16-f1a49c595b05', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 5, 5, 'በስሙ እንዲያምኑ አሕዛብን ልናስተምር ሐዋርያት ተብለን የተሾምንበትና ጸጋን ያገኘንበት፥'),
  ('b211ca91-5828-5980-ae73-660473fed1bd', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 6, 6, 'እናንተም ዛሬ በኢየሱስ ክርስቶስ ለማመን እንደ ተጠራችሁ።'),
  ('cc15c68e-a593-5b74-a931-25d7d371787d', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 7, 7, 'በሮሜ ላላችሁ፥ እግዚአብሔር ለሚወዳችሁ፥ ለመረጣችሁና ላከበራችሁ ሁሉ፥ ከአባታችን ከእግዚአብሔር፥ ከጌታችን ከኢየሱስ ክርስቶስም ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('8b6246c2-88f0-5d19-a035-755f6221b04c', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 8, 8, 'አስቀድሜ ስለ ሁላችሁ በኢየሱስ ክርስቶስ እግዚአብሔርን አመሰግነዋለሁ፤ ማመናችሁ በዓለም ሁሉ ተሰምታለችና።'),
  ('d4eb5ea6-8332-5c08-a67b-09fd3b07bbbd', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 9, 9, 'ባለማቋረጥ በምጸልየው ጸሎት እንደማስባችሁ ልጁ በአስተማረው ወንጌል በፍጹም ልቡናዬ የማመልከው እግዚአብሔር ምስክሬ ነው።'),
  ('e2287c1f-bbe4-5193-ae49-0d9a36c26109', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 10, 10, 'ወደ እናንተ እመጣ ዘንድም እግዚአብሔር በፈቃዱ መንገዴን ያቃናልኝ ዘንድ ዘወትር እጸልያለሁ።'),
  ('0964352a-b85a-5545-aeaf-319374f0e75d', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 11, 11, 'ትጸኑ ዘንድ የመንፈስ ቅዱስን ስጦታ እንድታገኙ ላያችሁ እወዳለሁና፤'),
  ('3a2b91be-2c9c-53f9-a22b-dee5518e0ca6', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 12, 12, 'ይህንም ማለቴ በመካከላችን ባለች በእናንተና በእኔ እምነት አብረን በእናንተ እንድንጽናና ነው።'),
  ('e387aefc-b0ef-51b0-ae2c-a4c21c75d2ca', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 13, 13, 'ነገር ግን ወንድሞቻችን ሆይ፥ በሌሎች አሕዛብ እንደ ሆነ በእናንተም ዋጋዬን አገኝ ዘንድ ሁልጊዜ ወደ እናንተ ልመጣ እንደ ወደድሁ፥ እስከ ዛሬ ድረስም እንደ ተሳነኝ ልታውቁ እወድዳለሁ።'),
  ('8098c719-783b-53f3-a5dd-cf5cd069158c', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 14, 14, 'ለአረማውያንና ላልተማሩ፥ ለጥበበኞችና ለማያስተውሉም ሁሉ አስተምር ዘንድ ዕዳ አለብኝ።'),
  ('c3734683-55e1-5138-a487-78e92f21d394', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 15, 15, 'ይልቁንም በሮሜ ላላችሁ ለእናንተ ወንጌልን ላስተምራችሁ እተጋለሁ።'),
  ('0abc930c-af74-5fc7-aac6-5d10fd5f39b5', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 16, 16, 'ወንጌልን ለማስተማር አላፍርምና፤ አስቀድሞ አይሁዳዊን፥ ደግሞም አረማዊን፥ የሚያምኑበትን ሁሉ የሚያድናቸው የእግዚአብሔር ኀይሉ ነውና።'),
  ('b88ab958-99e2-54da-a8ff-2c3d28ae8025', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', 'ea7b56d4-73e2-57c1-a896-b17b321c35c0', 17, 17, '“ጻድቅ በእምነት ይኖራል” ብሎ መጽሐፍ እንደ ተናገረ የእግዚአብሔር ጽድቅ ከእምነት ወደ እምነት በእርሱ ይገለጣልና።'),
  ('703114b4-0090-51d0-a6dd-d592c48a91c7', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 1, 18, 'እውነትን ዐውቀው በክፋታቸው በሚለውጡአት በዐመፀናውና በኀጢአተናው ሰው ሁሉ ላይ የእግዚአብሔር መቅሠፍት ከሰማይ ይመጣል።'),
  ('5cf6dbb0-07a5-5dc7-a01c-a4acdab141a0', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 2, 19, 'እግዚአብሔር ስለ ገለጠላቸው እግዚአብሔርን ማወቅ በእነርሱ ዘንድ ግልጥ ነውና።'),
  ('735ab8f5-3eee-5692-a347-8ecca2cfe63d', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 3, 20, 'የማይታየው የእግዚአብሔር ባሕርይ እርሱም የዘለዓለም ኀይሉና ጌትነቱ ከዓለም ፍጥረት ጀምሮ የፈጠረውን ፍጥረት በማሰብና በመመርመር ይታወቃል፤ መልስ የሚሰጡበትን ምክንያት እንዳያገኙ።'),
  ('b498d256-2773-553c-a1a1-e9418d17c0fd', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 4, 21, 'እግዚአብሔርን ሲያውቁት እንደ እግዚአብሔርነቱ አላከበሩትም፤ አላመሰገኑትምም፤ ነገር ግን ካዱት፤ በአሳባቸውም ረከሱ፤ ልቡናቸውም ባለማወቅ ጨለመ።'),
  ('a23c2f04-436f-52c6-a3c7-0f6152878fd1', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 5, 22, 'ጥበበኞች ነን ሲሉ አላዋቆች ሆኑ።'),
  ('12f68a7f-60c0-5377-afe5-d11c5702afd6', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 6, 23, 'የማይሞተውን የእግዚአብሔርን ክብር በሚሞት ሰውና በዎፎች፥ አራት እግር ባላቸውም፥ በሚንቀሳቀሱትም መልክ መስለው ለወጡ።'),
  ('7ed3fe4b-8463-5619-a3b4-e120dbee122b', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 7, 24, 'ስለዚህም እግዚአብሔር እርስ በርሳቸው ሥጋቸውን ሊያዋርዱ በልባቸው ፍትወት ወደ ርኵሰት አሳልፎ ተዋቸው።'),
  ('c61a27e9-bc89-5cbb-a6bd-d36f5bc3823c', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 8, 25, 'የእግዚአብሔርን እውነት ሐሰት አድርገዋታልና፤ ተዋርደውም ፍጥረቱን አምልከዋልና፤ ሁሉን የፈጠረውን ግን ተዉት፤ እርሱም ለዘለዓለም ቡሩክ አምላክ ነው፤ አሜን።'),
  ('c9e3c76a-a253-5a7f-a7f6-cd78d268d613', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 9, 26, 'ስለዚህም እግዚአብሔር ክፉ መቅሠፍትን አመጣባቸው፤ ሴቶቻቸውም ለባሕርያቸው የሚገባውን ትተው ለባሕርያቸው የማይገባውን ሠሩ።'),
  ('c43461b6-7425-508d-acec-a3255ee697f9', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 10, 27, 'ወንዶችም እንዲሁ ለባሕርያቸው የሚገባውን ሴቶችን ትተው በፍትወት ተቃጠሉ፤ እርስ በርሳቸውም እየተመላለሱ፥ ወንዶች በወንዶች ላይ የሚያዋርዳቸውን ነውር ሠሩ፤ ነገር ግን ፍዳቸውን ያገናሉ፤ ፍዳቸውም በራሳቸው ይመለሳል።'),
  ('39186118-0c46-5acd-aefd-cea24f756f56', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 11, 28, 'እግዚአብሔርን ለማወቅ ባልወደዱ መጠን እንዲሁ እግዚአብሔር ይህን የማይገባውን ይሠሩ ዘንድ ሰነፍ አእምሮን ሰጣቸው።'),
  ('ee2e4b75-3c36-5ff5-a620-87b2dbcc8956', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 12, 29, 'እነርሱም ዐመፅን ሁሉ፥ ክፋትንም፥ ምኞትንም፥ ቅሚያንም፥ ቅናትንም የተመሉ ናቸው፤ ምቀኞች፥ ነፍሰ ገዳዮች፥ ከዳተኞች፥ ተንኰለኞች፥ ኩሩዎች፥ ጠባያቸውንና ግብራቸውንም ያከፉ ናቸው።'),
  ('e8151367-197e-5f1b-abfe-dd999d34c70e', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 13, 30, 'ሐሜተኞች፥ እግዚአብሔርን የሚጠሉ፥ ተሳዳቢዎች፥ ትዕቢተኞች፥ ትምክሕተኞች፥ ክፋትን የሚፈላለጉ፥ ለወላጆቻቸውም የማይታዘዙ ናቸው።'),
  ('189f9adb-fadd-58a1-afd0-60956b3ce6f4', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 14, 31, 'የማያስተውሉ፥ ዝንጉዎች፥ ፍቅርም፥ ምሕረትም የሌላቸው ናቸው።'),
  ('4195615a-5fd5-5d80-a1cf-e52ad3c6d7ff', 'bf58f51b-b163-5749-aea8-3f3c94ff9510', '75fdfde7-e37b-5ed2-a5a4-6903f7e02d1c', 15, 32, 'ይህን እንዲህ ላደረገ ሞት እንደሚገባው እነርሱ ራሳቸው የእግዚአብሔርን ፍርድ እያወቁ፥ እነርሱ ብቻ የሚያደርጉት አይደለም፤ ነገር ግን ሌላውን ያነሣሡታል፤ ያሠሩታልም።'),
  ('d62b14d5-60cb-544e-a627-1a1ad49ecf19', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 1, 1, 'አንተ ሰው ሆይ፥ እውነት ለሚፈርደው ለእግዚአብሔር ምን ትመልስለታለህ? በወንድምህ ላይ የምትጠላውን ያን ሥራ አንተ ራስህ ከሠራኸው በራስህ የምትፈርድ አይደለምን? አንተ ራስህ ያን ሥራ ትሠራዋለህና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('88a45518-97d6-581b-a330-c02e6f2abc8a', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 2, 2, 'ይህም እንደዚህ በሚያደርጉ ሰዎች ላይ ቅጣት የሚያመጣ የእግዚአብሔር ፍርዱ እውነት እንደ ሆነ እናውቃለን።'),
  ('65092581-aaa4-554b-a7f6-73e606d156c1', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 3, 3, 'አንተ ሰው ሆይ፥ በሌላ ላይ አይተህ የምትጠላውንና የምትነቅፈውን ያን አንተ ራስህ የምትሠራው ከሆነ፥ ከእግዚአብሔር ፍርድ እንደምታመልጥ ታስባለህን?'),
  ('62d6e580-400f-5274-a486-0319e5d1366b', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 4, 4, 'ወይስ በቸርነቱ ብዛት በመታገሡ፥ ለአንተም እሺ በማለቱ እግዚአብሔርን አላዋቂ ልታደርገው ታስባለህን? የእግዚአብሔርስ ቸርነቱ አንተን ወደ ንስሓ እንዲመልስህ አታውቅምን?'),
  ('10c025df-24d6-576c-a960-e5055f6f26de', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 5, 5, 'ነገር ግን ልቡናህን እንደ ማጽናትህ፥ ንስሓም እንደ አለመግባትህ መጠን የእግዚአብሔር እውነተና ፍርድ በሚገለጥበት ቀን መቅሠፍትን ለራስህ ታከማቻለህ።'),
  ('cff8a4f7-2764-5e84-a4e9-8a076aa774ce', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 6, 6, 'እርሱ በእውነተና ፍርዱ ለሁሉ እንደ ሥራው ይከፍለዋልና።'),
  ('64051fc6-5daa-51fc-a55c-02372f298fe8', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 7, 7, 'በበጎ ምግባር ጸንተው ለሚታገሡ፥ ምስጋናና ክብርን፥ የማይጠፋ ሕይወትንም ለሚሹ እርሱ የዘለዓለም ሕይወትን ይሰጣቸዋል።'),
  ('7b3c9c85-c535-58b2-a550-a40bb766ec51', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 8, 8, 'ለሚክዱና እውነትን ለሚለውጡ፥ ዐመፅንም ለሚወድዱ ሰዎች ዋጋቸው ቍጣና መቅሠፍት ነው።'),
  ('c4d82749-3654-546a-aebe-8a15557f05aa', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 9, 9, 'መከራና ጭንቀት አስቀድሞ በአይሁዳዊ፥ ደግሞም በአረማዊ፥ ሥራዉ ክፉ በሆነ ሰው ሁሉ ላይ ነው።'),
  ('291cb002-ab7d-5840-a71e-f87cff96921b', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 10, 10, 'ምስጋናና ክብር፥ ሰላምም አስቀድሞ ለአይሁዳዊ፥ ደግሞም ለአረማዊ፥ ሥራዉ መልካም ለሆነ ሁሉ ነው።'),
  ('54bd1840-e7f9-5254-a618-76b09161a16f', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 11, 11, 'እግዚአብሔር ለሰው ፊት አያዳላምና።'),
  ('b685228c-882c-54a8-a525-4951a65072b2', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 12, 12, 'ከሕግ ወጥተው የበደሉ በሕግ ይፈረድባቸዋል፤ ያለ ሕግ የበደሉ ሁሉም ያለ ሕግ ይፈረድባቸዋል።'),
  ('b95c830d-2bf1-5955-a9e1-ee3bc44cb0cb', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 13, 13, 'በእግዚአብሔር ፊት ሕግን የሚያደርጉ ይጸድቃሉ እንጂ ሕግን የሚሰሙ አይጸድቁምና።'),
  ('4bb1b8d7-df84-5603-ac92-f921708b8539', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 14, 14, 'ሕግ የሌላቸው አሕዛብስ እንኳ ለራሳቸው ሕግ ይሠራሉ፤ ራሳቸው ለራሳቸው ሕግን ይደነግጋሉ፤ በሕጋቸው የታዘዘውንም ያደርጋሉ።'),
  ('b59e3ba4-6544-5701-a01d-261c2138b798', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 15, 15, 'በልባቸው የተጻፈውን የሕግ ሥራ ያሳያሉ፤ ከሥራቸውም የተነሣ ይታወቃል፤ ሕሊናቸውም ይመሰክርባቸዋል፤ ይፈርድባቸዋልም።'),
  ('c57e76f8-54e5-5ac1-a1ea-3410b66f354a', '71144602-d487-5c11-af86-a458d6e21f0b', '7ebe3016-32cc-59e2-acd2-4a4c4b68dc6d', 16, 16, 'ይህም እግዚአብሔር በኢየሱስ ክርስቶስ እኔ በወንጌል እንዳስተማርሁ ሰዎችን በልቡናቸው የሰወሩትንና የሸሸጉትን በሚመረምርበት ጊዜ የሚናገሩትና የሚመልሱት እንደሌለ ስለሚያውቁ ነው።'),
  ('f458ec63-1094-5eb5-a964-46bc4a0854cf', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 1, 17, 'አንተ አይሁዳዊ፥ በኦሪትህ የምታርፍ፥ በእግዚአብሔርም የምትመካ ከሆንህ፥'),
  ('c23cecb7-f588-5436-a154-d74ffdceeae7', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 2, 18, 'ፈቃዱን የምታውቅ፥ መልካሙንም የምትለይ፥ ኦሪትንም የተማርህ ከሆንህ፥'),
  ('65c7e85c-f8d2-5a0b-aff7-d38e65c717a2', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 3, 19, 'አንተ የዕውሮች መሪ፥ በጨለማም ላሉት ብርሃን እንደ ሆንህ በራስህ የምትታመን ከሆንህ፥'),
  ('d7929091-a32c-57a9-a8d3-80133b021b6e', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 4, 20, 'ሰነፎችን ልባሞች የምታደርግ፥ ሕፃናትን የምታስተምር፥ ጻድቅና የምትከብርበትን የኦሪትን ሕግ የምታውቅ የምትመስል፥'),
  ('fd2d8abe-179a-5c11-a57a-db8bd5c37d46', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 5, 21, 'እንግዲህ ሌላውን የምታስተምር ራስህን እንዴት አታስተምርም? አትስረቁ ትላለህ፤ ነገር ግን አንተ ራስህ ትሰርቃለህ።'),
  ('da6ce402-8745-56d9-acdc-b842b013ce89', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 6, 22, 'አታመንዝሩ ትላለህ፤ ነገር ግን አንተ ራስህ ታመነዝራለህ፤ ወደ ጐልማሳ ሚስትም ትሄዳለህ፤ ጣዖትን ትጸየፋለህ፤ አንተ ግን ቤተ መቅደስን ትዘርፋለህ።'),
  ('75254d5d-6748-5c48-ae5f-6d2de11dce05', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 7, 23, 'በኦሪት ትመካለህ፤ ነገር ግን አንተ ራስህ ኦሪትን በመሻር እግዚአብሔርን ታቃልለዋለህ።'),
  ('dcd34133-eb13-539c-a031-4591f4a08550', '71144602-d487-5c11-af86-a458d6e21f0b', '134e179c-80ca-5508-a5b4-7d99541161a6', 8, 24, 'እንደ ተጻፈም “እነሆ፥ በእናንተ ምክንያት አሕዛብ የእግዚአብሔርን ስም ይሰድባሉ።”'),
  ('1d23fd7a-c5c9-5751-a83b-bdfbb9a3ccb1', '71144602-d487-5c11-af86-a458d6e21f0b', '644e56a6-94c7-596d-af38-bd1036ffb1f0', 1, 25, 'ኦሪትንም ብትፈጽም ግዝረት ትጠቅምሃለች፤ ኦሪትን ባትፈጽም ግን ግዝረትህ አለመገዘር ትሆንብሃለች።'),
  ('488d086c-ce89-5be2-a4bb-cc9aed115189', '71144602-d487-5c11-af86-a458d6e21f0b', '644e56a6-94c7-596d-af38-bd1036ffb1f0', 2, 26, 'አንተ ሳትገዘር ብትኖር፥ ኦሪትንም ብትጠብቅ አለመገዘርህ መገዘር ትሆንልሃለች።'),
  ('1073a34d-c657-51e8-a758-dfcd07788c75', '71144602-d487-5c11-af86-a458d6e21f0b', '644e56a6-94c7-596d-af38-bd1036ffb1f0', 3, 27, 'ተገዝረህ ኦሪትን ከምታፈርስ በተፈጥሮ ያገኘሃት አለመገዘርህ አብራህ ብትኖር ይሻልሃል፤ ኦሪትን ከምታፈርስ ከአንተ ከተገዘርኸው ያ ያልተገዘረው፥ ኦሪትን የሚፈጽመው ይሻላል።'),
  ('0ed3e9de-ebcf-5c92-a804-725243f0544a', '71144602-d487-5c11-af86-a458d6e21f0b', '644e56a6-94c7-596d-af38-bd1036ffb1f0', 4, 28, 'በውኑ ለሰው ይምሰል አይሁዳዊ መሆን ይገባልን? ለሰው ፊትስ ተብሎ ይገዘሩአልን?'),
  ('f3470af0-027f-51df-a3cd-1d44f8ccd664', '71144602-d487-5c11-af86-a458d6e21f0b', '644e56a6-94c7-596d-af38-bd1036ffb1f0', 5, 29, 'ዳሩ ግን አይሁዳዊነት በስውር ነው፤ መገዘርም በመንፈስ የልብ መገዘር እንጂ በኦሪት ሥርዐት አይደለም፤ ምስጋናውም ከእግዚአብሔር ነው እንጂ ከሰው አይደለም።'),
  ('07e4ebcb-f21b-543a-a158-2ee592f9de31', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 1, 1, 'እንግዲህ አይሁዳዊ የመባል ትርፉ ምንድን ነው? የግዝረትስ ጥቅምዋ ምንድን ነው?'),
  ('6577609b-6ff3-5945-ab70-9f002882f303', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 2, 2, 'በሁሉ ነገር ብዙ ነው፤ ነገር ግን ከዚያ አስቀድሞ የእግዚአብሔር ቃል አደራ ተሰጣቸው።'),
  ('5b8f1b74-4cdf-5695-a090-da003709c859', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 3, 3, 'የማያምኑ ቢኖሩስ የእነርሱ አለማመን ሌላውን በእግዚአብሔር እንዳያምን ይከለክላልን? አይከለክልም።'),
  ('38332575-5961-53b8-a382-0468f690c11c', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 4, 4, 'መጽሐፍ፥ “በነገርህ ትጸድቅ ዘንድ፥ በፍርድህም ታሸንፍ ዘንድ” ብሎ እንደ ተናገረ እግዚአብሔር እውነተና ነውና፥ ሰውም ሁሉ ሐሰተና ነውና።'),
  ('c6c42a11-7374-55c9-a203-a778abb3da76', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 5, 5, 'በእኔ ኀጢአት የእግዚአብሔር ጽድቅ ከጸና እንግዲህ ምን እንላለን? እግዚአብሔር በሰው ላይ ቅጣትን ቢያመጣ ይበድላልን? አይበድልም፤ የምናገረውንም በሰው ልማድ እናገራለሁ።'),
  ('a591a987-f531-5adc-a939-2cdca91aa276', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 6, 6, 'እንዲህማ ከሆነ እግዚአብሔር በዓለም እንደምን ይፈርዳል?'),
  ('36aeac8e-7374-53af-abe5-363407a13359', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 7, 7, 'የእግዚአብሔር እውነት በእኔ ሐሰተናነት ለክብሩ ከፍ ከአለ እንግዲህ እኔን እንደ ኀጢአተና ለምን ይፈርድብናል?'),
  ('7c39e347-36b4-5a1a-aa8e-70096995f519', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 8, 8, 'በውኑ እና መልካም ነገር እናገኝ ዘንድ ክፉ ነገር እናድርግ እንደምንል አስመስለው የሚጠረጥሩንና የሚነቅፉን ሰዎች እንደሚሰድቡን ነን? ለእነርሱስ ቅጣታቸው ተዘጋጅቶላቸዋል።'),
  ('ed57d4b7-08cc-592d-a390-56debfc9ef83', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 9, 9, 'እንግዲህ ምን እንላለን? ከእነርሱ እንበልጣለን? አይደለም፤ አይሁዳዊንም፥ አረማዊንም እነሆ፥ አስቀድመን ነቅፈናቸዋል፤ ሁሉም ስተዋልና።'),
  ('f4c2b3f0-e35f-51bc-aea7-f116cb9c57ef', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 10, 10, 'መጽሐፍ እንዲህ እንዳለ “አንድ ስንኳ ጻድቅ የለም።'),
  ('b6092edb-7522-5ded-a2d5-44db088581ca', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 11, 11, 'አስተዋይም የለም፤ እግዚአብሔርንም የሚሻው የለም።'),
  ('0c44aed6-de6e-52fc-ac48-fb0a9cc1fa5b', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 12, 12, 'ሁሉም ተባብሮ በደለ፤ በጎ ሥራንም የሚሠራ የለም፤ አንድ ስንኳ ቢሆን የለም።'),
  ('8a68434d-5424-5f37-af1f-d2e40bb11552', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 13, 13, 'ጕረሮአቸው እንደ ተከፈተ መቃብር ነው፤ በአንደበታቸውም ሸነገሉ፤ ከከንፈሮቻቸውም በታች የእባብ መርዝ አለ፤'),
  ('06b1500f-75bd-5952-ae76-212c51d4abbd', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 14, 14, 'አፋቸው መራራ ነው፤ መርገምንም የተሞላ ነው።'),
  ('f25630e1-0bb0-5753-acab-4f084a3c81bb', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 15, 15, 'እግሮቻቸውም ደምን ለማፍሰስ ፈጣኖች ናቸው።'),
  ('1843a5a7-47f6-5f2b-a14d-f6071acc2e40', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 16, 16, 'በመንገዳቸው ጥፋትና ጕስቍልና አለ።'),
  ('e0a57537-ec2c-5293-af0f-178e6bb1de75', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 17, 17, 'የሰላምን መንገድ አያውቋትም።'),
  ('01ddec17-fdcc-5bc2-aad5-c7bb94743aad', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 18, 18, 'በዐይኖቻቸውም ፊት እግዚአብሔርን መፍራት የለም።”'),
  ('3ddc3d76-1847-5618-a5a6-3e2153e51b84', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 19, 19, 'አንደበት ሁሉ ይዘጋ ዘንድ፥ ዓለምም ሁሉ ከእግዚአብሔር ፍርድ በታች ይሆን ዘንድ ኦሪት የሚናገረው ሁሉ በኦሪት ላሉት እንደ ተነገረ እናውቃለን።'),
  ('0244d4cf-dbc9-5d27-aad9-d6aa61c97041', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 20, 20, 'ከኦሪት የተነሣ ኀጢአት ስለ ታወቀች ሰው ሁሉ የኦሪትን ሥርዐት በመፈጸም በእግዚአብሔር ፊት አይጸድቅም።'),
  ('89355bf6-999a-5c3b-ab4a-7014205f352f', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 21, 21, 'አሁን ግን በኦሪትና በነቢያት የተመሰከረላት የእግዚአብሔር ጽድቅ ያለ ኦሪት ተገለጠች።'),
  ('0abc5a0d-99b6-5ec1-a326-fa923b3bdbcd', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 22, 22, 'የሚያምኑበት ሁሉ ኢየሱስ ክርስቶስን በማመን በእግዚአብሔር ዘንድ ይጸድቃሉ።'),
  ('1428f50f-2534-5d79-a8eb-68c2b4ec9414', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 23, 23, 'በዚህም ልዩነት የለም፤ ሁሉም ፈጽመው በድለዋልና፤ እግዚአብሔርን ማክበርንም ትተዋልና።'),
  ('c9d86bd9-7f64-5672-a653-a049989028fc', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 24, 24, 'ጽድቅ ግን በኢየሱስ ክርስቶስም ቤዛነት ያለ ዋጋ በእርሱ ቸርነት ሆነ።'),
  ('3ce2a0c5-18e5-5034-a225-5b93303dfd18', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 25, 25, 'እርሱንም እግዚአብሔር በእምነት የሚገኝ፥ በደሙም የሆነ ማስተስረያ አድርጎ አቆመው፤ ይህም ከጥንት ጀምሮ በበደሉት ላይ ጽድቁን ይገልጥ ዘንድ ነው።'),
  ('f27821c9-df79-529e-a0e1-2d81d2a07238', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 26, 26, 'እግዚአብሔር ታጋሽ በመሆኑ፥ እሺ በማለቱም እርሱ ጻድቅ እንደ ሆነ፥ በኢየሱስ ክርስቶስም የሚያምኑትን እንደሚያጸድቃቸው ዛሬ ያውቁ ዘንድ ነው።'),
  ('72394645-6b23-5456-a863-7bcf5c394469', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 27, 27, 'ትምክሕት ወዴት አለ? እርሱ ቀርቶአል፤ በየትናውስ ሕግ ነው? በሥራ ሕግ ነውን? አይደለም፤ በእምነት ሕግ ነው እንጂ።'),
  ('fe1e864b-5f56-54a6-ae02-230f5f01e53e', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 28, 28, 'ሰው የኦሪትን ሥራ ሳይሠራ በእምነት እንዲጸድቅ እናውቃለንና።'),
  ('e70aa349-be7f-5cb9-a3a7-611392b6bd9e', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 29, 29, 'በውኑ እግዚአብሔር ለአይሁድ ለብቻቸው ነውን? ለአሕዛብስ አይደለምን?'),
  ('63de90c8-c88b-5ddb-a2a2-4ca713fde6f1', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 30, 30, 'አዎን፥ ለአሕዛብም ነው፤ የተገዘረውን በእምነት የሚያጸድቅ፥ ያልተገዘረውንም በእምነት የሚያጸድቀው እርሱ አንዱ እግዚአብሔር ነውና።'),
  ('02cffb79-c724-5e04-a5fc-7b953747e428', 'ecdfaf3a-d5d0-5559-ad8a-76f856bf3363', 'adeec868-937e-5292-a9a8-874845c85e3f', 31, 31, 'እንግዲህ በእምነት ኦሪትን እንሽራለን? አንሽርም፤ ኦሪትን እናጸናለን እንጂ።'),
  ('41e73124-8ae5-51cd-affd-73069a380d91', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 1, 1, 'እንግዲህ በሥጋ የቀድሞ አባታችን የሆነው አብርሃም ምን አገኘ እንላለን? ይህን በሥራው አግኝቶአልን?'),
  ('d1a44064-48e5-5b1c-aa37-56f7eec5ae32', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 2, 2, 'አብርሃም በሥራው ጸድቆስ ቢሆን ትምክሕት በሆነው ነበር፤ ነገር ግን በእግዚአብሔር ዘንድ አይደለም።'),
  ('c58522e1-c554-5a8b-a87e-9fd91f63edbd', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 3, 3, 'መጽሐፍስ ምን ይላል? አብርሃም በእግዚአብሔር አመነ፤ ጽድቅም ሆኖ ተቈጠረለት።'),
  ('dc8df227-ae4b-50c0-af9b-b8b22d1d8a75', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 4, 4, 'ለሚሠራ ዋጋው እንደሚገባው እንጂ በለጋስነት እንደ ሰጡት ሆኖ አይቈጠርበትም።'),
  ('5bf872c0-53a4-5ad6-a333-d8cbace8dda1', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 5, 5, 'ለማይሠራ ግን ኀጢአተናውን በሚያጸድቀው ካመነ እምነቱ ጽድቅ ሆኖ ይቈጠርለታል።'),
  ('78ce12a4-ad81-5584-a7da-812f28663e7a', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 6, 6, 'የኦሪትን ሥራ ሳይፈጽም ማመኑ በእግዚአብሔር ዘንድ ጽድቅ ሆኖ የሚቈጠርለትን ሰው ዳዊት “ብፁዕ” በሚልበት አንቀጽ እንዲህ ይላል፦'),
  ('8a11dc41-ff4a-5de6-a5fe-a769c4aaa88c', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 7, 7, '“መተላለፋቸው የቀረላቸው፥ ኀጢአታቸውም የተሰረየላቸው ብፁዓን ናቸው።'),
  ('8d9adc37-d898-57b9-adca-25399c6490df', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 8, 8, 'እግዚአብሔርም በደሉን የማይቈጥርበት ሰው ብፁዕ ነው።”'),
  ('fa5e53fd-3ddd-56d8-a833-0f068edb8a96', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 9, 9, 'እንግዲህ ይህ ብፅዕና ስለ መገዘር ተነገረን? ወይስ ስለ አለመገዘር? እምነቱ ለአብርሃም ጽድቅ ሆኖ ተቈጠረለት እንላለንና።'),
  ('39a8be02-9719-569c-af8e-c96992f3af5f', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 10, 10, 'ለአብርሃም ጽድቅ ሆኖ የተቈጠረለት መቼ ነው? ተገዝሮ ሳለ ነውን? ወይስ ሳይገዘር? ሳይገዘር ነው እንጂ ተገዝሮ ሳለ አይደለም።'),
  ('28909628-4229-5fb9-ab84-37aaad8cc549', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 11, 11, 'ሳይገዘር እግዚአብሔር አብርሃምን በእምነት እንደ አጸደቀው በእርሱ ላይ ይታወቅ ዘንድ ግዝረትን የጽድቅ ማኅተም ትሆነው ዘንድ ምልክት አድርጎ ሰጠው። ሳይገዘሩ ለሚያምኑ ሁሉ አባት ሊሆን፥ አብርሃም በእምነት እንደ ከበረ እነርሱም በእምነት እንደሚከብሩ ያውቁ ዘንድ ሰጠው።'),
  ('5474aca4-aed6-54fc-a8ad-36af65cd5e4e', '940429f4-d580-5633-a8ce-f35de7c66fd1', '3c61c3e2-09f2-5b3b-a26f-e2033c712ec9', 12, 12, 'ለተገዘሩትም አባት ይሆን ዘንድ ነው፤ ነገር ግን ለተገዘሩት ብቻ አይደለም፤ እርሱ አባታችን አብርሃም ሳይገዘር እንደ አመነ ሳይገዘሩ የአባታችን የአብርሃምን የሃይማኖቱን ፍለጋ ለሚከተሉ ደግሞ ነው እንጂ።'),
  ('2dbb5579-61f8-5d57-af75-f069b64ec686', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 1, 13, 'አብርሃም፥ ዘሩም ዓለምን ይወርስ ዘንድ ተስፋ ያገኘ የኦሪትን ሥራ በመሥራት አይደለም፤ በእግዚአብሔር ቃል፥ እርሱንም በማመን በእውነተና ሃይማኖቱ ይህን አገኘ እንጂ።'),
  ('b790758a-67db-5512-af1c-419c336c6b94', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 2, 14, 'የኦሪትን ሕግ የፈጸመ ብቻ ተስፋ የሚያገኝ፥ ዓለምንም የሚወርስ ቢሆን ኖሮ፥ ለአብርሃም እምነቱ ባልጠቀመውም ነበር፤ ተስፋውንም ባላገኘም ነበር።'),
  ('c1c39713-e496-5223-ac32-37071e861910', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 3, 15, 'የኦሪት ሕግ በአፍራሹ ላይ ቅጣትን ያመጣልና፤ የኦሪት ሕግም ከሌለ መተላለፍ የለም።'),
  ('e2b3b7b3-4263-5953-a42a-ab391cc546cd', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 4, 16, 'ስለዚህም እግዚአብሔር ለአብርሃምና ለዘሩ የሰጠው ተስፋ የታመነ ይሆን ዘንድ፥ የሚጸድቁ በእምነት እንጂ የኦሪትን ሥራ በመፈጸም ብቻ እንዳይደለ ያውቁ ዘንድ እግዚአብሔር ጽድቅን በእምነት አደረገ።'),
  ('c900238a-72d7-5cad-a0e0-45035e7f4442', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 5, 17, '“ለብዙዎች አሕዛብ አባት አደርግሃለሁ” ተብሎ እንደ ተጻፈ ሙታንን በሚያስነሣቸው፥ የሌሉትንም እንደ አሉ በሚያደርጋቸው በአመነበት በእግዚአብሔር ፊት አብርሃም የሁላችን አባት ነው።'),
  ('7d7454cd-ef31-52d4-aba6-47523d779406', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 6, 18, 'አብርሃም “ዘርህ እንዲሁ ይሆናል” ብሎ እግዚአብሔር ተስፋ እንደ ሰጠው ተስፋ ባልነበረ ጊዜ የብዙዎች አሕዛብ አባት እንደሚሆን አመነ።'),
  ('bae9b589-43c3-5906-a03a-7aa112cea071', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 7, 19, 'አብርሃም የመቶ ዓመት ሽማግሌ ስለሆነ እንደ ምውት የሆነውን የራሱን ሥጋና የሣራ ማኅፀን ምውት መሆኑን እያየ በእምነት አልተጠራጠረም።'),
  ('d71d240b-c954-5224-a04e-c92a3f348f5d', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 8, 20, 'እግዚአብሔር ያናገረለትንም ተስፋ ይቀራል ብሎ አልተጠራጠረም፤ በእምነት ጸና እንጂ፤ ለእግዚአብሔርም ክብርን ሰጠ።'),
  ('35885df6-744d-5cc9-a69b-ae9c4c538874', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 9, 21, 'እግዚአብሔርም የሰጠውን ተስፋ ሊያደርግለት እንደሚችል በፍጹም ልቡ አመነ።'),
  ('f883c0b8-b8e1-5bfe-aa4a-610655202c47', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 10, 22, 'ስለዚህም ጽድቅ ሆኖ ተቈጠረለት።'),
  ('cc1d3d5d-92be-5ce0-a6f8-31fb803ec924', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 11, 23, 'ነገር ግን “ጽድቅ ሆኖ ተቈጠረለት” የሚለው ቃል የተጻፈ ስለ እርሱ ብቻ አይደለም።'),
  ('85adb0fb-c71a-5640-ac61-2e0a3b421608', '940429f4-d580-5633-a8ce-f35de7c66fd1', '9ec51857-65ae-596f-a5d8-a0e367d136bb', 12, 24, 'ስለ ኀጢአታችን የተሰቀለውን፥ ሊያስነሣንና ሊያጸድቀን የተነሣውን ጌታችንን ኢየሱስን ከሙታን ለይቶ በአስነሣው ስለምናምን ስለ እናም ነው እንጂ።'),
  ('10595d6b-d5b9-5358-a9e6-2a01ed6d6b23', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 1, 1, 'እንግዲህ በእምነት ከጸደቅን፥ በእግዚአብሔር ዘንድ በጌታችን በኢየሱስ ክርስቶስ ሰላምን እናገናለን።'),
  ('1f7ce3a9-a879-526a-a5a6-a607b82d7c55', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 2, 2, 'በእርሱም አማካኝነት ወደቆምንበት ወደ ጸጋው በእምነት ተመራን፤ በእግዚአብሔርም ክብር ተስፋ እንመካለን።'),
  ('7c82b12b-a8f9-5942-ae8f-581fb9eb34ee', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 3, 3, 'የምንመካ በእርስዋ ብቻ አይደለም፤ በመከራችን ደግሞ እንመካለን እንጂ፤ መከራ በእና ላይ ትዕግሥትን እንደሚያመጣ እናውቃለንና።'),
  ('7eeeaa49-4cbb-5f87-a653-939f85ff2823', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 4, 4, 'ትዕግሥትም መከራ ነው፤ በመከራም ተስፋ ይገናል።'),
  ('ab7faaf1-8d0f-5d4e-aee4-eb12c9b73984', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 5, 5, 'ተስፋም አያሳፍርም፤ በሰጠን በመንፈስ ቅዱስ የእግዚአብሔር ፍቅር በልባችን መልቶአልና።'),
  ('7c4d832b-c322-511f-a7cf-2e9e37c2b3ff', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 6, 6, 'ክርስቶስም እና ኀጢአተኞች ስንሆን ስለ ኀጢአታችን ይሞት ዘንድ ዘመኑ ሲደርስ መጣ።'),
  ('c0a45120-04a9-563b-a138-28cadfc789d3', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 7, 7, 'ስለ ክፉዎች በጭንቅ ጊዜ ስንኳ ቢሆን ሊሞት የሚደፍር አይገኝም፤ ስለ ደጋጉ ግን ሊሞት የሚጨክን የሚገኝ እንዳለ እንጃ።'),
  ('a8fdef44-a36e-5be8-a0d5-aa212dda8b8f', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 8, 8, 'እግዚአብሔር ምን ያህል እንደ ወደደን እነሆ፥ እዩ፤ እና ኀጢአተኞች ስንሆን ክርስቶስ ስለ እና ሞተ።'),
  ('26d8e209-ddd7-5b7b-a6ca-834e6401c8a9', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 9, 9, 'እንግዲህ በደሙ ዛሬ ከጸደቅን ከሚመጣው መከራ በእርሱ እንድናለን።'),
  ('d8e5a007-bdd8-5131-a1d1-d39a9a211467', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 10, 10, 'እና የእግዚአብሔር ጠላቶቹ ስንሆን በልጁ ሞት ይቅር ካለን፥ ከታረቀን በኋላም በልጁ ሕይወት እንዴት የበለጠ ያድነን!'),
  ('0e4af893-adc6-5042-a5b3-5bed25d8bc89', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', '0b4b28b7-1c51-5739-ae69-44b0b4fe734d', 11, 11, 'በዚህ ብቻ አይደለም፤ በእርሱ ይቅርታውን ባገኘንበት በጌታችን በኢየሱስ ክርስቶስም በእግዚአብሔር ዘንድ እንመካለን እንጂ።'),
  ('9b33addd-2072-549a-a072-b79c01bfa358', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 1, 12, 'ስለዚህም በአንድ ሰው በደል ምክንያት ኀጢአት ወደ ዓለም ገባች፤ ስለዚችም ኀጢአት ሞት ገባ፤ እንደዚሁም ሁሉ ኀጢአትን ስለ አደረጉ በሰው ሁሉ ላይ ሞት መጣ።'),
  ('9fc35d58-2730-59cf-af25-50a2048f3965', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 2, 13, 'ኦሪት እስከ መጣች ድረስ ኀጢአት ምን እንደ ሆነች ሳትታወቅ በዓለም ውስጥ ነበረች፤ ነገር ግን የኦሪት ሕግ ገና ስላልመጣ ኀጢአት ተብላ አትቈጠርም ነበር።'),
  ('79da19e8-e1ee-5199-a736-a936931344fa', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 3, 14, 'ነገር ግን በአዳም ኀጢአት ምክንያት ከአዳም እስከ ሙሴ የበደሉትንም ያልበደሉትንም ሞት ገዛቸው፤ ሁሉ በአዳም አምሳል ተፈጥሮአልና፥ አዳምም ይመጣ ዘንድ ላለው ለእርሱ አምሳሉ ነውና።'),
  ('2cc574ca-11b3-54ad-a1ff-b54a5872c0f5', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 4, 15, 'ነገር ግን የእግዚአብሔር ጸጋው በበደላችን መጠን የሆነብን አይደለም፤ በአንድ ሰው በደል ብዙዎች ከሞቱ፥ እንግዲህ በእግዚአብሔር ጸጋ፥ በአንዱ ሰው በኢየሱስ ክርስቶስ ቤዛነት በሰጠን ሀብቱ ሕይወት በብዙዎች ላይ እንዴት እጅግ ይበዛ ይሆን?'),
  ('751c9b54-ea38-5a5d-a735-89a94c063e29', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 5, 16, 'የእግዚአብሔር ጸጋው በአንዱ ሰው ኀጢአት መጠን የሆነብን አይደለም፤ የኀጢአት ፍርድ ከአንድ ሰው ወጥታ ሁሉ ከተቀጣባት፥ ጸጋው ከበደላችን እንደ ምን ያነጻን ይሆን? የዘለዓለምንስ ሕይወት እንዴት ይሰጠን ይሆን?'),
  ('e91c1ae9-ecde-5d9a-a636-7035404fe41b', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 6, 17, 'የአንዱ ሰው ኀጢአት ሞትን ካነገሠችው በአንድ ሰው በደልም ሞት ከገዛን፥ የአንዱ ሰው የኢየሱስ ክርስቶስ የጸጋው ብዛትና የጽድቁ ስጦታ እንዴት እጅግ ያጸድቀን ይሆን? የዘለዓለም ሕይወትንስ እንዴት ያበዛልን ይሆን?'),
  ('76d3b051-5c12-54dd-a024-a1ac97066504', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 7, 18, 'እንግዲህ በአንዱ ሰው በደል ዓለም ሁሉ እንደ ተፈረደበት፥ እንዲሁ ደግሞ በአንዱ ሰው ጽድቅ ሰው ሁሉ ይጸድቃል።'),
  ('9adcf615-5f4f-5df5-ac71-076010b1d2b0', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 8, 19, 'በአንድ ሰው አለመታዘዝ ብዙዎች ኀጢአተኞች እንደ ሆኑ፥ እንዲሁ ደግሞ በአንድ ሰው መታዘዝ ብዙዎች ጻድቃን ይሆናሉ።'),
  ('69124c93-ab8a-581a-a397-1308c775fdca', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 9, 20, 'ኦሪትስ ኀጢአትን ታበዛት ዘንድ መጣች፤ ኀጢአትም ከበዛች ዘንድ የእግዚአብሔር ጸጋ በዛች።'),
  ('3f7fd396-5b12-5260-a6ad-cb1f4ddff67d', 'f4e16d4f-4044-55ff-a679-2555a8b2f4d7', 'e7fa97fc-c1cf-5151-a6a9-393c60aa5759', 10, 21, 'ኀጢአትም ሞትን እንደ አነገሠችው እንዲሁ በጌታችን በኢየሱስ ክርስቶስ የእግዚአብሔር ጸጋ ጽድቅን ለዘለዓለም ሕይወት ታነግሠዋለች።'),
  ('c012e65c-01de-5759-a9f0-1cc5f15b8822', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 1, 1, 'እንግዲህ ምን እንላለን? የእግዚአብሔር ጸጋ እንዲበዛ ኀጢአት እንሥራን? አይደለም።'),
  ('673da1ea-48da-54f7-a8d3-2c72c1cc0bf4', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 2, 2, 'ከኀጢአታችን የተለየን እኛ እንግዲህ እንዴት ዳግመኛ በእርስዋ ጸንተን መኖር እንችላለን?'),
  ('2e5e2673-757d-537b-aa03-04e93a3e20f3', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 3, 3, 'ነገር ግን በጌታችን በኢየሱስ ክርስቶስ የተጠመቅን እኛ ሁላችን በሞቱ እንደ ተጠመቅን ሁላችሁ ይህን ዕወቁ።'),
  ('844ca483-a77c-5f0a-a2a8-d8eb49423fa7', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 4, 4, 'በሞቱም እንመስለው ዘንድ ከእርሱ ጋር በጥምቀት ተቀበርን፤ እርሱ ክርስቶስ በአባቱ ጌትነት ከሙታን እንደ ተነሣ እኛም እንደ እርሱ በሐዲስ ሕይወት እንኖራለን።'),
  ('5b16aa27-cfe9-5a4f-a354-6096a3bcad5e', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 5, 5, 'በሞቱ ከመሰልነውም በትንሣኤው እንመስለዋለን።'),
  ('911b6640-aec9-5065-a8a8-5b751ae98805', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 6, 6, 'ነገር ግን የኀጢአትን ሥጋ ይሽር ዘንድ ከእርሱ ጋር የተሰቀለው አሮጌው ሰውነታችን እንደ ሆነ ይህን እናውቃለን፤ ከእንግዲህ ወዲያ ዳግመና ለኀጢአት እንገዛ ዘንድ አንመለስም።'),
  ('c50f000f-2381-5588-a110-327ecec9561c', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 7, 7, 'የሞተስ ከኀጢአት ነጻ ወጥቶአል።'),
  ('fbdaa3fa-bd6f-5f17-a4f5-d36f91c9fa7b', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 8, 8, 'ከክርስቶስ ጋር ከሞትንም ከእርሱ ጋር በሕይወት እንደምንኖር እናምናለን።'),
  ('93712f53-4756-5136-a8f5-06cac4996df6', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 9, 9, 'ክርስቶስ ከሙታን ተለይቶ እንደ ተነሣ፥ ዳግመኛም እንደማይሞት፥ እንግዲህ ወዲህም ሞት እንደማይገዛው እናውቃለን።'),
  ('455c1e21-f800-5987-accb-e25dbdb43d4f', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 10, 10, 'የሞተ አንድ ጊዜ ሞተ፤ በሞቱም ኀጢአትን ሻራት፤ የተነሣም ለእግዚአብሔር ተነሣ።'),
  ('78f90726-123a-5d50-abcd-7504933c144e', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 11, 11, 'እንዲሁ እናንተም ራሳችሁን ለኀጢአት ምውታን አድርጉ፤ በጌታችን በኢየሱስ ክርስቶስም ለእግዚአብሔር ሕያዋን ሁኑ።'),
  ('2c6f7b70-fd1d-5d30-a9bc-659a9d08d7e4', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 12, 12, 'በዚህ በሚሞት ሰውነታችሁ ኀጢአትን አታንግሡአት፤ ለምኞቱም እሽ አትበሉት።'),
  ('745478e1-7c50-57ac-a028-3937b17b93a6', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 13, 13, 'ከሙታን ተለይቶ እንደ ተነሣ፥ ራሳችሁን ለእግዚአብሔር መሥዋዕት አድርጉ እንጂ ሰውነታችሁን ለኀጢአት የዐመፅ የጦር መሣሪያ አታድርጉት፤ ሰውነታችሁንም ለእግዚአብሔር የጽድቅ የጦር መሣሪያ አድርጉ።'),
  ('901bc354-934f-580d-a55d-c30336995fa6', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', 'ca7b72df-dce8-583a-a083-af1289e917eb', 14, 14, 'እንግዲህ ኀጢአት አትገዛችሁም፤ የኦሪትን ሕግ ከመሥራት ወጥታችሁ ወደ እግዚአብሔር ጸጋ ገብታችኋልና።'),
  ('9ad51a26-b4eb-5d54-a534-c9f8aa395088', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 1, 15, 'እንግዲህ ምን እንላለን? የኦሪትን ሕግ ከመሥራት ወጥተን ወደ እግዚአብሔር ጸጋ ስለ ገባን ኀጢአት እንሥራን? አይደለም።'),
  ('bc86bcf4-cd14-566d-a273-6c437694be1f', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 2, 16, 'ለምትታዘዙለት፥ እሺ ለምትሉትም እናንተ አገልጋዮች እንደ ሆናችሁ አታውቁምን? ለተባበራችሁለትስ ራሳችሁን እንደ አስገዛችሁ አታውቁምን? ኀጢአትንም እሺ ብትሉአት፥ ተባብራችሁም ብትበድሉ እናንት ለሞት ተገዢዎች ትሆናላችሁ፤ ጽድቅንም እሺ ብትሉአት ለበጎ ሥራም ብትተባበሩ የእግዚአብሔር አገልጋዮች ናችሁ።'),
  ('55f85362-6de5-5919-a497-fb298c1d8ad3', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 3, 17, 'የኀጢአት ተገዦች ስትሆኑ ምሳሌነቱ ለተሰጣችሁ ለምትማሩት ትምህርት ታዝዛችኋልና እግዚአብሔር ይመስገን።'),
  ('141181bf-0fad-51b3-a572-07c89a4733ab', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 4, 18, 'አሁን ግን ከኀጢአት ነጻ ሁናችሁ ለጽድቅ ተገዝታችኋል።'),
  ('886e8f56-4d4c-5eaf-ae2f-1b9139efa831', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 5, 19, 'ስለ ሰውነታችሁ ድካም በሰው ልማድ እነግራችኋለሁ፤ ዕወቁ፤ ቀድሞ ሰውነታችሁን ለኀጢአትና ለርኵሰት፥ ለዐመፃም እንደ አስገዛችሁ፥ እንዲሁ አሁንም ሰውነታችሁን ለጽድቅና ለቅድስና አስገዙ።'),
  ('e737f3b9-1476-5a8e-af7c-6fcd21957df2', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 6, 20, 'ለኀጢአት ትገዙ በነበረበት ጊዜ ከጽድቅ ነፃ ነበራችሁና።'),
  ('a39b35c0-fbd9-50a9-abee-8b9ab47a419a', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 7, 21, 'በዚያን ጊዜ ሥራችሁም እነሆ፥ ዛሬ ታፍሩበታላችሁ፤ መጨረሻው ሞት ነውና።'),
  ('7d5d56f0-1850-5e7f-a126-6bd87a39ad0a', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 8, 22, 'ዛሬ ግን ከኀጢአት ነጻ ወጣችሁ፤ ራሳችሁንም ለጽድቅ አስገዛችሁ፤ ለቅድስናም ፍሬን አፈራችሁ፤ ፍጻሜው ግን የዘለዓለም ሕይወት ነው።'),
  ('dc74a04d-1d8a-5254-afd4-baf41fcb0ce1', '75f67fe2-ebce-5690-a705-3cd2f1f56d86', '1df87dd6-931c-51d7-a8ed-f2b97ca52a73', 9, 23, 'የኀጢአት ትርፍዋ ሞት ነውና፤ የእግዚአብሔር ጸጋ ግን በጌታችን በኢየሱስ ክርስቶስ የዘለዓለም ሕይወት ነው።'),
  ('c21356ac-5069-5c5b-a003-02ba55b5d890', 'd29ec345-b099-52c8-a914-20b75890a97e', '07ba9c6a-061c-5d42-acd2-33940bb7e5ab', 1, 1, 'ወንድሞቻችን! ሕግን ለሚያስተውሉ እናገራለሁና፤ ሰው በሕይወት ባለበት ሁሉ ሕግ እንዲገዛው አታውቁምን?'),
  ('df1d8d32-7cbf-5eb4-adbf-90a3802eef45', 'd29ec345-b099-52c8-a914-20b75890a97e', '07ba9c6a-061c-5d42-acd2-33940bb7e5ab', 2, 2, 'ባል ያላት ሴት ባልዋ በሕይወት ሳለ ከእርሱ ጋር በሕግ የታሰረች ናት፤ ባልዋ የሞተ እንደ ሆነ ግን በሚስትነት ታስራበት ከኖረችው ሕግ የተፈታች ናት።'),
  ('1ec62dbb-7f84-5160-a137-bd5e757077a2', 'd29ec345-b099-52c8-a914-20b75890a97e', '07ba9c6a-061c-5d42-acd2-33940bb7e5ab', 3, 3, 'ስለዚህ ባልዋ በሕይወት ሳለ ለሌላ ወንድ ብትሆን አመንዝራ ትሆናለች፤ ባልዋ ቢሞት ግን ከሕግ ነፃ ወጥታለች፤ ለሌላ ወንድ ብትሆንም አመንዝራ አትባልም።'),
  ('d7156179-075a-5b7e-ae67-99b5db890b99', 'd29ec345-b099-52c8-a914-20b75890a97e', '07ba9c6a-061c-5d42-acd2-33940bb7e5ab', 4, 4, 'ወንድሞች ሆይ! እናንተ እንዲሁ የክርስቶስ አካል ስለ ሆናችሁ ከኦሪት ተለይታችኋል፤ ለእግዚአብሔርም ፍሬ እንድታፈሩ ከሙታን ተለይቶ ለተነሣው ለዳግማዊ አዳም ሆናችኋል።'),
  ('824e01dc-1077-5875-a90c-905bb4c041af', 'd29ec345-b099-52c8-a914-20b75890a97e', '07ba9c6a-061c-5d42-acd2-33940bb7e5ab', 5, 5, 'የሰውን ሕግ በሠራን ጊዜ ግን በኦሪት ሕግ ደካማነት ቅጣቱ ጸናብን፤ ሞትንም አፈራን።'),
  ('71fbfbbf-1430-545c-af43-cafa0b00b8c7', 'd29ec345-b099-52c8-a914-20b75890a97e', '07ba9c6a-061c-5d42-acd2-33940bb7e5ab', 6, 6, 'አሁን ግን ታስረንበት ከነበረው ከኦሪት ሕግ ነፃ ወጥተናል፤ ስለዚህ በብሉይ መጽሐፍ ሳይሆን በአዲሱ መንፈሳዊ ሕይወት እንገዛለን።'),
  ('13b9862a-f9be-5b43-a9cd-917aacc8848b', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 1, 7, 'እንግዲህ ምን እንላለን? ኦሪት ኀጢአት ናትን? አይደለችም፤ ነገር ግን ኦሪት ባትሠራ ኀጢአትን ባላወቅኋትም ነበር፤ ኦሪት፥ “አትመኝ” ባትል ኖሮም ምኞትን ፈጽሞ ባላወቅኋትም ነበር።'),
  ('f50786d6-1fe4-514b-a3d2-8107ea8af2ff', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 2, 8, 'ያችም ትእዛዝ ለኀጢአት ምክንያት ሆነቻት፤ ምኞትንም ሁሉ አመጣችብኝ፤ ቀድሞ ግን ኦሪት ሳትሠራ ኀጢአት ሙት ነበረች።'),
  ('3dbd537e-2674-53ff-ae35-c8cb8d72ffac', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 3, 9, 'እኔም ቀድሞ ኦሪት ሳትሠራ ሕያው ነበርሁ፤ የኦሪት ትእዛዝ በመጣች ጊዜ ግን ኀጢአት ሕይወትን አገኘች፤ እኔ ግን ሞትሁ።'),
  ('7ec70dbc-d25a-5c2b-ad8f-5f3c66301863', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 4, 10, 'ለሕይወት የተሠራችልኝ ያቺ ሕግ ለሞት ሆና አገኘኋት።'),
  ('5f1dfa57-e0b2-56d5-a2a2-96f16195e498', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 5, 11, 'ኀጢአት በዚያች ትእዛዝ ምክንያት አሳተችኝ፤ በእርሷም ገደለችኝ።'),
  ('01d28aa9-e0a1-5563-a424-81d1b2f2d5ef', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 6, 12, 'አሁንም ቢሆን ኦሪትስ ቅድስት ናት፤ ትእዛዝዋም ቅዱስና እውነት ነው፤ መልካምም ነው፤ በረከትም ነው።'),
  ('9737f139-4fc9-5e56-afe3-f6ee22460a48', 'd29ec345-b099-52c8-a914-20b75890a97e', '7a18e7e1-1578-50d8-ae8a-e6bdf89852d3', 7, 13, 'እንግዲህ ያ መልካም ነው ብዬ የማስበው ነገር በውኑ አጥፊ ሆነኝ እላለሁን? አይደለም፤ ነገር ግን ኀጢአት ኀጢአት እንደ ሆነች በታወቀች ጊዜ ሞትን አበዛችብኝ፤ ከዚያም ትእዛዝ የተነሣ ኀጢአተናው እንዲታወቅ፥ ኀጢአትም ተለይታ እንድትታወቅ ኦሪት መልካሙን ከክፉ ልትለይ ተሠርታለች።'),
  ('fff97113-6ceb-5d81-a165-de60dceafbe3', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 1, 14, 'የኦሪት ሕግ መንፈሳዊ እንደ ሆነ እናውቃለን፤ እኔ ግን ለኀጢአት የተሸጥሁ ሥጋዊ ነኝ።'),
  ('28f2588b-41e1-501d-a2a8-8b77fba485f5', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 2, 15, 'የማደርገውን አላውቅምና፤ የምወደውንም ያን ምንም አላደርገውምና፤ ያንኑ የምጠላውን ብቻ እሠራለሁ እንጂ።'),
  ('febcdf26-6b2c-51ab-a97a-1ca74ab26944', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 3, 16, 'የማልወደውን የምሠራ ከሆንሁ ግን ያ የኦሪት ሕግ መሠራት ለበጎ እንደ ሆነ ምስክሩ እኔ ነኝ።'),
  ('4391ae43-6dda-5e91-ab6f-2a958ddb81bc', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 4, 17, 'እንግዲያስ በእኔ ላይ ያደረች ኀጢአት ናት እንጂ፥ ያን የማደርገው እኔ አይደለሁም።'),
  ('45d11a18-ecda-5b40-a572-4deeaea8b051', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 5, 18, 'በእኔ ማለት በሥጋዬ መልካም ነገር እንደማይኖር አውቃለሁ፤ መልካም ሥራ ለመሥራት መሻቱስ በእኔ ዘንድ አለ፤ በጎ ምግባር መሥራት ግን የለኝም።'),
  ('bd83135e-5abb-58f2-a369-f45a32f30d1a', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 6, 19, 'ያን የምወደውንም በጎ ነገር የማደርግ አይደለም፤ ነገር ግን ያን የምጠላውን ክፉውን አደርጋለሁ።'),
  ('faa615bb-780d-5e5b-ac3e-daa615e8f7b8', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 7, 20, 'የማልወደውንስ የምሠራ ከሆነ የምሠራው እኔ አይደለሁም፤ በእኔ ላይ ያደረች ኀጢአት ናት እንጂ።'),
  ('dff36a67-5585-5c07-abd1-05d32fe3eca2', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 8, 21, 'መልካም ሥራ እንድሠራ የፈቀደልኝን ያን ሕግ እርሱ ክፉ ነገር አምጥቶብኝ አገኘሁት።'),
  ('e9909537-9ca9-50b8-a3cd-a851c083dee3', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 9, 22, 'በልቡናዬ ውስጥ ያለ የእግዚአብሔር ሕግ መልካም ነው።'),
  ('f890cd58-ce1d-5922-aa0b-6f14839b3793', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 10, 23, 'ነገር ግን በሰውነቴ ውስጥ ያለውን ሌላ የኀጢአት ሕግ እመለከታለሁ፤ በልቡናዬም ውስጥ ካለው ከእግዚአብሔር ሕግ ጋር ተሰልፈው ተዋጉ፤ በሰውነቴ ውስጥ ያለው ያ የኀጢአት ሕግም በረታና ወደ እርሱ ማረከኝ።'),
  ('63cc747f-e4d0-55c7-a11b-53d9853f7e5c', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 11, 24, 'እኔ ምንና ወራዳ ሰው ነኝ፤ ከዚህ ሟች ሰውነቴ ማን ባዳነኝ?'),
  ('5cfd811b-e8cd-5774-a061-833608acfc32', 'd29ec345-b099-52c8-a914-20b75890a97e', '445db9e4-b517-5f1e-a66c-9801635c3794', 12, 25, 'በጌታችን በኢየሱስ ክርስቶስ እግዚአብሔር ይመስገን፤ እኔ በልቤ ለእግዚአብሔር ሕግ እገዛለሁ፤ በሥጋዬ ግን ለኀጢአት ሕግ እገዛለሁ።'),
  ('82ca8547-71d5-5180-a6fe-c934e3ef1db2', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 1, 1, 'እንግዲህ በኢየሱስ ክርስቶስ ላሉት በመንፈስ እንጂ በሥጋ ለማይመላለሱ ፍርድ የለባቸውም።'),
  ('3f9f8071-f270-586f-a31d-cc86de1206c9', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 2, 2, 'በኢየሱስ ክርስቶስ የተሰጠን ሕይወት የሚገኝበት የመንፈስ ሕግ እርሱ ከኀጢአትና ከሞት ሕግ ነጻ አውጥቶናልና።'),
  ('acec2220-906a-5e0b-ae77-fc033c923061', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 3, 3, 'ስለ ሥጋ ደካማነት የኦሪት ሕግ ከሞት ማዳን በተሳነው ጊዜ እግዚአብሔር በኀጢኣተና ሥጋ ምሳሌ ልጁን ላከ፤ ያችንም ኀጢአት በሥጋው ቀጣት።'),
  ('e4bc94a2-fcea-58e9-a059-9270727cbafa', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 4, 4, 'እናን ያጸድቀን ዘንድ፥ የኦሪትንም ሕግ ሠርቶ እንደ ፈጸመ ሰው ያደርገን ዘንድ፤ ይህም በመንፈሳዊ ሕግ ጸንተው ለሚኖሩ ነው እንጂ በሥጋ ሕግ ለሚሠሩ አይደለም።'),
  ('b28466aa-a4e1-508f-a5fc-3f3599321f2d', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 5, 5, 'እንደ ሥጋ ፈቃድ የሚኖሩ የሥጋን ነገር ያስባሉና፤ እንደ መንፈስ ፈቃድ የሚኖሩ ግን የመንፈስን ነገር ያስባሉ።'),
  ('be1fcbe7-1503-5e0f-a0a3-dc8f45ae375a', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 6, 6, 'የሥጋ ዐሳብ ሞትን ያመጣብናል፤ የመንፈስ ዐሳብ ግን ሰላምንና ሕይወትን ይሰጠናል።'),
  ('d1bf6053-d306-55e0-a8b4-6ea848d709dd', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 7, 7, 'የሥጋ ዐሳብ ለእግዚአብሔር ጠላቱ ነውና፤ ለእግዚአብሔርም ሕግ ስለማይገዛ፥ መፈጸም አይቻለውም።'),
  ('857451d5-80a2-5142-a112-267da440739b', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 8, 8, 'ለሥጋዊ ፈቃዳቸው የሚሠሩ ሁሉ እግዚአብሔርን ደስ ማሰኘት አይችሉም።'),
  ('d4982e8d-da59-52e7-a1f3-4830f2a8add1', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 9, 9, 'እናንተ ግን ለመንፈሳዊ ሕግ እንጂ ለሥጋችሁ ፈቃድ የምትሠሩ አይደላችሁም፤ የእግዚአብሔር መንፈስ በእናንተ አድሮ ይኖራልና፤ የክርስቶስ መንፈስ ያላደረበት ግን እርሱ የእርሱ ወገን አይደለም።'),
  ('bf8c878d-2c1d-5d8c-a37a-832c6ed46680', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 10, 10, 'ክርስቶስ ካደረባችሁ ግን ሰውነታችሁን ከኀጢአት ሥራ ለዩ፤ መንፈሳችሁንም ለጽድቅ ሥራ ሕያው አድርጉ።'),
  ('f7a7abae-fe26-5feb-a789-19fda6e523c6', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', 'cea56e65-e041-5397-abce-0eae4d525312', 11, 11, 'ጌታችን ኢየሱስን ከሙታን ለይቶ ያስነሣው የእግዚአብሔር መንፈስ ካደረባችሁ ኢየሱስ ክርስቶስን ከሙታን ለይቶ ያስነሣው እርሱ አድሮባችሁ ባለ መንፈሱ ለሟች ሰውነታችሁ ሕይወትን ይሰጣታል።'),
  ('4ed6b231-c204-5d31-aa73-b6152eaf88e6', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '3827057e-1c28-5fe8-a73a-8ba88bd8e87a', 1, 12, 'ወንድሞቻችን፥ አሁንም በሥጋችን ሳለን በሥጋ ፈቃድ እንኖር ዘንድ አይገባም።'),
  ('a962260b-cbbc-59d5-a836-dc7c7eed8ab1', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '3827057e-1c28-5fe8-a73a-8ba88bd8e87a', 2, 13, 'እንደ ሥጋ ፈቃድ ብትኖሩ ትሞታላችሁ፤ ነገር ግን በመንፈሳዊ ሥራ የሥጋችሁን ፈቃድ ብትገድሉ ለዘለዓለም በሕይወት ትኖራላችሁ።'),
  ('5f7caf91-572f-5c07-aa07-d07144ce9a07', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '3827057e-1c28-5fe8-a73a-8ba88bd8e87a', 3, 14, 'በእግዚአብሔር መንፈስ የሚሠሩ ሁሉ የእግዚአብሔር ልጆች ናቸው።'),
  ('94cbdc2e-2ea0-5bd8-a73c-aced9df521d4', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '3827057e-1c28-5fe8-a73a-8ba88bd8e87a', 4, 15, 'ዳግመናም አባ አባት ብለን የምንጮህበትን የልጅነት መንፈስ ተቀበላችሁ እንጂ እንደ ገና ለፍርሀት የባርነት መንፈስን አልተቀበላችሁምና።'),
  ('1fe73d64-c7de-55d5-a90d-5b899cdb54a2', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '3827057e-1c28-5fe8-a73a-8ba88bd8e87a', 5, 16, 'እና የእግዚአብሔር ልጆች እንደሆን ለልቡናችን ምስክሩ እርሱ መንፈስ ቅዱስ ነው።'),
  ('8df5f84b-8ba5-5ea3-a20f-bb0276138f5d', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '3827057e-1c28-5fe8-a73a-8ba88bd8e87a', 6, 17, 'እና የእግዚአብሔር ልጆች ከሆን ወራሾቹ ነን፤ የእግዚአብሔር ወራሾች ከሆንም የክርስቶስ ወራሾቹ ነን፤ በመከራ ከመሰልነውም በክብር እንመስለዋለን።'),
  ('ac45dfac-bff5-5a5e-a450-6286be6255ad', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 1, 18, 'ነገር ግን የዚህ ዓለም መከራ ለእና ሊገለጥ ከአለው ክብር ጋር እንደማይተካከል ዐስቡ።'),
  ('bdbd2ce0-ac5e-52c6-a356-d5f56c1cc79e', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 2, 19, 'የዓለም ተስፋው የእግዚአብሔርን ልጅ መምጣት ይጠባበቅ ነበርና።'),
  ('71044bb0-1a86-51f8-aaec-91422aadfca0', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 3, 20, 'ዓለም ባለማወቅ ለከንቱ ነገር ተገዝቶአልና በተስፋ ስለ አስገዛው ነው እንጂ በፈቃዱ አይደለም።'),
  ('f579a0d6-503e-5bb0-a171-834dbd14ecc4', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 4, 21, 'ነገር ግን አስቶ በባርነት ከሚገዛው ከዚህ ወጥቶ የእግዚአብሔር ልጆች ወደ አገኙአት የነጻነት ክብር ይገባ ዘንድ ተስፋ አለው።'),
  ('0c6135ec-611f-5a91-acbf-2d57690adb15', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 5, 22, 'እስካሁን ዓለም ሁሉ ያዘነና የተከዘ እንደ ሆነ እናውቃለን።'),
  ('072e61c0-027c-5d87-abb0-7d819627262c', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 6, 23, 'ነገር ግን የሚተክዝ ዓለም ብቻ አይደለም፤ የመንፈስ ቅዱስን ፈለማ የተቀበልነው እናም ደግሞ እናዝናለን እንጂ፤ የነፍሳችንን ድኅነት እናገኝ ዘንድ የልጅነትን ክብር ተስፋ እናደርጋለንና፤ በእምነትም ድነናልና።'),
  ('ac5daea3-9f2d-50c9-afd8-75318ca69a29', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 7, 24, 'የሚታየውን ተስፋ ማድረግ ተስፋ አይደለም፤ የሚያየውንማ እንዴት ተስፋ ያደርጋል? እንዴትስ ይጠብቃል?'),
  ('dc5038a1-021b-5b49-a8af-1214acfb3e96', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 8, 25, 'የማይታየውን ተስፋ ብናደርግ ግን እርሱን ተስፋ አድርገን በእርሱ እንደ ጸናን መጠን ትዕግሥታችን ይታወቃል።'),
  ('e12eb387-5b1f-5f20-ae79-1227c06d15bc', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 9, 26, 'መንፈስ ቅዱስም ከድካማችን ይረዳናል፤ እንግዲያስ ተስፋችንን ካላወቅን ጸሎታችን ምንድነው? ነገር ግን እርሱ ራሱ መንፈስ ቅዱስ ስለ መከራችንና ስለ ችግራችን ይፈርድልናል።'),
  ('b9f033a2-15bc-5b2a-aa48-899c309d025e', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 10, 27, 'እርሱም ልባችንን ይመረምራል፤ ልብ የሚያስበውንም እርሱ ያውቃል፤ ስለ ቅዱሳንም በእግዚአብሔር ዘንድ ይፈርዳል።'),
  ('3046b89f-fbdd-5067-acc3-f45b07ebe40f', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 11, 28, 'እግዚአብሔር የሚወዱትን ምርጦቹን በበጎ ምግባር ሁሉ እንደሚረዳቸው እናውቃለን።'),
  ('8dd105dc-d72a-5b3c-a81b-d5a2452e735e', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 12, 29, 'ልጁ በብዙዎች ወንድሞች መካከል በኵር ይሆን ዘንድ አስቀድሞ ያወቃቸውንና የመረጣቸውን እነርሱን ልጁን ይመስሉ ዘንድ አዘጋጅቶአቸዋል።'),
  ('035d34ce-f162-5fc9-ada9-b39a85294bbd', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 13, 30, 'ያዘጋጃቸውን እነርሱን ጠራ፤ የጠራቸውንም እነርሱን አጸደቀ፤ የአጸደቃቸውንም እነርሱን አከበረ።'),
  ('bdb7e031-b719-5c8f-a93b-81f093b4c0be', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 14, 31, 'እንግዲህ ስለዚህ ምን እንላለን? እግዚአብሔር ከእና ጋር ከሆነ ማን ይችለናል?'),
  ('7d38fd72-c598-5532-a276-191fd5dcc5b8', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 15, 32, 'ለልጁ ስንኳ አልራራም፤ ስለ ሁላችን ቤዛ አድርጎ አሳልፎ ሰጠው እንጂ፥ እንግዲህ እርሱ ሁሉን እንዴት አይሰጠንም?'),
  ('d11a0428-9e5d-572d-a986-83ce14b897be', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 16, 33, 'እንግዲህ እርሱ ራሱ ካጸደቀ እግዚአብሔር የመረጣቸውን ሰዎች የሚቃወማቸው ማነው?'),
  ('fe472ec9-885e-53be-ae23-aca2a6813515', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 17, 34, 'የሚፈርድስ ማነው? የሞተው፥ ይልቁንም ከሙታን ተለይቶ የተነሣው፥ በእግዚአብሔርም ቀኝ የተቀመጠው፥ ደግሞ ስለ እና የሚፈርደው ኢየሱስ ክርስቶስ ነው።'),
  ('f6a23d6b-a455-56f4-a605-4ba3d10f0f95', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 18, 35, 'ከክርስቶስ ፍቅር ማን ይለየናል? መከራ ነውን? ኀዘን ነውን? ስደት ነውን? ራብ ነውን? መራቆት ነውን? ጭንቀት ነውን? ሾተል ነውን?'),
  ('f373c77c-442a-539a-a9c0-9884fdb1c1c3', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 19, 36, 'መጽሐፍ እንዳለ፥ “ስለ አንተ ዘወትር ይገድሉናል፤ እንደሚታረዱ በጎችም ሆነናል።”'),
  ('d483c380-5c2e-53a4-a9a7-d6063c676094', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 20, 37, 'ነገር ግን በወደደን በእርሱ ሁሉን ድል እንነሣለን።'),
  ('c626743e-0010-5dc6-a337-8cda2a7cc9e6', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 21, 38, 'ነገር ግን ሞትም ቢሆን፥ ሕይወትም ቢሆን፥ መላእክትም ቢሆኑ፥ አለቆችም ቢሆኑ፥ ያለውም ቢሆን፥ የሚመጣውም ቢሆን በጌታችን በኢየሱስ ክርስቶስ ካለ ከእግዚአብሔር ፍቅር ሊለየን እንደማይችል አምናለሁ።'),
  ('9b684653-cc64-58cf-a6a3-015b9b0584f4', 'd11f7b68-30fd-5011-af0b-1dd691a7b301', '50427dab-97c4-593b-a24f-48b8c0b17c15', 22, 39, 'ኀይልም ቢሆን፥ ከፍታም ቢሆን፥ ዝቅታም ቢሆን፥ ሌላ ፍጥረትም ቢሆን ከክርስቶስ ፍቅር ሊለየን የሚችል የለም።'),
  ('0ac30c8a-2ac7-5711-a231-1485fca5c899', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 1, 1, 'በክርስቶስ እውነት እነግራችኋለሁ፤ ሐሰትም አልናገርም። ሕሊናዬም በመንፈስ ቅዱስ ይመሰክርልናል፤'),
  ('265315a6-1806-5acf-a499-d2faed6dcaac', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 2, 2, 'በጊዜው ሁሉ ብዙ ኀዘን፥ የማያቋርጥም ጭንቀት በልቤ አለ።'),
  ('2288f4a8-10cf-58ff-a752-9a0116b778ac', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 3, 3, 'በሥጋ ዘመዶችና ወንድሞች ስለሚሆኑ እኔ ከክርስቶስ እለይ ዘንድ እጸልያለሁ።'),
  ('a97d4510-89de-53e1-adef-e15112a9a2f8', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 4, 4, 'እናህም ልጅነት፥ ክብር፥ ኪዳን፥ ሕግና አምልኮ ያላቸው፥ ተስፋም የተሰጣቸው እስራኤላውያን ናቸው።'),
  ('7819dff5-9dd8-5654-acb1-1ce96ece9094', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 5, 5, 'እነርሱም አባቶቻችን ናቸው፤ ከእነርሱም ክርስቶስ በሥጋ ተወለደ፤ እርሱም ከሁሉ በላይ የሆነ ለዘለዓለም ቡሩክ አምላክ ነው፤ አሜን።'),
  ('3bfc4a7f-b289-552d-aa9e-a148adc523c7', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 6, 6, 'ነገር ግን የእግዚአብሔር ቃል አይታበልም፤ እስራኤል ሁሉ እስራኤላውያን አይደሉምና።'),
  ('6a9a1f9e-a339-5740-a93a-1de63c455427', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 7, 7, 'የአብርሃም ዘር ሁሉ ልጆቹ የሆኑት አይደለም፤ ከይስሐቅ ዘር ይጠራልሃል አለው እንጂ።'),
  ('6bdb7abb-79b0-555f-ad2a-812c622af34a', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 8, 8, 'ልጆች እንዲሆኑት ተስፋ ያናገረለት የእግዚአብሔር ልጆች ናቸው፤ እነዚህ ከሥጋ የተወለዱ ግን የእግዚአብሔር ልጆች አይደሉም።'),
  ('5df0d5e9-bf6b-5247-a44a-db1b4c3ac9d8', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 9, 9, '“ከርሞ እንደ ዛሬ ወደ አንተ እመለሳለሁ፤ ሣራም ወንድ ልጅ ታገናለች፤” ብሎ ተስፋ ሰጥቶታልና።'),
  ('ad769274-6231-5a99-aaa6-39012d04a8dd', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 10, 10, 'ነገር ግን ለእርስዋ ብቻ አይደለም፤ ርብቃም ለአባታችን ለይስሐቅ መንታ በፀነሰች ጊዜ፥'),
  ('ae966816-c75f-59dd-a7f5-d35e806e154a', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 11, 11, 'ሳይወለዱ፥ ክፉና መልካም ሥራም ሳይሠሩ የእግዚአብሔር መምረጡ በምን እንደ ሆነ ይታወቅ ዘንድ፥'),
  ('aec8000d-d98c-537d-a492-e76a6a40c4b6', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 12, 12, 'እርሱ የጠራው ነው እንጂ ሰው በሥራው የሚመረጥ አንዳይደለም ያውቁ ዘንድ፥ ለርብቃ፥ “ታላቁ ለታናሹ ይገዛል” አላት።'),
  ('04be728e-d82a-5996-a941-535376d45475', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 13, 13, '“ያዕቆብን ወደድሁ፤ ዔሳውን ግን ጠላሁ” ተብሎ እንዲሁ ተጽፎአልና።'),
  ('4911f657-5c7b-5856-abe5-b17a64d8467a', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 14, 14, 'እንግዲህ ምን እንላለን? እግዚአብሔር ያደላልን? አያደላም።'),
  ('94a09463-0da3-5f6a-afe1-2ee3bbd8bad0', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 15, 15, 'እግዚአብሔርም ሙሴን እንዲህ አለው፥ “የምምረውን እምረዋለሁ፤ ይቅር የምለውንም ይቅር እለዋለሁ።”'),
  ('5786a611-7fd0-5f2f-af62-42f2e58529c3', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 16, 16, 'አሁንም ለሮጠና ለቀደመ አይደለም፤ እግዚአብሔር ይቅር ላለው ነው እንጂ።'),
  ('600bd8eb-68c4-5df6-a880-b4ca47d135af', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 17, 17, 'እግዚአብሔርም ለፈርዖን በመጽሐፍ እንዲህ አለው፥ “ኀይሌን በአንተ ላይ እገልጥ ዘንድ፥ ስሜም በምድር ሁሉ ይሰማ ዘንድ ስለዚህ አስነሣሁህ።”'),
  ('de962985-d3fa-5174-adca-796408b48503', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 18, 18, 'እነሆ፥ የሚወድደውን ይምረዋል፤ የሚወድደውንም ልቡን ያጸናዋል።'),
  ('4385d81a-46eb-55bc-a65d-f93c8893ed64', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 19, 19, 'እንግዲህ ምን ትላለህ? አንተ እግዚአብሔርን ትነቅፈዋለህን? ምክሩንስ የሚቃወማት አለን?።'),
  ('0c7c0e07-9bab-584a-aba6-a42924bd505c', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 20, 20, 'ሰው ሆይ፥ እግዚአብሔርን የምትከራከረው አንተ ምንድን ነህ? ሥራ ሠሪውን እንዲህ አታድርገኝ ሊለው ይችላልን?'),
  ('6f51fa81-04b5-5238-a367-e655dcbc0a9d', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 21, 21, 'ሸክላ ሠሪ ከአንድ ጭቃ ግማሹን ለክብር፥ ግማሹንም ለኀሳር አድርጎ ዕቃን ሊሠራ አይችልምን?'),
  ('e14d4579-e7a4-5494-a44f-6e45d23769d0', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 22, 22, 'እግዚአብሔርም ኀይሉን የሚገልጽበትን ቅጣቱን ሊያሳይ ቢወድ፥ ትዕግሥቱን ካሳየ በኋላ ለማጥፋት የተዘጋጁትን ቍጣውን የሚገልጽባቸውን መላእክት ያመጣል።'),
  ('4c87de8f-aa6d-51b4-a239-bc6a92658787', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 23, 23, 'ዳግመናም የክብሩን ባለጠግነት ሊያሳይ ቢወድ አስቀድሞ ለወደዳቸውና ለጠራቸው ለይቅርታ የተዘጋጁ የምሕረት መላእክትን ያመጣል።'),
  ('66f651c9-45bd-58f7-a33f-7394de8603d1', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 24, 24, 'ወደ ክብሩ የጠራንና የሰበሰበንም እና ነን፤ ነገር ግን ከአሕዛብም ነው እንጂ ከአይሁድ ብቻ አይደለም።'),
  ('09897763-7bd5-53b5-adeb-ba8b2166e379', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 25, 25, 'ነቢዩ ሆሴዕ እንዲህ እንዳለ “ወገኔ ያልነበረውን ወገኔ አደርገዋለሁ፤ ወዳጄ ያልነበረችውንም ወዳጄ አደርጋታለሁ።'),
  ('09d0ffb5-a8c8-5507-ab7e-95d52bf7be42', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 26, 26, 'የእግዚአብሔር ወገኖች አይደላችሁም ይባሉ በነበሩበት ሀገርም የእግዚአብሔር ልጆች ይሆናሉ።”'),
  ('c1b2ab53-9ba7-598c-a5a8-c0056eb21663', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 27, 27, 'ኢሳይያስም ድምፁን ከፍ አድርጎ ስለ እስራኤል እንዲህ አለ፥ “የእስራኤል ልጆች ቍጥራቸው እንደ ባሕር አሸዋ ቢሆንም የተረፉት ይድናሉ።'),
  ('ae948433-3d6b-5187-a6ed-b80180d7750f', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 28, 28, 'እግዚአብሔር በዓለም ውስጥ ያደርገው ዘንድ ያለውን ያለቀና የተቈረጠ ነገርን ይናገራልና።”'),
  ('8e32a7ad-c8f4-578c-aa21-4f8402718314', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '50d8a405-d5c3-5a58-ae88-a100d525e45a', 29, 29, 'ኢሳይያስም አስቀድሞ እንደ ተናገረ “እግዚአብሔር ጸባኦት ዘር ያስቀረልን ባይሆን ኖሮ እንደ ሰዶም በሆን፥ ገሞራንም በመሰልን ነበር።”'),
  ('7aebfc7f-1846-5e15-a023-8d8426ba1932', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '822d10d9-6588-5922-a0eb-6197953fd41c', 1, 30, 'እንግዲህ ምን እንላለን? ጽድቅን ያልፈለጉአት አሕዛብ ስንኳ ጽድቅን አገኙአት፤ በእምነትም ጸደቁ።'),
  ('682ca827-92e0-5620-ac55-527a021fb103', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '822d10d9-6588-5922-a0eb-6197953fd41c', 2, 31, 'እስራኤል ግን ኦሪትን ሲከተሉ መጽደቅ ተሳናቸው፤ የኦሪታቸውን ሥራ አልፈጸሙምና።'),
  ('5b7097f0-289c-50e4-af47-142fd6c1459f', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '822d10d9-6588-5922-a0eb-6197953fd41c', 3, 32, 'ይህስ ስለምን ነው? ጽድቃቸው የኦሪትን ሥራ በመሥራት እንጂ በእምነት ስለ አልሆነ ነው፤ የእንቅፋት ድንጋይ አሰነካከላቸው።'),
  ('4f4c814b-733c-5d4a-ad46-28b55b0cbe48', '26deba80-f5d3-5b98-ab65-8f527c1d6b84', '822d10d9-6588-5922-a0eb-6197953fd41c', 4, 33, 'መጽሐፍ እንዲሁ “በጽዮን የእንቅፋት ድንጋይንና የማሰናከያ ዐለትን አኖራለሁ፤ ያመነባትም ለዘለዓለም አያፍርም” ብሎአልና።'),
  ('bf8e2125-8c44-514e-a5cf-787379a622f0', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 1, 1, 'ወንድሞች፥ የእኔስ የልቤ ምኞት፥ ወደ እግዚአብሔር የማቀርበው ጸሎትም እስራኤል እንዲድኑ ነው።'),
  ('1c72381e-c774-5026-a0f5-b88af281461a', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 2, 2, 'ለእግዚአብሔር እንዲቀኑ ምስክራቸው እኔ ነኝና፤ ነገር ግን ዐውቀው አይደለም።'),
  ('c6fd88de-9b5d-5f0f-a86e-9a809ea890e5', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 3, 3, 'የእግዚአብሔርን ጽድቅ አያውቁአትምና በራሳቸውም ጽድቅ ጸንተው ሊኖሩ ወደዱ፤ ለእግዚአብሔር ጽድቅ ግን መገዛት ተሳናቸው።'),
  ('1f1f7dc8-fbd6-556d-aafc-74f9d47143d4', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 4, 4, 'የኦሪት ጽድቅ ፍጻሜስ ለሚያምኑበት ሁሉ በክርስቶስ ማመን ነው።'),
  ('fc587bf8-5333-5ffc-a8dd-51a5917a6e9b', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 5, 5, 'ሙሴም “የኦሪትን ጽድቅ መሥራትን የፈጸመ ሁሉ በእርሱ ይጸድቅበታል” አለ።'),
  ('9d3947b5-5620-538c-afcf-9c85f97c87f3', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 6, 6, 'የእምነት ጽድቅ ግን እንዲህ ይላል፥ “በልብህ ወደ ሰማይ ማን ይወጣል?” አትበል፤ ከሰማይ የወረደው ክርስቶስ ነው።'),
  ('35963cff-51d1-55c2-a33a-9bd11ac36cb0', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 7, 7, '“ወደ ጥልቁም ማን ይወርዳል?” አትበል፤ ከሙታን ተለይቶ የተነሣው ክርስቶስ ነው።'),
  ('069184d6-90ff-5c7a-a48c-98aaba743d1f', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 8, 8, 'መጽሐፍ እንዲሁ፥ “ቃል ለልብህም ለአፍህም ቀርቦልሃል ይል የለምን?” ይህም የምንሰብከው የእምነት ቃል ነው።'),
  ('182321d7-2ba5-50aa-a8ab-e54448530ee5', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 9, 9, 'ኢየሱስ ጌታ እንደ ሆነ በአፍህ ብትመሰክር እግዚአብሔርም ከሙታን ለይቶ እንደ አስነሣው በልብህ ብታምን ትድናለህ።'),
  ('cc638288-dcf6-5104-aa53-099cbd75b7ae', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 10, 10, 'በልቡ የሚያምን ይጸድቃልና፤ በአፉም የሚመሰክር ይድናልና።'),
  ('d15ebd1a-2b81-54ba-a3a1-6e47802bf299', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 11, 11, 'መጽሐፍ፥ “የሚያምንበት ሁሉ አያፍርም” ብሎአል።'),
  ('67d51b7d-2ef6-543c-abd8-00704d52ee3d', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 12, 12, 'አይሁዳዊንና አረማዊን አልለየም፤ አንዱ ጌታ የሁሉ ጌታ ነውና፥ እግዚአብሔር ባለጸጋ ስለሆነ ለለመነው ሁሉ ይበቃልና።'),
  ('3af0f13e-8670-5435-a679-184aeb0c79b4', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 13, 13, '“የእግዚአብሔርን ስም የሚጠራ ሁሉ ይድናል።”'),
  ('a1663f36-341c-5e28-a211-6a3c0fe967df', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 14, 14, 'ነገር ግን ያላመኑበትን እንዴት ይጠሩታል? ባልሰሙትስ እንዴት ያምናሉ? ያለ ሰባኪስ እንዴት ይሰማሉ?'),
  ('d999042e-62b8-5872-a88b-58c67d58319c', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 15, 15, '“መልካሙን የምሥራች የሚያወሩ እግሮቻቸው እንዴት ያማሩ ናቸው?” ተብሎ እንደ ተጻፈ ካልተላኩ እንዴት ይሰብካሉ?'),
  ('f9168c3e-2f53-55ec-a9b0-3631b0db4939', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 16, 16, 'ነገር ግን ሁሉም የወንጌልን ትምህርት የሰሙ አይደለም፤ ኢሳይያስም፥ “አቤቱ፥ ምስክርነታችንንስ ማን አመነ? የእግዚአብሔርስ ክንዱ ለማን ተገለጠ?” ብሎአልና።'),
  ('ffd04e43-73e8-5506-a0cd-b1e6a347e117', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 17, 17, 'ማመን ከመስማት ነው፤ መስማትም በእግዚአብሔር ቃል ነው።'),
  ('2c074947-26e3-5d30-a0ca-43b55e5a70e4', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 18, 18, 'ነገር ግን እንዲህ እላለሁ፤ በውኑ እስራኤል ብቻ አልሰሙምን? መጽሐፍ “ነገራቸው በምድር ሁሉ ተሰማ፤ ቃላቸውም እስከ ዓለም ዳርቻ ደረሰ” ብሎ የለምን?'),
  ('fa9af755-bc0f-542b-a31b-5646a4e52c57', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 19, 19, 'እስራኤል ብቻ አልሰሙምን? ሙሴስ አስቀድሞ እንዲህ ብሎአቸው የለምን? “እኔ በማያስተውሉ ወገኖች አስቀናቸዋለሁ፤ ወገን ባልሆነውም አስቈጣቸዋለሁ።”'),
  ('7abefb21-d51a-5d05-a0c6-cdf56c780824', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 20, 20, 'ኢሳይያስም ደፍሮ፥ “ለአልፈለጉኝ ተገኘሁ፤ ለአልጠየቁኝም ተገለጥሁላቸው” ብሏል።'),
  ('c17d8310-5e09-5d98-a948-ca37f2dfb60a', 'eba30093-0fff-5591-a261-ea0defd8900c', '2b7a741e-7d6b-5710-a4bd-18f6cb9c6f3c', 21, 21, 'ለእስራኤል ግን “ሁልጊዜ ከዳተኞችና ወንጀለኞች ወደሆኑት ሕዝብ እጄን ዘረጋሁ” ብሎአል።'),
  ('69246c4f-197e-5b26-acef-256c8943e297', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 1, 1, 'እንግዲህ እላለሁ፤ እግዚአብሔር ሕዝቡን ጣላቸውን? አይደለም፤ እኔ ደግሞ ከአብርሃም ዘር ከብንያም ወገን የሆንሁ እስራኤላዊ ነኝ።'),
  ('5da56cb6-aafb-5bb9-a705-4baeefb0f1a8', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 2, 2, 'እግዚአብሔር አስቀድሞ ያወቃቸውን ሕዝቡን አልጣላቸውም፤ ኤልያስ እስራኤልን ወደ እግዚአብሔር እንዲህ ሲል በከሰሳቸው ጊዜ መጽሐፍ ያለውን አታውቁምን?'),
  ('be3b65f5-84b8-5cd2-a52c-4c22f06231d9', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 3, 3, '“አቤቱ፥ ነቢያትህን ገደሉ፤ መሠዊያዎችህንም አፈረሱ፤ እኔም ብቻዬን ቀረሁ፤ ነፍሴንም ይሿታል።”'),
  ('1c8ec318-2ec4-5088-a0fe-bc57074e7745', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 4, 4, 'የተገለጠለትስ ምን አለው? “ለጣዖት ያልሰገዱ ሰባት ሺህ ሰዎች ለእኔ አስቀርቻለሁ።”'),
  ('6eeb9f2e-6504-5535-af1f-f688c463a177', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 5, 5, 'እንዲሁም ዛሬ በዚህ ዘመን በጸጋ የተመረጡና በእግዚአብሔር ያመኑ ቅሬታዎች አሉ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b4e4b73c-e43e-5163-a235-89a3410e74e8', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 6, 6, 'በጸጋ ከጸደቁ ግን በሥራቸው አይደለማ፤ በሥራም የሚጸድቁ ከሆነ ጸጋ ጸጋ አይባልም።'),
  ('067bbbe8-d226-5256-a538-71c36850ece0', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 7, 7, 'እንግዲህ ምንድን ነው? እስራኤል የፈለገውን አላገኘም። የተመረጠው ግን አግኝቶአል፤ የቀሩትም ታወሩ።'),
  ('1333fec1-0949-59d2-ac1b-69f4f402b8aa', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 8, 8, 'መጽሐፍ እንዳለ፥ “እስከ ዛሬ ድረስ በዐይናቸው እንዳያዩ በጆሮአቸውም እንዳይሰሙ እግዚአብሔር ደንዛዛ አእምሮን ሰጣቸው።”'),
  ('2f580207-eed7-5c9b-a78d-ec76ffb93de7', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 9, 9, 'ዳዊትም እንዲህ ብሎአል፥ “ማዕዳቸው በፊታቸው ወጥመድና አሽክላ፥ መሰናከያና ፍዳም ትሁንባቸው።'),
  ('e9073404-aacb-50e5-ab86-dda1e9fbb154', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 10, 10, 'እንዳያዩ ዐይኖቻቸው ይጨልሙ፤ ዘወትርም ጀርባቸው ይጕበጥ።”'),
  ('f7cec0f3-338b-58cc-a68e-2077e6b430fc', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 11, 11, 'እንግዲህ እላለሁ፤ ሊወድቁ ተሰናከሉን? አይደለም፤ ነገር ግን እስራኤል ይቀኑ ዘንድ እነርሱ በመሰናከላቸው ለአሕዛብ ድኅነት ሆነ።'),
  ('5fda8b0c-b55c-5b16-ac33-7cfc8094c4b5', '94d2c9b1-b235-5598-a231-fe162a059395', 'fda9163e-9ada-5d8a-ab02-144e2f4da542', 12, 12, 'የእነርሱ መሰናከል ለዓለም ባለጸግነት፥ በደላቸውም ለአሕዛብ ባለጸግነት ከሆነ ፍጹምነታቸውማ እንዴት በሆነ ነበር?'),
  ('d695d954-2687-5849-ac08-04f7ae467c64', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 1, 13, 'ለእናንተ ለአሕዛብ እናገራለሁ፤ እኔ ለአሕዛብ ሐዋርያቸው እንደ መሆኔ መጠን መልእክቴን አከብራታለሁ።'),
  ('a9b3b249-00f6-58bc-aa84-40dedd4aef23', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 2, 14, 'ይህም በዚህ ዘመዶችን አስቀናቸው እንደ ሆነ፥ ከእነርሱ ወገን የሆኑትንም አድን እንደ ሆነ ነው።'),
  ('77699d1e-ccce-59b6-a225-914b10c0c1ba', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 3, 15, 'የእነርሱ መውጣት ለዓለም ዕርቅ ከሆነ ይልቁንም መመለሳቸው ምን ይሆን? ከሙታን በመነሣት የሚገኝ ሕይወት ነው።'),
  ('ade105fd-c5d7-5038-a56c-f03fc90602c9', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 4, 16, 'እርሾው ቅዱስ ከሆነ ቡሆውም እንዲሁ ቅዱስ ነው፤ ሥርዋ ቅዱስ ከሆነም ቅርንጫፎችዋ እንዲሁ ቅዱሳን ይሆናሉ።'),
  ('52eefc86-3679-5066-ad08-1fc674e35a98', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 5, 17, 'ከቅርንጫፎችዋ አንዳንዶቹ ቢሰበሩ የዱር ወይራ የሆንህ አንተን በእነርሱ ፋንታ ተከሉ፤ የእነርሱንም ሥርነት አገኘህ፤ እንደ እነርሱም ዘይት ሆንኽ።'),
  ('d94b327f-343a-5a83-a8d9-f7b6d8c29e66', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 6, 18, 'በቅርንጫፎች ላይ አትኵራ፤ ብትኰራ ግን ሥሩ አንተን ይሸከምሃል እንጂ አንተ ሥሩን የምትሸከመው አይደለም።'),
  ('de65c43d-1738-5af8-af23-d5d80812d208', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 7, 19, 'ቅርንጫፎችዋ ተሰበሩ፤ በእነርሱም ፋንታ “እኔ የዘይት ቅርንጫፍ ሆንሁ” ትል ይሆናል።'),
  ('21e9ff8a-2983-57fd-adb1-2a84b4aea95c', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 8, 20, 'አላመኑምና ተሰበሩ፤ አንተ ግን ስለ አመንህ ቆመሃል፤ እንግዲህ ፈርተህ ኑር እንጂ ራስህን ከፍ ከፍ አታድርግ።'),
  ('a9fecd4f-ab7f-5bcc-a70e-a2ac82a6e716', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 9, 21, 'እግዚአብሔር በተፈጥሮአቸው ቅርንጫፎች ለነበሩ ለእነዚያ ከአልራራላቸው ለአንተም አይራራልህም፤'),
  ('3c9a431a-a1de-5e61-aaa1-bc258eff5a7e', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 10, 22, 'እንግዲህ የእግዚአብሔርን ርኅራኄውንና ጭካኔውን አስተውል፤ የወደቁትን ቀጣቸው፤ አንተን ግን ይቅር እንዳለህ ብትኖር ማረህ፤ ያለዚያ ግን አንተም ትቈረጣለህ።'),
  ('a5cccf52-6c20-5cff-af38-0365605d84dd', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 11, 23, 'እነርሱም ባለማመናቸው ጸንተው ባይኖሩ ይተከላሉ። እግዚአብሔር ዳግመና ሊተክላቸው ይችላልና።'),
  ('c8280fac-e13d-5f52-a8a1-20d93b770a72', '94d2c9b1-b235-5598-a231-fe162a059395', '842cb574-684c-5b4e-a1f7-6f21ce687c7e', 12, 24, 'አንተ የዱር ወይራ፥ አንተን ስንኳ ከበቀልህበት ቈርጦ ባልበቀልህበት በመልካሙ ዘይት ስፍራ ከተከለህ፥ ይልቁን ጥንቱን ዘይት የነበሩትን እነዚያን በበቀሉበት ስፍራ እንዴት አብልጦ ሊተክላቸው አይችልም?'),
  ('87ffa47d-4f6f-5547-a630-839a465130f7', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 1, 25, 'ወንድሞቻችን፥ እና ዐዋቂዎች ነን እንዳትሉ ይህን ምሥጢር ልታውቁ እወዳለሁ፦ አሕዛብ ሁሉ እስኪገቡ ድረስ ከእስራኤል እኩሌቶችን የልብ ድንቍርና አግኝቶአቸዋልና።'),
  ('4efe19d4-f88f-5364-aded-37e1bc119036', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 2, 26, 'ከዚህ በኋላም መላው እስራኤል ይድናሉ፤ መጽሐፍ እንዲህ እንዳለ፥ “አዳኝ ከጽዮን ይወጣል፤ ከያዕቆብም ኀጢአትን ያስወግዳል።'),
  ('a2f9f2f4-2366-597f-af9e-72237d098bd9', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 3, 27, 'ኀጢአታቸውንም ባራቅሁላቸው ጊዜ ከእነርሱ ጋር የምገባው ኪዳን ይህ ነው።”'),
  ('c284ae77-9aed-5383-a487-5be0384ddc5e', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 4, 28, 'በወንጌል በኩል ስለ እናንተ ጠላቶቻችን ናቸው፤ በምርጫ በኩል ግን ስለ አባቶች ወዳጆች ናቸው።'),
  ('0640ea95-9416-5bc5-a798-3d2fefbd2865', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 5, 29, 'በእግዚአብሔር ጸጋና በመጥራቱ ጸጸት የለምና።'),
  ('48ad6d94-86c5-5989-ace3-3b90b43233b6', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 6, 30, 'ቀድሞ እናንተ እግዚአብሔርን እንደ አልታዘዛችሁት፥ ዛሬ ግን በእነርሱ አለመታዘዝ ይቅር እንዳላችሁ፥'),
  ('8f317dc4-6b93-5ffc-a3b2-748bab7cb0c1', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 7, 31, 'እንዲሁም እናንተ በተማራችሁት ምሕረት እነርሱ ምሕረትን እንዲያገኙ እነርሱ ዛሬ አልታዘዙትም።'),
  ('25408f5f-8c67-550b-a6eb-f5d5485e484f', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 8, 32, 'እግዚአብሔር ሁሉን ይቅር ይለው ዘንድ ሁሉን በኀጢአት ውስጥ ዘግቶታልና።'),
  ('9385f450-8525-5145-af95-78ec2d223e88', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 9, 33, 'የእግዚአብሔር ባለጠግነት፥ ጥበብና ዕውቀት እንዴት ጥልቅ ነው! ለመንገዱም ፍለጋ የለውም፤ ፍርዱንም የሚያውቀው የለም።'),
  ('a8ae092b-2923-5f78-a55a-59ba80fcdb7f', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 10, 34, '“የእግዚአብሔርን ዐሳቡን ማን ያውቃል? ወይስ ማን ተማከረው?'),
  ('2d9b2e47-24c3-5856-acb8-24279c24efef', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 11, 35, 'ብድሩን ይከፍል ዘንድ ለእርሱ አስቀድሞ ማን አበደረው?”'),
  ('26516648-6487-5759-a632-0c7b7ddfe4ee', '94d2c9b1-b235-5598-a231-fe162a059395', 'cb4ba706-4233-5a7b-a78f-186457443d77', 12, 36, 'ሁሉ ከእርሱ፥ በእርሱና ለእርሱ ነውና፤ ለእርሱም ለዘለዓለም ክብር ምስጋና ይሁን። አሜን።'),
  ('2e3d94f8-6623-5a37-adab-d10b18034af2', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 1, 1, 'ወንድሞቻችን፥ ሰውነታችሁን ለእግዚአብሔር ሕያውና ቅዱስ፥ ደስ የሚያሰኝም መሥዋዕት አድርጋችሁ ታቀርቡ ዘንድ በእግዚአብሔር ርኅራኄ እማልዳችኋለሁ። ይህም በዕውቀት የሚሆን አገልግሎታችሁ ነው።'),
  ('c75a4db5-4686-5b10-ad69-a6bb699a2711', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 2, 2, 'ይህን ዓለም አትምሰሉ፤ ልባችሁንም አድሱ፤ እግዚአብሔር የሚወደውን መልካሙንና እውነቱን፥ ፍጹሙንም መርምሩ።'),
  ('82626141-9c16-5f34-a9f6-66bf6a04d361', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 3, 3, 'በተሰጠኝ በእግዚአብሔር ጸጋ ሁላችሁም እንዳትታበዩ እነግራችኋለሁ፤ ራሳችሁን ከዝሙት የምታነጹበትን ዐስቡ እንጂ ትዕቢትን አታስቡ፤ ሁሉም እንደ እምነቱ መጠን እግዚአብሔር እንደ አደለው ይኑር።'),
  ('1f264c09-892e-5f88-a91c-bd67aa5537b3', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 4, 4, 'በአንዱ ሰውነታችን ብዙ የአካል ክፍሎች እንዳሉ፥ ሥራቸውም ልዩ ልዩ እንደ ሆነ፥'),
  ('fe5f4c90-2adb-58e9-afb9-9a0f6582f5ee', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 5, 5, 'እንዲሁ ሁላችን ብዙዎች ስንሆን በክርስቶስ አንድ አካል ነን፤ እርስ በርሳችንም እያንዳንዳችን የሌላው አካሎች ነን፤ ስጦታውም ልዩ ልዩ ነው፤'),
  ('89907e27-f679-54ea-a111-f0e2f563b3a8', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 6, 6, 'እግዚአብሔርም በሰጠን ጸጋ መጠን ልዩ ልዩ ስጦታ አለን። ትንቢት የሚናገር እንደ እምነቱ መጠን ይናገር።'),
  ('71908044-c2d4-559c-ad70-81b4aeee9c9a', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 7, 7, 'የሚያገለግልም በማገልገሉ ይትጋ፤ የሚያስተምርም በማስተማሩ ይትጋ፤'),
  ('c7c79ce6-3611-5d88-acc2-db29867372e0', '258e9109-b024-5148-afde-cb739993e28d', '48284fb0-6f09-5d7a-a680-99c52682ebd2', 8, 8, 'የሚመክርም በመምከሩ ይትጋ፤ የሚሰጥም በልግስና ይስጥ፤ የሚገዛም በትጋት ይግዛ፤ የሚመጸውትም በደስታ ይመጽውት።'),
  ('0cbb9039-8c01-52d8-a7b4-8e0ce4b964ee', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 1, 9, 'ፍቅራችሁ ያለ ግብዝነት ይሁን፤ ከክፉ ራቁ፤ በጎውንም ያዙ፤ ለጽድቅ አድሉ፤'),
  ('b84023f0-d8ec-58c7-a4a1-0b8a82a153dd', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 2, 10, 'እርስ በርሳችሁ በወንድማማችነት መዋደድ ተዋደዱ፤ የምትራሩም ሁኑ፤ እርስ በርሳችሁ ተከባበሩ፤ መምህሮቻችሁንም አክብሩ።'),
  ('9ecc8e49-4a2f-55ab-a550-820cdf78af75', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 3, 11, 'ለሥራ ከመትጋት አትስነፉ፤ በመንፈስ ሕያዋን ሁኑ፤ ለእግዚአብሔር ተገዙ፤'),
  ('73d3428e-6220-52c4-a562-9702aeede2f5', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 4, 12, 'በተስፋ ደስ ይበላችሁ፤ በመከራ ታገሡ፤ ለጸሎት ትጉ።'),
  ('1568b95c-3707-5255-a4d2-10a91759762d', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 5, 13, 'በችግራቸው ቅዱሳንን ለመርዳት ተባበሩ፤ እንግዳ መቀበልንም አዘውትሩ።'),
  ('f874ac2e-7f4a-52f6-aeb4-08131a6d06b8', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 6, 14, 'የሚያሳድዱአችሁን መርቁ፤ መርቁ እንጂ አትርገሙ።'),
  ('6d4933cb-4e31-552e-a91a-6675cb6900cd', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 7, 15, 'ደስ ከሚለው ጋር ደስ ይበላችሁ፤ ከሚያለቅሰው ጋርም አልቅሱ።'),
  ('1afe7cbe-3721-591d-a193-865d7b7d36be', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 8, 16, 'እርስ በርሳችሁም በአንድ ዐሳብ ተስማሙ፤ ትዕቢትን ግን አታስቡ፤ ራሱን የሚያዋርደውንም ሰው ምሰሉ፤ እና ዐዋቆች ነን አትበሉ።'),
  ('a55a7158-a9da-5250-a0f8-b031045e991c', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 9, 17, 'ክፉ ላደረገባችሁም ክፉ አትመልሱለት፤ በሰው ሁሉ ፊት በጎውን ተነጋገሩ።'),
  ('26c4ead0-8c07-5242-ab91-b48330c18b5d', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 10, 18, 'ቢቻላችሁስ ከሰው ሁሉ ጋር በሰላም ኑሩ።'),
  ('57f5ecc8-5407-5500-a8c4-564595b8caac', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 11, 19, 'ወንድሞቻችን፥ ራሳችሁ አትበቀሉ፤ ቍጣን አሳልፏት፥ “እኔ እበቀላለሁ፤ እኔ ብድራትን እከፍላለሁ ይላል እግዚአብሔር” ተብሎ ተጽፎአልና።'),
  ('b8f9b597-e7b9-52a1-a1dd-db59bbcc42a2', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 12, 20, 'ጠላትህ ቢራብ አብላው፤ ቢጠማም አጠጣው፤ ይህን ብታደርግ የእሳት ፍሕም በራሱ ላይ ትከምራለህ።'),
  ('b4a0ba25-bbf8-5fcd-af57-612fcbb7e466', '258e9109-b024-5148-afde-cb739993e28d', '2c5462b3-eda1-536f-aa7b-41d382598da7', 13, 21, 'ክፉውን በመልካም ሥራ ድል ንሣው እንጂ ክፉውን በክፉ ድል አትንሣው።'),
  ('dc39cf86-b447-5aa8-a02c-7b10e313aa4d', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 1, 1, 'ሰው ሁሉ በበላይ ላሉ ባለሥልጣኖች ይገዛ፤ ከእግዚአብሔር ከአልተገኘ በቀር ሥልጣን የለምና፤ ያሉትም ባለሥልጣኖች በእግዚአብሔር የተሾሙ ናቸው።'),
  ('b12468e3-03f6-596b-a9e5-71059d1d61b1', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 2, 2, 'ለባለሥልጣን አልገዛም ያለ የእግዚአብሔርን ትእዛዝ እንቢ ማለቱ ነው፤ መገዛትን እንቢ የሚሉም በራሳቸው ላይ ቅጣትን ያመጣሉ።'),
  ('8ce658d0-18bb-58eb-a18e-5c7412e6f790', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 3, 3, 'ሹሞች ሥራው ክፉ ለሆነ ሰው እንጂ መልካም ለሚሠራ የሚአስፈሩ አይደሉም፤ ሹሞችን እንዳትፈራ ብትፈልግ መልካም አድርግ፤ እነርሱ ደግሞ ያመሰግኑሃል፤'),
  ('71486b80-4da4-5640-ae58-79f92965659a', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 4, 4, 'አንተ ሥራህን ታሳምር ዘንድ የእግዚአብሔር መልእክተኞች ናቸውና። ክፉ ብታደርግ ግን ፍራ፤ ሰይፍ የታጠቁም ለከንቱ አይደለም፤ ክፉ አድራጊዎችን ለመቅጣት የእግዚአብሔር አገልጋዮች ናቸውና።'),
  ('996378e0-5cf3-5a14-a841-54a8ac693b17', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 5, 5, 'ስለዚህ ቍጣን ስለ መፍራት ብቻ አይደለም፤ ነገር ግን ስለ ሕሊና ደግሞ መገዛት ግድ ነው።'),
  ('99fd1d9b-11be-530c-a6f5-e26ea707e201', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 6, 6, 'ስለዚህም ግብር ታገቡላቸዋላችሁ፤ ለዚህ ሥራ የተሾሙ የእግዚአብሔር አገልጋዮች ናቸውና፤'),
  ('d3e77acc-028d-5f10-a176-659c25826dd3', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '05bdd07d-538b-5221-a770-dee8ca355dc0', 7, 7, 'ለሁሉም እንደሚገባው አድርጉ፤ ግብር ለሚገባው ግብርን ስጡ፤ ቀረጥ ለሚገባው ቀረጥን ስጡ፤ ዐሥራት ለሚገባው ዐሥራትን ስጡ፤ ሊፈሩት የሚገባውን ፍሩ፤ ክብር የሚገባውንም አክብሩ።'),
  ('8eec7638-ee77-5bb4-a67c-dcf635305d17', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 1, 8, 'እርስ በርሳችሁ ከመዋደድ በቀር ለማንም ዕዳ አይኑርባችሁ፤ ባልንጀራውን የወደደ ግን ሕግን ሁሉ ፈጸመ።'),
  ('6bde5aec-3303-5eb2-aacb-2b94ced45f28', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 2, 9, 'በኦሪት እንዲህ ብሎአልና፥ “አታመንዝር፤ አትግደል፤ አትስረቅ፤ በሐሰት አትመስክር፥ አትመኝ፤” ደግሞ ሌላ ትእዛዝ አለ፤ ነገር ግን የሁሉም ራስ “ ባልንጀራህን እንደ ራስህ ውደድ” የሚለው ነው።'),
  ('e885b5f6-05c1-5c7a-a56d-dccb82294465', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 3, 10, 'ባልንጀራዉን የሚወድ በባልንጀራዉ ላይ ክፉ ሥራ አይሠራም፤ ስለዚህ ፍቅር የሕግ ፍጻሜ ነው።'),
  ('f237fd2c-e0d7-5e81-aa62-f7c0674a38eb', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 4, 11, 'ከእንቅልፍ የምትነቁበት ጊዜ እንደ ደረሰ ዕወቁ፤ ካመንበት ጊዜ ይልቅ መዳናችን ዛሬ ወደ እና ደርሳለችና።'),
  ('bb8d0018-f29f-5a08-a86d-9aa8d65ea5d3', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 5, 12, 'ሌሊቱ አልፎአል፤ ቀኑም ቀርቦአል። እንግዲህ የጨለማን ሥራ ከእና እናርቅ፤ የብርሃንንም ጋሻ ጦር እንልበስ።'),
  ('c226ce49-dc19-5dee-aff5-3892b2556496', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 6, 13, 'በቀን እንደሚሆን በጽድቅ ሥራ እንመላለስ፤ በዘፈንና በስካር፥ በዝሙትና በመዳራትም አይሁን፤ በክርክርና በቅናትም አይሁን።'),
  ('c9a8acd4-4cd2-52ea-a7f9-4a519d1855a9', 'fe8a2d51-811e-5f6e-a6cf-1b6d46d20efa', '84f42b83-552f-55a9-aaee-0c30953ffa47', 7, 14, 'ነገር ግን ጌታችን ኢየሱስ ክርስቶስን ልበሱት፤ የሥጋችሁንም ምኞት አታስቡ።'),
  ('9ecfdcdd-5eb9-5797-a1fc-42e2996cf119', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 1, 1, 'እምነቱ ደካማ የሆነውን ሰው ታገሡት፤ በዐሳቡም አትፍረዱ።'),
  ('4594d556-8022-5411-a5c9-f7d443bd4721', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 2, 2, 'ሁሉን ይበላ ዘንድ እንደ ተፈቀደለት የሚያምን ሁሉን ይብላ፤ የሚጠራጠር ግን አትክልት ይብላ።'),
  ('22bb1c20-41ea-5692-a580-4135cf4ecfdb', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 3, 3, 'የሚበላውም የማይበላውን አይናቀው፤ የማይበላውም የሚበላውን አይንቀፈው፤ ሁሉንም እግዚአብሔር አውቆአቸዋልና።'),
  ('014db10f-0f15-5cd1-adf8-c48f226b8736', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 4, 4, 'እንግዲህ የሌላውን ሎሌ የምትነቅፍ አንተ ማነህ? እርሱ ቢቆም ወይም ቢወድቅ ለጌታው ነው። ነገር ግን እግዚአብሔር ሊያነሣው ይችላልና ይቆማል።'),
  ('af349b56-f1c1-50a9-af4e-639e0531c88f', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 5, 5, 'ከቀን ቀን የሚከለከል አለና፤ ዘወትርም የሚከለከል አለና፤ ነገር ግን ሁሉም ልቡ እንደ ወደደ ያድርግ።'),
  ('a727c7ad-ed02-5dc2-a62f-bba88a3a5044', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 6, 6, 'አንዳንድ ቀን የተከለከለም ለእግዚአብሔር ተከለከለ፤ ዘወትር የተከለከለም ለእግዚአብሔር ተከለከለ፤ የበላም ለእግዚአብሔር በላ፤ እግዚአብሔርንም ያመሰግነዋል፤ ያልበላም ለእግዚአብሔር አልበላም፤ እግዚአብሔርንም ያመሰግነዋል።'),
  ('251b6bea-bc79-5453-a739-867b60551eff', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 7, 7, 'ከመካከላችንም ለራሱ የሚኖር፥ ለራሱም የሚሞት የለም።'),
  ('775b73b0-3569-52c3-a38b-d0bee8cc570c', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 8, 8, 'በሕይወት ብንኖርም ለእግዚአብሔር እንኖራለን፤ ብንሞትም ለእግዚአብሔር እንሞታለን፤ እንግዲህ በሕይወት ብንኖርም ብንሞትም ለእግዚአብሔር ነን።'),
  ('b38c63bc-d6cd-56af-a531-6347a458e5af', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 9, 9, 'ስለዚህ ሕያዋንንና ሙታንን ይገዛ ዘንድ ክርስቶስ ሞተ፥ ተነሣም።'),
  ('227f452b-fe3f-56a5-a8b5-fbb997653fa9', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 10, 10, 'እንግዲህ በወንድምህ ላይ የምትፈርድ አንተ ምንድን ነህ? ወንድምህንስ የምትነቅፍ አንተ ምንድን ነህ? ሁላችን በክርስቶስ የፍርድ ዙፋን ፊት እንቆማለንና።'),
  ('e7591b70-09cb-5c79-aadc-8bf3d090e359', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 11, 11, 'እግዚአብሔር እንዲህ ብሎአልና፥ “እኔ ሕያው ነኝ፤ ጕልበትም ሁሉ ለእኔ ይሰግዳል፤ አንደበትም ሁሉ ለእኔ ይገዛል።”'),
  ('b539f963-938b-5fae-a13e-9076d9d75700', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '15638f96-2715-570f-aaba-da2182635824', 12, 12, 'እነሆ፥ ሁላችን በእግዚአብሔር ዘንድ እንደምንመረመር ታወቀ።'),
  ('e68246a5-2284-5c31-a913-b314bd9bf6c5', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 1, 13, 'እንግዲህ ከዛሬ ጀምሮ እርስ በርሳችን አንነቃቀፍ፤ ይልቁንም ለወንድም እንቅፋትን ወይም ማሰናከያን ማንም እንዳያኖር ይህን ዐስቡ።'),
  ('780b6d1f-b62f-5e8b-aa36-908f2d229c3b', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 2, 14, 'በራሱ ርኩስ የሆነ ነገር እንደሌለ በጌታችን በኢየሱስ ሆኜ ዐውቄአለሁ፤ ተረድቼአለሁም፤ ነገር ግን ማናቸውም ነገር ርኩስ እንደሚሆን ለሚያስብ ያ ለእርሱ ርኩስ ነው።'),
  ('a78fd2a5-767a-567f-ac02-0153ccb50b94', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 3, 15, 'በመብል ምክንያት ባልንጀራህን የምታሳዝን ከሆንህ ፍቅር የለህም፤ በውኑ ክርስቶስ ስለ እርሱ የሞተለት ያ ሰው በመብል ምክንያት ሊጐዳ ይገባልን?'),
  ('8ce27b34-646a-521b-a38a-7fe2692b003d', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 4, 16, 'እንግዲህ ጌታችን የሰጠንን መልካሙን ነገር አታሰድቡ።'),
  ('9ca069ef-2839-5e94-ab72-c780287a9b46', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 5, 17, 'የእግዚአብሔር መንግሥት ጽድቅና ሰላም፤ በመንፈስ ቅዱስም የሆነ ደስታ ነው እንጂ መብልና መጠጥ አይደለምና።'),
  ('2afe73ae-84ac-515d-aac1-d341f8521891', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 6, 18, 'እንዲህ አድርጎ ለክርስቶስ የሚገዛ ግን እግዚአብሔርን ደስ የሚያሰኝና በሰውም ዘንድ የተመረጠ ነው።'),
  ('63576597-c2ea-5763-a43c-3af758e21a88', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 7, 19, 'አሁንም ወንድማችን ይታነጽ ዘንድ ሰላምን እንከተላት።'),
  ('bf4e3523-dc1e-56d3-a148-da76747689fa', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 8, 20, 'በመብል ምክንያት የእግዚአብሔርን ፍጥረት አናፍርስ፤ ለንጹሓን ሁሉ ንጹሕ ነው፤ ለሰውስ ክፉው ነገር በመጠራጠር መብላት ነው።'),
  ('f64c00e6-2d30-5e12-ac0e-cb383b74f3b8', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 9, 21, 'ለወንድም ዕንቅፋት ከመሆን ሥጋን አለመብላት ወይንንም አለመጠጣት ይሻላል።'),
  ('580c76c0-24e0-55a2-a412-f4d9d713429e', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 10, 22, 'እምነት ካለህ በእግዚአብሔር ፊት ባመንኸው እምነት ራስህን አጽና፤ ባገኘው አእምሮም ራሱን የሚዘልፍ ብፁዕ ነው።'),
  ('7a85abb0-b8cb-544b-a09d-ed3380854519', 'c8645d9f-54ba-5936-aeee-2a0f0a41a94a', '3ca1b6e7-35c3-56f0-ad60-6cbf1c130293', 11, 23, 'የሚጠራጠር ግን ቢበላ ይፈረድበታል፤ በማመን አልሆነምና፤ ያለ እምነትም የሚደረግ ሁሉ ኀጢአትና በደል ነው።'),
  ('0234e662-c909-5090-a499-2d3ccd6d07aa', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'ad842397-68de-5382-aba2-4571984090be', 1, 1, 'የሚገባስ እና ብርቱዎች ደካሞችን በድካማቸው እንድንረዳቸው ነው፤ ለራሳችንም አናድላ።'),
  ('b6b0e6a3-4157-5995-a8df-e6ca72e8ea80', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'ad842397-68de-5382-aba2-4571984090be', 2, 2, 'ሁላችንም በእውነትና በመልካም ሥራ ይታነጽ ዘንድ ለባልንጀራችን እናድላ።'),
  ('9d00c5e7-4ce5-5c98-a14a-a5e1a4a5df6f', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'ad842397-68de-5382-aba2-4571984090be', 3, 3, 'ክርስቶስም፥ “አንተን የነቀፉበት ነቀፋ በእኔ ላይ ደረሰ” ብሎ መጽሐፍ እንደ ተናገረ ለራሱ ያደላ አይደለም።'),
  ('4b8e25fc-9ba7-5ea3-aba1-f3b4397a0786', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'ad842397-68de-5382-aba2-4571984090be', 4, 4, 'የተጻፈው ሁሉ በመታገሣችንና መጻሕፍትን በመታመናችን ተስፋችንን እናገኝ ዘንድ እና ልንማርበት ተጻፈ።'),
  ('b4e972ae-7aad-5468-a7ad-cf863c780461', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'ad842397-68de-5382-aba2-4571984090be', 5, 5, 'የትዕግሥትና የመጽናናት አምላክ እግዚአብሔር እንደ ኢየሱስ ክርስቶስ ፈቃድ እርስ በርሳችን አንድ ዐሳብ መሆንን ይስጠን።'),
  ('6a3516ca-1d38-5d3f-a297-bd98acbe2e2d', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'ad842397-68de-5382-aba2-4571984090be', 6, 6, 'ሁላችን አንድ ሆነን በአንድ አፍ በጌታችን በኢየሱስ ክርስቶስ እግዚአብሔርን እናመሰግነው ዘንድ።'),
  ('9493abf4-f2ba-5e95-a937-99d2455f21f5', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 1, 7, 'አሁንም ባልንጀሮቻችሁን ተቀበሉ፤ ክርስቶስ ለእግዚአብሔር ክብር ተቀብሎአችኋልና።'),
  ('554b0356-caef-59f6-a905-d145ae1777d5', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 2, 8, 'እንግዲህ ክርስቶስ የእግዚአብሔርን ቃል እውነት ለማድረግ የአባቶቻችንንም ተስፋ ያጸና ዘንድ ለግዝረት መልእክተና ሆነ እላለሁ።'),
  ('6521f689-060b-57c2-a588-2e7b54678dc1', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 3, 9, 'አሕዛብም እግዚአብሔርን ያመሰግኑታል፤ ይቅር ብሎአቸዋልና፤ መጽሐፍ እንዲህ ብሎአልና፥ “አቤቱ፥ ስለዚህ በአሕዛብ መካከል እገዛልሃለሁ፤ ስምህንም አመሰግናለሁ።”'),
  ('94e6aa8b-bfda-59fd-ad85-4594ec9f2d1b', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 4, 10, 'ዳግመናም መጽሐፍ እንዲህ ብሎአል፥ “አሕዛብ ከሕዝቡ ጋር ደስ ይበላችሁ።”'),
  ('cc555d01-593e-541d-a8ad-6a87ecce1f2b', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 5, 11, 'ዳግመናም እንዲህ አለ፥ “አሕዛብ ሁላችሁ እግዚአብሔርን አመስግኑ፤ ሕዝቡም ሁሉ ያመሰግኑታል።”'),
  ('16c3ab87-6e5c-5bb5-a0dc-79db10800ef0', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 6, 12, 'ኢሳይያስም ደግሞ እንዲህ ብሎአል፥ “የእሴይ ዘር ይነሣል፤ ከእርሱ የሚነሣውም ለአሕዛብ ንጉሥ ይሆናል፤ ሕዝቡም ተስፋ ያደርጉታል።”'),
  ('6d6abff3-e4fc-505f-a30c-ff0684ca5e3b', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'bbd566fd-2a01-53be-a1d8-eb486974b4ce', 7, 13, 'የተስፋ አምላክ እግዚአብሔርም በመንፈስ ቅዱስ ኀይል በተስፋ ያበዛችሁ ዘንድ በእምነት ደስታንና ሰላምን ሁሉ ይፈጽምላችሁ።'),
  ('e04deb33-9fcb-5005-a9dd-0950c7002cd5', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 1, 14, 'ወንድሞች ሆይ፥ እኔም በጎ ምግባርን ሁሉ እንደምትፈጽሙ እታመንባችኋለሁ፤ እናንተ ፍጹም ዕውቀትን የተመላችሁ ናችሁ፤ ባልንጀሮቻችሁንም ልታስተምሩአቸው ትችላላችሁ።'),
  ('42cf7deb-9d2f-546f-a2fe-04875a49dc51', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 2, 15, 'ከእግዚአብሔር ስለ አገኘሁት ጸጋ ላሳስባችሁ በአንዳንድ ቦታ በድፍረት ጻፍሁላችሁ።'),
  ('a1cc901b-083e-5d05-a7ad-a86f411773b8', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 3, 16, 'በአሕዛብ መካከል ኢየሱስ ክርስቶስን አገለግል ዘንድ፥ ለእግዚአብሔር ወንጌልም እገዛ ዘንድ፥ በእኔ ትምህርት አሕዛብ በመንፈስ ቅዱስ የተወደደና የተመረጠ መሥዋዕት ይሆኑ ዘንድ።'),
  ('4c12a1a4-ed64-5652-a92d-89b03f001e39', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 4, 17, 'ለእኔም በእግዚአብሔር ዘንድ መመኪያዬ ኢየሱስ ክርስቶስ ነው።'),
  ('772d4581-76a4-5ce6-a937-9b2eaf94078d', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 5, 18, 'አሕዛብም እንዲያምኑ ክርስቶስ በቃልም በሥራም ያደረገልኝን እናገር ዘንድ እደፍራለሁ።'),
  ('39f0554c-2a44-5f23-a56c-6418adb698fb', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 6, 19, 'በኀይልና በተአምራት፥ በመንፈስ ቅዱስ ኀይልና ድንቅ ሥራን በመሥራትም፥ ከኢየሩሳሌም አውራጃዎች ጀምሬ እስከ እልዋሪቆን ድረስ እንደ አስተማርሁ፥ የክርስቶስንም ወንጌል ፈጽሞ እንደ ሰበክሁ እናገር ዘንድ እደፍራለሁ።'),
  ('cbb20de6-3fb0-5065-af1e-2e3766eec72b', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 7, 20, 'ወንጌልን ለማስተማር ተጋሁ፤ ነገር ግን በሌላ መሠረት ላይ እንዳላንጽ የክርስቶስ ስም ወደ ተጠራበት አልሄድሁም።'),
  ('734b0598-37c3-5965-a0b4-2fab03013701', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 8, 21, '“ወሬው ያልደረሳቸው ያውቁታል፤ ያልሰሙትም ያስተውሉታል” ብሎ መጽሐፍ እንደ ተናገረ ነው።'),
  ('fa79ca1e-8766-5d1a-a646-e2abe3232d51', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 9, 22, 'ዘወትር ወደ እናንተ ልመጣ እወድድ ነበር፤ ነገር ግን ተሳነኝ።'),
  ('558f08ab-b39f-5de8-acd1-4a819176cdb9', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 10, 23, 'አሁን ግን በዚህ ሀገር ሥራዬን ስለ ጨረስሁ፥ ከብዙ ጊዜም ጀምሮ ወደ እናንተ ልመጣ እተጋ ስለ ነበር፤'),
  ('9ffa29d6-1302-5e2a-a59a-5d8cea701b71', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', '48243817-bf12-5ea1-a717-5614f70103dc', 11, 24, 'ወደ አስባንያ ስሄድ እግረ መንገዴን ላያችሁ ተስፋ አደርጋለሁ፤ ቀደም ብዬ ከእናንተ ጋር ደስ ካለኝ በኋላም ከእናንተ ወደዚያ እሄዳለሁ።'),
  ('5a285319-9911-51a1-a916-77b529045b20', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 1, 25, 'አሁን ግን ቅዱሳንን ለመርዳት ወደ ኢየሩሳሌም እሄዳለሁ።'),
  ('72e6b74a-ea13-5dd1-aeba-59db365df2be', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 2, 26, 'መቄዶንያና አካይያ በኢየሩሳሌም ቅዱሳን መካከል ላሉ ድሆች አስተዋጽፅኦ ለማድረግ ተባብረዋልና።'),
  ('c59399f7-8dfc-507a-aac6-3c0c316fdc2b', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 3, 27, 'የሚገባቸውም ሰለሆነ በመንፈሳዊ ሥራ አሕዛብን ከተባበሩአቸው ለሰውነታቸው በሚያስፈልጋቸው ሊረዱአቸው ይገባል።'),
  ('c412ab3e-9083-5a76-aded-23d17c688497', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 4, 28, 'እንግዲህ ይህን ፍሬ ጨርሼና አትሜ በእናንተ በኩል ወደ አስባንያ እሄዳለሁ።'),
  ('e53f1961-93fa-58fe-adaa-8a5e6cdbd067', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 5, 29, 'ነገር ግን በመጨረሻ ጊዜ በክርስቶስ ወንጌል በረከት ፍጹምነት እንደምትመጣ አምናለሁ።'),
  ('8954e23b-2d3b-52a3-a752-a797959b47aa', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 6, 30, 'ወንድሞች፥ በጸሎታችሁ ስለ እኔ ወደ እግዚአብሔር ከእኔ ጋር ትተጉ ዘንድ በጌታችን በኢየሱስ ክርስቶስና በመንፈስ ቅዱስ ፍቅር እማልዳችኋለሁ።'),
  ('1c747f52-e153-5884-a2b2-069a12b7b476', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 7, 31, 'ይኸውም በኢየሩሳሌም ያሉ ቅዱሳንን በአገልግሎቴ ደስ አሰናቸው ዘንድ በይሁዳ ሀገር ካሉ ዐላውያን እንዲያድነኝ ነው።'),
  ('76c8bdcb-faa1-59a6-ab56-be74f1af3819', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 8, 32, 'እግዚአብሔርም ቢፈቅድ በደስታ ወደ እናንተ መጥቼ ከእናንተ ጋር ዐርፍ ዘንድ ነው።'),
  ('ae2bcfa1-28d5-5ef3-a47a-7d6ececfca40', '8fdfe88f-f63b-5108-af8a-f3d541604e3b', 'f0b2f089-3fda-55a4-a8c6-edcbe52ac5e7', 9, 33, 'የሰላም አምላክ ከእናንተ ጋር ይሁን፤ አሜን።'),
  ('3eed537b-27cf-5d81-a148-0fa58afce103', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 1, 1, 'ለክንክራኦስ ቤተ ክርስቲያን የምትላላከውን እኅታችንን ፌቤንን አደራ እላችኋለሁ፤'),
  ('04458f77-216b-5a3d-a138-3279754c33b2', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 2, 2, 'ለቅዱሳንም እንደሚገባ በጌታችን ተቀበሉአት፤ እርስዋ ለብዙዎች፥ ለእኔም ረዳት ናትና፤ ለችግራችሁም በፈቀዳችሁት ቦታ መድቡአት።'),
  ('450549e9-6792-522d-a8f8-2faf1ec14cd7', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 3, 3, 'በኢየሱስ ክርስቶስ ሥራ ከእኔ ጋር የተባበሩትን ጵርስቅላንና አቂላን ሰላም በሉ፤'),
  ('07aaa43a-631f-566a-a3a7-cd0e4c0de556', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 4, 4, 'ስለ እኔ ሰውነታቸውን ለመከራ አሳልፈው ሰጥተዋልና፤ የማመሰግናቸውም እኔ ብቻ አይደለሁም፤ ከአሕዛብ ያመኑ ምእመናን ሁሉ ያመሰግኑአቸዋል እንጂ።'),
  ('b28d26e6-8fa3-5fc4-ae44-77c1746c24e6', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 5, 5, 'በቤታቸው ያሉትን ማኅበረ ክርስቲያንም ሰላም በሉ፤ ወዳጄ ኤጴኔጦስንም እንዴት ነህ? በሉ፤ ይኸውም በእስያ በክርስቶስ ላመኑ ሁሉ መጀመሪያቸው ነው።'),
  ('46afa0b4-827c-5a78-a048-7ce20f408b93', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 6, 6, 'ለእናንተ ብዙ የደከመችላችሁን ማርያምንም ሰላም በሉ።'),
  ('372a6163-a1a4-5be4-aab4-8c3a9f9eef52', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 7, 7, 'ከዘመዶች ወገን የሚሆኑትን ከእኔ ጋር ያመኑ እንድራናቆስንና ዩልያንን ሰላም በሉ፤ ቀደም ሲል ክርስቶስን እንደ አገለገሉ ሐዋርያት ያውቁአቸዋል።'),
  ('01b4421e-d530-5afd-ac30-d9efbde168d7', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 8, 8, 'በክርስቶስ ወንድሜ የሆነውን አምጵልያጦስን ሰላም በሉ።'),
  ('33f3a1bc-6a40-5618-a582-faa145434336', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 9, 9, 'የክርስቶስን ሥራ በመሥራት የምንተባበረውን ኡሩባኖስን፥ ወዳጄ ስንጣክንንም ሰላም በሉ።'),
  ('38419bfc-f20e-5a39-aa92-a8ebdcf8f3e2', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 10, 10, 'በክርስቶስ የተመረጠውን ኤጤሌንን ሰላም በሉ፤ እነ አርስጠቦሎስንም ሰላም በሉ።'),
  ('2ebbbc80-492f-5286-a635-045e76adc299', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 11, 11, 'ከዘመዶች ወገን የሚሆን ሄሮድዮናን ሰላም በሉ፤ በንርቃሶስ ቤት ያሉትንና በክርስቶስ ያመኑትን ምእመናን ሰላም በሉ።'),
  ('e50f6523-74df-51c8-a16b-acd51f98304e', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 12, 12, 'በጌታችን ስም መከራ የተቀበሉትን የጢሮፊሞናንና የጢሮፊሞስን ወገኖች ሰላም በሉ። በጌታችን ስም ብዙ የደከመች እኅታችንን ጠርሴዳን ሰላም በሉ።'),
  ('0f01dc4e-a9f4-5c9b-a9b0-559c112d62fb', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 13, 13, 'ጌታችን የመረጠው ሩፎንን፥ እናቱንም፥ ለእኔም እናቴ የሆነችውን ሰላም በሉ።'),
  ('12320b41-224e-5438-a417-15f3d63b50d2', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 14, 14, 'አስቀሪጦስን፥ አልሶንጳን፥ ሄርሜስን፥ ጳጥሮባስን፥ ሄርማስን፥ ከእነርሱ ጋር ያሉ ወንድሞቻችንንም ሰላም በሉ።'),
  ('c8d0ce5d-c673-5274-a53a-72dd9dc2e903', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 15, 15, 'ፊሎሎጎስን፥ ዩልያን፥ ኔርዮስን፥ እኅቱንም አሊንጳስን ከእነርሱም ጋር ያሉ ቅዱሳንን ሁሉ ሰላም በሉ።'),
  ('f12f9f07-1112-59a6-a9b0-aaa2574d0943', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 16, 16, 'እርስ በርሳችሁ በተቀደሰ ሰላምታ ሰላም ተባባሉ፤ የክርስቶስ ማኅበረ ክርስቲያንም ሰላም ይሉአችኋል።'),
  ('1d793e7f-29e0-5465-aa69-8266a8c25102', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 17, 17, 'ወንድሞቻችን ሆይ፥ እናንተ የተማራችሁትን ትምህርት የሚቃወሙትን፥ መለያየትንና ማሰናከያን የሚያደርጉትን እንድታውቁባቸው እማልዳችኋለሁ፤ ከእነርሱም ተለዩ፤'),
  ('c1f6fd14-893e-5b57-a38d-e1552c0b3262', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 18, 18, 'እነርሱ ለጌታችን ለኢየሱስ ክርስቶስ ያይደለ ለሆዳቸው ይገዛሉና፤ በነገር ማታለልና በማለዛዘብም የብዙዎች የዋሃንን ልብ ያስታሉ፤'),
  ('40b7e037-a22b-5f5e-a758-25dcd06f8ee8', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 19, 19, 'መታዘዛችሁም በሁሉ ዘንድ ተሰምቶአል፤ እኔም በእናንተ ደስ ይለናል፤ ለመልካም ነገር ጠቢባን፥ ለክፉ ነገርም የዋሃን እንድትሆኑ እፈልጋለሁ።'),
  ('36302b15-a6a2-5737-a100-1c84dbd543a1', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 20, 20, 'የሰላም አምላክም ፈጥኖ ሰይጣንን ከእግራችሁ በታች ይቀጥቅጠው፤ የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከእናንተ ጋር ይሁን፤ አሜን።'),
  ('701e2d56-e561-5711-a471-99e05c1067a9', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 21, 21, 'ከእኔ ጋር በሥራ የሚተባበረው ጢሞቴዎስም፥ ከዘመዶች ወገን የሚሆኑ ሉቅዮስም፥ ኢያሶንም፥ ሱሲ ጴጥሮስም ሰላም ይሉአችኋል።'),
  ('7955daaa-999a-5551-a86e-bdd101c1fbc1', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 22, 22, 'ይህችን መልእክት የጻፍኋት እኔ ጤርጥዮስ በጌታችን ስም ሰላም እላችኋለሁ።'),
  ('0f26d29e-9649-5784-a1f4-c0ca8a388867', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 23, 23, 'እኔንና አብያተ ክርስቲያናትን ሁሉ በእንግድነት የተቀበለ ጋይዮስም ሰላም ብሎአችኋል፤ የከተማው መጋቢ አርስጦስና ወንድማችን ቁአስጥሮስም ሰላም ብለዋችኋል።'),
  ('42f5b792-e7b0-5183-a253-c78f03b3f3e0', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 24, 24, 'ከዓለም አስቀድሞ ምሥጢሩ ተሰውሮ ስለ ነበረ ስለ ኢየሱስ ክርስቶስ በማስተምራት ትምህርት ላይ ሊያጸናችሁ የሚችለው እርሱ እግዚአብሔር ነው።'),
  ('0789255f-a99d-58ff-ac9a-0181323524c2', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 25, 25, 'ይህም በነቢያት ቃልና የዘለዓለም ገዥ በሚሆን በእግዚአብሔር ትእዛዝ በዚህ ወራት ተገለጠ፤ አሕዛብ ሁሉ ይህን ሰምተውና ዐውቀው በእግዚአብሔር ልጅ በኢየሱስ ክርስቶስ ያምኑ ዘንድ።'),
  ('221ce2bc-bbc7-5b9e-a4e3-4e9efbe75ed0', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 26, 26, 'ብቻውን ጠቢብ ለሆነው ለእግዚአብሔር ክብር ይሁን፤ አሜን።'),
  ('fa2568d5-76e8-511d-abd7-5592a971da9d', '4e515452-be8e-558e-aa8e-e2b3bc4c9dd2', '4387f259-880d-591c-a04a-95967fcfe838', 27, 27, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከሁላችሁ ጋር ይሁን፤ አሜን።'),
  ('4ecac20b-689e-596c-a448-eeff66fa2020', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 1, 1, 'በእግዚአብሔር ፈቃድ የኢየሱስ ክርስቶስ ሐዋርያ ሊሆን ከተጠራ ከጳውሎስና ከወንድማችን ከሶስቴንስ፥'),
  ('94fa39a6-fddf-53b4-ab6f-9c6c1089de8b', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 2, 2, 'በቆሮንቶስ ሀገር ላለች ለእግዚአብሔር ቤተ ክርስቲያን በኢየሱስ ክርስቶስ ስም ለከበሩና ቅዱሳን ለተባሉ የእነርሱና የእኛ ጌታ የሆነውን የጌታችን የኢየሱስ ክርስቶስን ስም በየስፍራው ለሚጠሩ ሁሉ፥'),
  ('05d6ba6a-c65c-5df2-ae0c-f88691775bf5', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 3, 3, 'ከአባታችን ከእግዚአብሔር፥ ከጌታችን ከኢየሱስ ክርስቶስ ዘንድ ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('dccaa345-3b3a-5b6f-a172-d2e636a4bac8', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 4, 4, 'ስለ እናንተ በኢየሱስ ክርስቶስ ከእግዚአብሔር ዘንድ ለእናንተ ስለተሰጣችሁ ጸጋ ዘወትር እግዚአብሔርን አመሰግነዋለሁ።'),
  ('7011dda8-85ca-5e45-aa80-559e39449f73', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 5, 5, 'በአነጋገር ሁሉ፥ በዕውቀትም ሁሉ ከብራችሁበታልና።'),
  ('27a18b2d-010d-5a8d-a48d-bf009781d334', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 6, 6, 'ለክርስቶስ መመስከሬ በእናንተ እንደ ጸና መጠን።'),
  ('9c3669c5-44a5-5428-ab67-4aac33df8c9b', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 7, 7, 'ፍጹማንም እንድትሆኑ የጌታችን የኢየሱስ ክርስቶስንም መምጣት ተስፋ አድርጋችሁ ፍጹም ጸጋን እንዳታጡ፥'),
  ('b2d6b50d-daaa-573c-a9c4-34d0f9ba4a51', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 8, 8, 'እርሱም በጌታችን በኢየሱስ ክርስቶስ ቀን ያለ ነውር ትገኙ ዘንድ እስከ ፍጻሜ ያጸናችኋል።'),
  ('eaa27564-a06a-5319-aeca-ab40ade52708', '6d651acf-636a-501b-a761-d0b88b554da7', '0094378b-d295-506a-a03f-4a74cfc49a2b', 9, 9, 'ከልጁ ከጌታችን ከኢየሱስ ክርስቶስ ጋር አንድ ትሆኑ ዘንድ የጠራችሁ እግዚአብሔር የታመነ ነው።'),
  ('bba95877-480e-5dbc-aa18-33dccc50653f', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 1, 10, 'ወንድሞቻችን! አንድ ቃል እንድትናገሩ፥ እንዳታዝኑ፥ ፍጹማንም እንድትሆኑ፥ ሁላችሁንም፦ በጌታችን በኢየሱስ ክርስቶስ ስም እማልዳችኋለሁ፤ እንዳትለያዩም አንድ ልብና አንድ አሳብ ሆናችሁ ኑሩ።'),
  ('1e504275-eacd-5353-a039-8f5e2db1fcd1', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 2, 11, 'ወንድሞቻችን ሆይ! እንደምትጣሉና እንደምትከራከሩ ከቀሎኤስ ወገኖች ስለ እናንተ ነገሩኝ።'),
  ('7f0d5fb4-6713-572a-a6fb-5890cd1e62c4', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 3, 12, 'እነሆ፥ እርስ በርሳችሁ፥ “እኔ የጳውሎስ ነኝ፤ እኔ የአጵሎስ ነኝ፤ እኔ የኬፋ ነኝ፤ እኔ የክርስቶስ ነኝ” የምትሉትን እነግራችኋለሁ።'),
  ('f2557b09-4bd5-58d7-aab1-6f68cce6f20c', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 4, 13, 'ክርስቶስ ተከፍሎአልን? ወይስ በውኑ ጳውሎስ ስለ እናንተ ተሰቅሎአልን? ወይስ በጳውሎስ ስም ተጠምቃችኋልን?'),
  ('cd47b80a-cf53-53ff-a160-4ef2b03f0f42', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 5, 14, 'ከቀርስጶስና ከጋይዮስ በቀር ከእናንተ ወገን ሌላ ስላላጠመቅሁ እግዚአብሔርን አመሰግነዋለሁ።'),
  ('cab60229-ad31-5545-aea0-62dd7b5c1a3f', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 6, 15, 'በእርሱ ስም ተጠመቅን የሚል እንዳይኖር።'),
  ('e53d5635-681b-5ba2-a395-fea0c5403d8a', '6d651acf-636a-501b-a761-d0b88b554da7', 'd919501d-2b99-5059-add1-95113d59777c', 7, 16, 'ነገር ግን የእስጢፋኖስን ቤተ ሰብእ አጥምቄአለሁ፤ እንግዲህ ሌላም ያጠመቅሁት እንዳለ አላውቅም።'),
  ('9c6a697d-8306-5715-a722-be8a53740ce1', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 1, 17, 'ክርስቶስ ወንጌልን ለመስበክ እንጂ ለማጥመቅ አልላከኝምና፥ የክርስቶስን መስቀሉን ከንቱ እንዳናደርግ ነገርን በማራቀቅ አይደለም።'),
  ('8f6a9697-a021-5320-a201-88eda8f444e2', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 2, 18, 'የመስቀሉ ነገር በሚጠፉ ሰዎች ዘንድ ስንፍና ነውና፥ ለምንድነው ለእኛ ግን የእግዚአብሔር ኀይል ነው።'),
  ('8cb6ddd7-d854-5942-af9e-5984f530fd70', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 3, 19, 'መጽሐፍ እንዲህ ብሎአልና፥ “እኔ የጥበበኞችን ጥበብ አጠፋለሁ፤ የመካሪዎችንም ምክር እንቃለሁ።”'),
  ('ca03d0a6-4381-54eb-aba3-8b88bf48b4ad', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 4, 20, 'እንግዲህ ጥበበኛ ማን ነው? ጸሓፊስ ማን ነው? ይህን ዓለምስ የሚመረምረው ማን ነው? እግዚአብሔር የዚህን ዓለም ጥበብ ስንፍና አላደረገውምን?'),
  ('97b3f6b4-0e4f-5f46-a455-f762d12d6d25', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 5, 21, 'ሰዎች በጥበባቸው በማያውቁት በእግዚአብሔር ጥበብ ስንፍና በሚመስላቸው ትምህርት ያመኑትን ሊያድናቸው እግዚአብሔር ወድዶአልና።'),
  ('7b0561ea-77dc-57a1-aab7-01866909f7c2', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 6, 22, 'አይሁድ ምልክትን ይጠይቃሉ፤ የጽርዕ ሰዎችም ጥበብን ይሻሉ።'),
  ('0d764cbb-2093-58dd-aeab-0549486f5dc6', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 7, 23, 'እኛ ግን የተሰቀለውን ክርስቶስን እንሰብካለን፤ ይህም ለአይሁድ ማሰናከያ ለአሕዛብም ስንፍና ነው።'),
  ('f9f985c9-09fb-5f4a-ae21-a9210f1045de', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 8, 24, 'ለእኛ ለዳንነው ግን ከአይሁድ፥ ከአረሚም ብንሆን ክርስቶስ የእግዚአብሔር ኀይል ነው፤ የእግዚአብሔርም ጥበብ ነው።'),
  ('efd6a545-9a43-517e-a83c-d1c49b5d64df', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 9, 25, 'የእግዚአብሔር ስንፍና ከሰው ይልቅ ይጠበባልና፥ የእግዚአብሔርም ድካም ከሰው ይልቅ ይበረታልና።'),
  ('b77ea36c-7ecc-5ebf-ab53-4753b4676ea4', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 10, 26, 'ወንድሞቻችን! እንግዲህ እንዴት እንደ ተጠራችሁ እዩ፤ በሥጋ እጅግ ብዙዎች ዐዋቂዎች አይደላችሁምና፥ ብዙዎች ኀያላንም አይደላችሁምና፥ በዘመድም ብዙዎች ደጋጎች አይደላችሁምና።'),
  ('3e764e4a-2078-5df3-ac7c-3bc1a419ea39', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 11, 27, 'ነገር ግን እግዚአብሔር ጥበበኞችን ሊያሳፍር የዚህን ዓለም ሰነፎች መረጠ፤ ኀይለኞችንም ያሳፍር ዘንድ እግዚአብሔር የዚህን ዓለም ደካሞች መረጠ።'),
  ('d4068888-4e66-5ecd-a358-4e21e8408620', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 12, 28, 'አለን የሚሉትንም ያሳፍር ዘንድ ዘመድ የሌላቸውንና የተናቁትን፥ ከቍጥርም ያልገቡትን እግዚአብሔር መረጠ።'),
  ('9519232b-044b-5c31-af2e-d1d27f1f7d4a', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 13, 29, 'ሰው ሁሉ በእግዚአብሔር ፊት እንዳይመካ።'),
  ('a494f2ad-a872-5660-a599-282e9f2df2e7', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 14, 30, 'እናንተም በኢየሱስ ክርስቶስ ከእርሱ ናችሁ፤ በእርሱም ከእግዚአብሔር ጥበብንና ጽድቅን፥ ቅድስናንና ቤዛነትን አገኘን።'),
  ('a750e576-e99b-5331-a127-df12e31989b7', '6d651acf-636a-501b-a761-d0b88b554da7', '87650a52-da4a-5a5b-a15b-f0f404e97d25', 15, 31, 'መጽሐፍ እንደ አለው ይሆን ዘንድ “የሚመካስ በእግዚአብሔር ይመካ።”'),
  ('9a1c63e1-341a-5a71-ae5f-9550204d89a9', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '46837697-3d6a-5ce1-a2a9-3ca8ecf9e3e2', 1, 1, 'ወንድሞቻችን ሆይ፥ እኔም ወደ እናንተ በመጣሁ ጊዜ በማባበልና ነገርን በማራቀቅ የእግዚአብሔርን ትምህርት ላስተምራችሁ የመጣሁ አይደለም።'),
  ('ea63e0d9-e781-57d2-aabc-c167ee8f1e1e', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '46837697-3d6a-5ce1-a2a9-3ca8ecf9e3e2', 2, 2, 'ከተሰቀለው ከኢየሱስ ክርስቶስ በቀር በእናንተ ዘንድ ሌላ ነገር እሰማለሁ ብዬ አልጠረጠርሁም ነበር።'),
  ('bfd4e09e-d680-54de-ab01-747ff47b7cba', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '46837697-3d6a-5ce1-a2a9-3ca8ecf9e3e2', 3, 3, 'እኔም በድካምና በፍርሀት፥ በብዙ መንቀጥቀጥም መጣሁ።'),
  ('4d168d14-d41f-5050-aa29-d2a81c42593a', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '46837697-3d6a-5ce1-a2a9-3ca8ecf9e3e2', 4, 4, 'ቃሌም፥ ትምህርቴም መንፈስንና ኀይልን በመግለጥ ነበር እንጂ በሚያባብል በጥበብ ቃል አልነበረም።'),
  ('443ffca5-473c-5cb8-a336-a5e73bfe6d51', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '46837697-3d6a-5ce1-a2a9-3ca8ecf9e3e2', 5, 5, 'ማመናችሁ በእግዚአብሔር ኀይል እንጂ በሰው ጥበብ እንዳይሆን።'),
  ('817e1c61-fa8f-59ec-a8e3-0e88dc32d00e', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 1, 6, 'ለዐዋቆች ጥበብን እንነግራቸዋለን፤ ነገር ግን የዚህን ዓለም ጥበብ ወይም ያልፉ ዘንድ ያላቸውን የዚህን ዓለም ሹሞች ጥበብ አይደለም።'),
  ('291bf053-5d96-5dbc-a564-ac4b35b82133', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 2, 7, 'ነገር ግን እግዚአብሔር አስቀድሞ ከዘመናት በፊት ለክብራችን የወሰነውን ተሰውሮም የነበረውን የእግዚአብሔር ጥበብ በምሥጢር እንናገራለን።'),
  ('cfc2701c-78f0-54f1-a272-228fcf832c29', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 3, 8, 'የዚህ ዓለም ሹሞችም አላወቁትም፤ ይህንስ ቢያውቁ ኑሮ የክብር ባለቤትን ባልሰቀሉትም ነበር።'),
  ('333432ee-16b5-50de-aa5c-e7ce982e1fed', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 4, 9, 'ነገር ግን መጽሐፍ፥ “ዐይን ያላየው፥ ጆሮም ያልሰማው፥ በሰውም ልቡና ያልታሰበ እግዚአብሔር ለሚወዱት ያዘጋጀው ነው።” ብሎ የለምን?'),
  ('d7ce0b6d-58f4-5d73-a717-603036c579bb', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 5, 10, 'ለእኛም እግዚአብሔር በመንፈሱ ገለጠልን፤ መንፈስ ቅዱስ የእግዚአብሔርን ጥልቅ ምሥጢሩን ያውቃልና።'),
  ('657e4253-db3a-56b1-a9cc-2f3b2bd42393', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 6, 11, 'በሰው ልቡና ያለውን የሚያውቅ ሰው ማን ነው? በእርሱ ያለችው ነፍሱ ናት እንጂ፤ እንዲሁም ከእግዚአብሔር መንፈስ በቀር የእግዚአብሔርን አሳብ የሚያውቅ የለም።'),
  ('929b6504-02ec-5d3c-a5f4-5c9f833d788f', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 7, 12, 'እኛ የዚህን ዓለም መንፈስ የተቀበልን አይደለም፤ ነገር ግን እግዚአብሔር የሰጠንን ጸጋ እናውቅ ዘንድ ከእግዚአብሔር የሚሆነውን መንፈስ ተቀበልን።'),
  ('034da705-92d7-5aeb-af9d-8dbc1cc3a13c', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 8, 13, 'ይህም ትምህርታችን ከሰው የተገኘ ትምህርት አይደለም፤ የአነጋገር ጥበብም አይደለም፤ መንፈስ ቅዱስ የገለጸው ትምህርት ነው እንጂ፤ መንፈሳዊ ጥበብም ከመንፈስ ቅዱስ የሚሆነውን መርምረው ለሚያውቁ ለመንፈሳውያን ነው።'),
  ('18ac9652-e9f5-594b-a97a-38a908f30212', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 9, 14, 'ለሥጋዊ ሰው ግን የእግዚአብሔር መንፈስ ነገር ሞኝነት ይመስለዋልና፥ አይቀበለውም፤ በመንፈስም የሚመረመር ስለሆነ ሊያውቅ አይችልም።'),
  ('2b435a27-54b9-5e9c-a593-635232866910', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 10, 15, 'መንፈስ ቅዱስ ያደረበት ሰው ግን ሁሉን ይመረምራል፤ እርሱን ግን የሚመረምረው የለም።'),
  ('56360531-83d6-578c-a5b3-6192add7fbd9', '7e85db38-d71d-563e-a7ca-c73e9dcb9a9d', '2734fca2-088d-5c0b-a664-b9ecbf0d0c19', 11, 16, 'የእግዚአብሔርን አሳብ ማን ያውቃል? መካሩስ ማን ነው? እኛ ግን ክርስቶስ የሚገልጠው ዕውቀት አለን።'),
  ('fac84d2e-f74f-5a8c-a9dd-d4368d8fdc62', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 1, 1, 'ወድሞች ሆይ፥ እኔስ የሥጋና የደም እንደ መሆናችሁ፥ ክርስቶስንም በማመን ሕፃናት እንደ መሆናችሁ እንጂ እንደ መንፈሳውያን ላስተምራችሁ አልቻልሁም።'),
  ('c2f0c787-b3e9-55ee-aa68-4ac6e4770ced', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 2, 2, 'ወተትን ጋትኋችሁ፤ ጽኑ መብልም ያበላኋችሁ አይደለም፤ ገና አልጠነከራችሁምና፤'),
  ('31c4267c-824b-5bee-aa6c-f607328aed80', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 3, 3, 'በሥጋዊ ሕግም ትኖራላችሁና እርስ በርሳችሁ የምትቃኑና የምትከራከሩ ከሆነ ግን ሥጋውያን መሆናችሁ አይደለምን? እንደ ሰው ልማድስ የምትኖሩ መሆናችሁ አይደለምን?'),
  ('eadf34cf-cf30-5f2b-a756-301779609da0', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 4, 4, 'ከመካከላችሁ፥ “እኔ የጳውሎስ ነኝ” የሚል አለና፤ ሌላውም፥ “እኔ የአጵሎስ ነኝ” ቢል እናንተ ሥጋውያን መሆናችሁ አይደለምን?'),
  ('c86c703d-a3a2-5b8f-a6cf-c09e0aafb6c2', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 5, 5, 'እንግዲህ ጳውሎስ ምንድን ነው? አጵሎስስ ምንድን ነው? እነርሱስ በቃላቸው የአመናችሁ አገልጋዮች ናቸው፤ ለእያንዳንዱም እግዚአብሔር እንደ ሰጠው ነው።'),
  ('b1de0fce-ab76-54fd-a80d-f76ec8faeeaf', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 6, 6, 'እኔ ተከልሁ፤ አጵሎስም አጠጣ፤ ነገር ግን እግዚአብሔር አሳደገ።'),
  ('9060c276-e472-5749-afe4-3b653c5dafe7', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 7, 7, 'አሁንም የሚተክልም ቢሆን፥ የሚያጠጣም ቢሆን የሚጠቅመው ነገር የለም፤ የሚያሳድግ እግዚአብሔር ነው እንጂ።'),
  ('e9173167-57b6-5e81-a4c6-b4f984270f30', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 8, 8, 'የሚተክልም፥ የሚያጠጣም አንድ ናቸው፤ ሁሉም እንደ ድካማቸው ዋጋቸውን ይቀበላሉ።'),
  ('206d18f0-9747-56cd-a05d-a051e7f78531', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 9, 9, 'በእግዚአብሔር ሥራ እንተባበራለንና፤ የእግዚአብሔርም አገልጋዮች ነንና፤ እናንተም የእግዚአብሔር ሕንፃ ናችሁ።'),
  ('54a0277c-fe55-5f96-a12b-af01845a8d85', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 10, 10, 'እግዚአብሔር እንደ ሰጠኝ ጸጋ መጠን እንደ ብልህ የጠራቢዎች አለቃ ሆኜ እኔ መሠረት ጣልሁ፤ ሌላውም በእርሱ ላይ ያንጻል፤ እያንዳንዱ ግን በእርሱ ላይ እንዴት እንደሚያንጽ ይጠንቀቅ።'),
  ('46454afa-3672-57e3-a9ab-5f3dae605864', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 11, 11, 'ነገር ግን ከተመሠረተው በቀር ሌላ መሠረት ሊመሠርት የሚችል የለም፤ መሠረቱም ኢየሱስ ክርስቶስ ነው።'),
  ('dd11b366-8d9c-5d22-a7a0-439999b5055e', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 12, 12, 'በዚህ መሠረት ላይ በወርቅና በብር፥ በከበረ ድንጋይና በእንጨት፥ በሣርና በአገዳ የሚያንጽ ቢኖርም፥'),
  ('d3f461d0-64da-5554-a462-2368143fb110', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 13, 13, 'የእያንዳንዱ ሥራ ይገለጻል፤ እሳትም በፈተነው ጊዜ ቀኑ ይገልጠዋል፤ የእያንዳንዱንም ሥራ እሳት ይፈትነዋል።'),
  ('5ebaf829-dc9c-5440-acd2-6a116d7dae95', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 14, 14, 'ሥራው ጸንቶ የተገኘለት ሰው ዋጋውን የሚቀበል እርሱ ነው።'),
  ('ea989154-2c50-5e59-a62b-4263bd0a61ba', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 15, 15, 'ሥራው የተቃጠለበት ግን ዋጋውን ያጣል፤ እርሱም ከእሳት እንደሚድን ሰው ይድናል።'),
  ('60ec55d3-8548-58c4-a00e-09fe0d3937d3', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 16, 16, 'እናንተ የእግዚአብሔር ቤተ መቅደስ እንደ ሆናችሁ፥ የእግዚአብሔር መንፈስም በእናንተ ላይ አድሮ እንደሚኖር አታውቁምን?'),
  ('b8d751f9-2947-57c9-aee7-49c83e943eef', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 17, 17, 'የእግዚአብሔርን ቤተ መቅደስ የሚያፈርሰውን ግን እርሱን ደግሞ እግዚአብሔር ያፈርሰዋል፤ የእግዚአብሔር ቤተ መቅደስ ነውና፤ የእግዚአብሔር ቤተ መቅደስም እናንተ ራሳችሁ ናችሁ፤ እንግዲያስ የእግዚአብሔርን ቤተ መቅደስ አታርክሱ።'),
  ('e3ffdcf4-daa7-5687-a3aa-1ba8ac9028c9', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 18, 18, 'ራሳችሁን አታስቱ፤ ከመካከላችሁ በዚህ ዓለም ጥበበኛ እንደ ሆነ የሚያስብ ሰው ጥበበኛ ይሆን ዘንድ ራሱን ዐላዋቂ ያድርግ።'),
  ('eedb4843-3823-5177-aa64-80a3392852a1', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 19, 19, 'የዚህ ዓለም ጥበብ በእግዚአብሔር ዘንድ ድንቍርና ነውና፤ መጽሐፍ እንዲህ ብሎአልና፥ “ጠቢባንን የሚገታቸው ተንኰላቸው ነው።”'),
  ('0e3fb08b-fbc5-5ac9-a3b7-26bf2aa5a48e', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 20, 20, 'ዳግመኛ “የጥበበኞች አሳብ ከንቱ እንደ ሆነ እግዚአብሔር ያውቃል” ብሎአል።'),
  ('a3b8f8f4-7d0a-53d0-a9c0-94925ee3d08a', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 21, 21, 'ስለዚህም እንግዲህ አንዱ ስንኳ በሰው አይመካ፤ ሁሉ የእናንተ ነውና።'),
  ('f715203c-2e9d-5fba-ac8f-5a23f2106e53', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 22, 22, 'ጳውሎስም ቢሆን፥ አጵሎስም ቢሆን፥ ጴጥሮስም ቢሆን፥ ዓለምም ቢሆን፥ ሕይወትም ቢሆን፥ ሞትም ቢሆን፥ ያለውም ቢሆን፥ የሚመጣውም ቢሆን ሁሉ የእናንተ ነው።'),
  ('2534e0ce-6f8a-56fe-a82c-1e8639628168', '28faae8f-605d-55fa-a7c4-3cbd000e6fae', 'a39477c6-0cb2-511d-a54a-c3bfde9f0e66', 23, 23, 'እናንተ ግን የክርስቶስ ናችሁ፤ ክርስቶስም የእግዚአብሔር ነው።'),
  ('799b6236-c6b4-5bfe-adb3-ac299dd47606', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 1, 1, 'እኛ የክርስቶስ አገልጋዮችና የእግዚአብሔር የምሥጢሩ መጋቢዎች እንደ ሆን ሰው ስለ እኛ እንዲህ ያስብ።'),
  ('206c203e-1b1b-5f90-a41a-78d43e17ddab', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 2, 2, 'እንግዲህ በዚህ ከመጋቢዎች እያንዳንዱ ቸርና ታማኝ ሆኖ እንዲገኝ ይፈለጋል።'),
  ('48afe23a-990c-54b9-a58a-644b2c71a02c', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 3, 3, 'ለእኔስ በእናንተ ዘንድ መመስገን ውርደት ነው፤ ጻድቅ ብትሉኝ፥ በመዋቲ ሰው ዘንድም ቸር ብላችሁ ብታከብሩኝ እኔ ለራሴ አልፈርድም።'),
  ('46f15ba9-4097-59c0-a5e2-50ea21464200', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 4, 4, 'የሚያጠራጥረኝና ትዝ የሚለኝ ነገር የለም፤ በዚህም ራሴን አላመጻድቅም፤ እግዚአብሔር ይመረምረኛልና።'),
  ('fb37ece2-2d2d-5d1a-aa72-8d06c514b5e8', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 5, 5, 'ጊዜው ሳይደርስ ዛሬ ለምን ትመረምራላቸሁ? በጨለማ ውስጥ የተሰወረውንም የሚያበራ፥ የልብን አሳብም የሚገልጥ ጌታችን ይመጣል፤ ያንጊዜ ሁሉም ዋጋውን ከእግዚአብሔር ዘንድ ይቀበላል።'),
  ('bc9933d5-1b44-5186-a2bf-23c7399ef6fd', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 6, 6, 'ወንድሞቻችን ሆይ! እኔም፥ አጵሎስም ብንሆን መከራ የተቀበልነው ስለ እናንተ ነው፤ እናንተ እንድትማሩ፥ ከመጻሕፍት ቃልም ወጥታችሁ በወንድሞቻችሁ ላይ እንዳትታበዩ ነው።'),
  ('61e1abfc-65d5-50ba-aaa6-5fff4407c431', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 7, 7, 'ማን ይመረምርሃል? የምትታበይስ በምንድን ነው? ከሌላ ያላገኘኸው አለህን? ያለህንም ከሌላ ካገኘህ እንዳላገኘ ለምን ትኮራለህ?'),
  ('df8eff1e-9fb7-55e7-a3e2-01f9239161b5', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 8, 8, 'እናንተ አሁን ጠግባችኋል፤ በልጽጋችኋልም፤ ያለእኛም ፈጽማችሁ ነግሣችኋል፤ እኛም ከእናንተ ጋር እንድንነግሥ ብትነግሡ አግባብ በሆነ ነበር።'),
  ('3c08cb4d-9297-5d51-aa47-26e75ed7f54f', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 9, 9, 'እኔስ ለሞት ዝግጁዎች እንደ መሆናችን እኛን ሐዋርያቱን እግዚአብሔር የኋለኞች ያደረገን ይመስለኛል፤ እኛ ለሰዎችም፥ ለአለቆችም፥ ለዓለምም መዘባበቻ ሆነናልና።'),
  ('84d45178-24aa-58cc-aabe-23213a25334c', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 10, 10, 'እኛስ ስለ ክርስቶስ ብለን አላዋቂዎች ነን፤ እናንተ ግን በክርስቶስ ጠቢባን ናችሁ፤ እኛ ደካሞች ነን፤ እናንተ ግን ብርቱዎች ናችሁ፤ እናንተ ክቡራን ናችሁ፤ እኛ ግን የተዋረድን ነን።'),
  ('cff321c0-3258-5c3d-abe0-d2af87db2b4a', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 11, 11, 'እኛ እስከዚች ቀን ድረስ እንራባለን፤ እንጠማለን፤ እንራቈታለን፤ እንሰደዳለን፤ ማረፊያም የለንም፤ እንደበደባለንም።'),
  ('374120de-f6fd-5acf-aee4-f68a3fdf8946', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 12, 12, 'በእጃችን ሥራ እያገለገልን እንደክማለን፤ ይረግሙናል፤ እኛ ግን እንመርቃቸዋለን፤ ያሳድዱናል፤ እኛ ግን እንጸልይላቸዋለን፤ እንታገሣቸዋለንም።'),
  ('0c8372b3-310d-5b49-a4a5-085ca4d335a1', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 13, 13, 'ይሰድቡናል፥ እንማልዳቸዋለን፤ በዓለም እንደ ጊጤ ሆን፤ በሁሉም ዘንድ የተናቅን ሆን።'),
  ('2304ba99-7fb8-596b-aa1a-b10178c7c477', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 14, 14, 'ይህንም የጻፍሁላችሁ ላሳፍራችሁ አይደለም፤ ልጆችና ወዳጆች እንደ መሆናችሁ ልመክራችሁና ላስተምራችሁ ነው እንጂ፤ እኔ ለሁላችሁ ቤዛችሁ ነኝ፤ እናንተ ግን አላፈራችሁኝም።'),
  ('c55f56b6-a3fe-54e5-abe7-e9c2af29954e', '150ec840-806b-585a-a731-547c4297c57b', '515025c4-639d-5536-a202-3838470e3457', 15, 15, 'በክርስቶስ ብዙ መምህራን ቢኖሩአችሁም አባቶቻችሁ ብዙዎች አይደሉም፤ እኔ በኢየሱስ ክርስቶስ በትምህርት ወልጄአችኋለሁና።'),
  ('cc7eb790-77f9-5bf9-abf2-448d846a3fe4', '150ec840-806b-585a-a731-547c4297c57b', '9e838ca3-c7ef-5e14-a5a8-1332e33392cb', 1, 16, 'ወንድሞቻችን ሆይ! እኔን እንድትመስሉ እማልዳችኋለሁ፤'),
  ('2903ca4c-c2f2-522d-aa96-9bb7d0f480ee', '150ec840-806b-585a-a731-547c4297c57b', '9e838ca3-c7ef-5e14-a5a8-1332e33392cb', 2, 17, 'ስለዚህም በየስፍራው በአብያተ ክርስቲያናት ሁሉ እንዳስተማርሁ በክርስቶስ ኢየሱስ የሄድሁበትን መንገድ ይገልጥላችሁ ዘንድ በእግዚአብሔር የታመነና ልጄ ወዳጄ የሆነ ጢሞቴዎስን ልኬላችኋለሁ።'),
  ('f124561a-1459-5939-a69d-7ae2d9fed859', '150ec840-806b-585a-a731-547c4297c57b', '9e838ca3-c7ef-5e14-a5a8-1332e33392cb', 3, 18, 'እነሆ፥ ወደ እናንተ ስላልመጣሁ ከእናንተ ወገን የታበዩ ሰዎች አሉ።'),
  ('0fd81f39-1679-5350-aa57-8bb07a5f9b3a', '150ec840-806b-585a-a731-547c4297c57b', '9e838ca3-c7ef-5e14-a5a8-1332e33392cb', 4, 19, 'እንኪያስ እግዚአብሔር ቢፈቅድ ፈጥኜ እመጣለሁ፤ ነገር ግን የትዕቢተኞችን ነገር አልሻም፤ ኀይላቸውን እሻለሁ እንጂ።'),
  ('d81dc7ee-2968-56c9-af3d-a11d670bcb44', '150ec840-806b-585a-a731-547c4297c57b', '9e838ca3-c7ef-5e14-a5a8-1332e33392cb', 5, 20, 'የእግዚአብሔር መንግሥት በኀይል እንጂ በቃል አይደለምና።'),
  ('4c518b1a-34b8-5dd1-aea3-28cc80bf94d3', '150ec840-806b-585a-a731-547c4297c57b', '9e838ca3-c7ef-5e14-a5a8-1332e33392cb', 6, 21, 'እንዴት ሆኜ ወደ እናንተ ልመጣ ትወዳላችሁ? በበትር ነውን? ወይስ በፍቅርና በቅንነት መንፈስ?'),
  ('bba546a1-15bd-5235-a126-41c33f2ff622', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 1, 1, 'በእናንተ ላይ ዝሙት ይሰማል፤ እንደዚህ ያለው ዝሙትም አረማውያን እንኳ የማያደርጉት ነው፤ ያባቱን ሚስት ያገባ አለና።'),
  ('ed50ef4a-cad6-536b-a746-cbb24f6384ff', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 2, 2, 'እናንተም ከዚህ ጋር ትዕቢተኞች ናችሁ፤ ይልቁንም ይህን ያደረገው ከእናንተ ይለይ ዘንድ ለምን አላዘናችሁበትም?'),
  ('1f0424ad-9d6e-5636-abd1-fea61d73ef78', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 3, 3, 'እኔ በሥጋዬ ከእናንተ ጋር ባልኖር፥ በመንፈሴ ከእናንተ ጋር አለሁ፤ እነሆ፥ ከእናንተ ጋር እንደ አለሁ ሆኜ፥ ይህን ሥራ የሠራውን እፈርድበታለሁ።'),
  ('98ab8a68-fb53-5008-a9eb-07d4cc54824c', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 4, 4, 'በጌታችን በኢየሱስ ክርስቶስ ስም ተሰብስባችሁ፥ በእኔ ሥልጣን፥ በጌታችን በኢየሱስም ኀይል፥'),
  ('277e5f95-724e-5873-a229-4c871afb9a57', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 5, 5, 'ሥጋውን ጎድቶ ጌታችን ኢየሱስ ክርስቶስ በሚመጣበት ቀን ነፍሱ ትድን ዘንድ እንዲህ ያለውን ሰው ለሰይጣን አሳልፋችሁ ስጡት።'),
  ('64c9d1fb-e8ac-51d3-a898-db39860d84f6', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 6, 6, 'እንግዲያስ መታበያችሁ መልካም አይደለም፤ ጥቂቱ እርሾ ብዙውን ሊጥ እንደሚያመጥ አታውቁምን?'),
  ('9ce1faa4-d8fa-5cb2-abe3-32a2d6acf384', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 7, 7, 'እንግዲህ ለአዲስ ቡሆ ትሆኑ ዘንድ አሮጌውን እርሾ ከእናንተ አርቁ፤ ገና ቂጣ ናችሁና፤ ፋሲካችን ክርስቶስ ተሠውቶ የለምን?'),
  ('30f3721a-77dc-5905-a535-775465eefac8', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 8, 8, 'አሁንም በዓላችሁን አድርጉ፤ ነገር ግን እውነትና ንጽሕና ባለው እርሾ ነው እንጂ በአሮጌው እርሾ፥ በኀጢአትና በክፋት እርሾም አይደለም።'),
  ('7209a932-0373-5b99-add2-a438454bfaa6', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 9, 9, 'ከዘማውያን ጋር አንድ እንዳትሆኑ በዚህ መልእክት ጻፍሁላችሁ።'),
  ('2b56a03e-8896-5c77-a0c8-45bcc1e342ca', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 10, 10, 'የዚህ ዓለም ዝሙት ብቻ አይደለም፤ ቀማኞችና ዘራፊዎች፥ ጣዖትን የሚያመልኩ ደግሞ አሉ፤ ያለዚያስ ከዚህ ዓለም ልትለዩ ይገባል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('63231489-cd0c-59f4-a53e-563542aab862', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 11, 11, 'አሁንም ከወንድሞች መካከል ዘማዊ፥ ወይም ገንዘብን የሚመኝ፥ ወይም ጣዖትን የሚያመልክ፥ ወይም ዐመፀኛ፥ ወይም ተራጋሚ፥ ወይም ሰካራም፥ ወይም የሚቀማ ቢኖር እንደዚህ ካለ ሰው ጋር አንድ እንዳትሆኑ ጻፍሁላችሁ፥ እንደዚህ ካለው ሰው ጋር መብልም እንኳ አትብሉ፤'),
  ('2bd9b75a-4525-5613-a60b-6e7e6973bc6b', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 12, 12, 'ምን አግዶኝ፥ በውጭ ባለው ላይ እፈርድበታለሁ? እናንተስ በውስጥ ከእናንተ ጋር የሚኖሩትን ፈርዳችሁ ቅጡአቸው።'),
  ('57931a5f-4d7d-59e1-ad78-ba46d631dfee', '5687485d-68f7-5d78-a3cc-a279998abf9f', '513c511b-d207-5b4a-a7cc-e702cd279d57', 13, 13, 'በውጭ ያሉትን ግን እግዚአብሔር ይፈርድባቸዋል፤ ይቀጣቸዋልም፤ ክፉውን ከእናንተ አርቁ።'),
  ('8838d2db-9922-5d3b-a323-318ba0687aa7', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 1, 1, 'እንግዲህ በሚነቅፉ ሰዎች ዘንድ ልትከራከሩ አትድፈሩ፤ ከጓደኛው ጋር በዐመፀኞች ዘንድ ሊከራከር የሚችል አለን? በደጋጎች ዘንድ አይደለምን? ከባልንጀራው ጋር ክርክር ያለው ቢኖርም በቅዱሳን ዘንድ ይከራከር፤ በሚነቅፉና በዐመፀኞች ዘንድ ግን አይደለም።'),
  ('f80da198-39ac-5094-aa6b-1e54c0532682', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 2, 2, 'ቅዱሳን ሰውን ሁሉ እንደሚዳኙ አታውቁምን? እናንተ ሰውን ሁሉ የምትዳኙ ከሆናችሁ ይህን ትንሹን ነገር ልትዳኙ አይገባችሁምን?'),
  ('f6457177-630d-5a9e-a07f-b61591157084', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 3, 3, 'የዚህንስ ዓለም ዳኝነት ተዉትና በመላእክት ስንኳ እንድንፈርድ አታውቁምን?'),
  ('84a0450a-5df5-5f39-a2fc-3f2834b79a0f', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 4, 4, 'ነገር ግን የዚህ ዓለም ክርክር ያላቸው ሰዎች ቢኖሩ በቤተ ክርስቲያን የተሾሙ የበታች ወንድሞች ይስሙአቸው።'),
  ('3cacb517-7a34-5554-a16e-6681484fb52f', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 5, 5, 'ይህንም የምላችሁ ስዘልፋችሁ ነው፤ እንግዲህ ከመካከላቸሁ ወንድማማቾችን ከወንድሞቻቸው ጋር ማስታረቅ የሚችል ሽማግሌ የለምን?'),
  ('75b75a43-7115-5ce1-a441-cb93e50466a4', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 6, 6, 'ነገር ግን ወንድም ከወንድሙ ጋር ይካሰሳል፤ ይህም በማያምኑ ፊት ይደረጋል።'),
  ('2dddf967-7621-5284-ab50-c0fd165a7df4', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 7, 7, 'እንግዲህ ፀብና ክርክር ካላችሁ፥ ከመጀመሪያው ጀምሮ ውርደት እንደሚሆንባችሁ ዕወቁ፤ እንግዲያማ እንዴት አትነጠቁም? እንዴትስ አትገፉም?'),
  ('bad3ab24-11e2-5068-acc4-63c399b98bf5', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '1a598328-c294-5518-a546-6d9dbdd9ade5', 8, 8, 'አሁንም ቢሆን፥ እናንተ ዐመፀኞችና ቀማኞች ናችሁ፤ እንደዚህም ወንድሞቻችሁን ትበድላላችሁ።'),
  ('e6daef38-4c9b-5a78-a40a-81f84fa00bd6', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', 'd3e19ef4-372f-5191-a25e-8329000bfc25', 1, 9, 'ዐመፀኞች የእግዚአብሔርን መንግሥት እንደማይወርሱ አታውቁምን? አያስቱአችሁ፤ ሴሰኞች፥ ወይም ጣዖትን የሚያመልኩ፥ ወይም አመንዝራዎች፥ ወይም ቀላጮች፥ ወይም በወንድ ላይ ዝሙትን የሚሠሩ፥ የሚሠሩባቸውም ቢሆኑ፤'),
  ('7629278f-5a97-5593-a037-c4e43fbd1122', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', 'd3e19ef4-372f-5191-a25e-8329000bfc25', 2, 10, 'ሌቦች፥ ወይም ቀማኞች፥ ወይም ሰካሮች፥ ወይም ተሳዳቢዎች፥ ወይም ነጣቂዎች፥ የእግዚአብሔርን መንግሥት አይወርሱአትም።'),
  ('a44d5cab-10d1-5d29-a953-20fd13bf3148', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', 'd3e19ef4-372f-5191-a25e-8329000bfc25', 3, 11, 'እንግዲህ እናንተ እንዲህ ስትሆኑ እነማን ናችሁ? ነገር ግን በጌታችን በኢየሱስ ክርስቶስ ስም በአምላካችንም መንፈስ ታጥባችኋል፤ ተቀድሳችኋል፤ ጸድቃችኋልም።'),
  ('1ea81f5d-9cf3-5b3a-aa41-c4157c983d66', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 1, 12, 'በሆነው ሁሉ ላይ ሥልጣን አለኝ፤ ግን ሁሉ የሚጠቅመኝ አይደለም፤ ሁሉም ይቻለኛል፤ ነገር ግን በእኔ ላይ እንዲሠለጥን የማደርገው ምንም የለም።'),
  ('7154529e-8f86-5bac-af2b-ff5798742969', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 2, 13, 'መብል ለሆድ ነው ፤ ሆድም ለመብል ነው፤ እግዚአብሔር ግን ሁለቱንም ይሽራቸዋል፤ ሥጋችሁም ለእግዚአብሔር ነው እንጂ ለዝሙት አይደለም፤ እግዚአብሔርም ለሥጋችሁ ነው።'),
  ('6cbcd639-28b6-59da-a9b8-1f9c9359e9b0', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 3, 14, 'ጌታችን ኢየሱስ ክርስቶስን ከሙታን ያስነሣው እግዚአብሔር እኛንም በከሃሊነቱ ያስነሣናል።'),
  ('76623bf4-3d85-5348-a68d-b52420d673d9', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 4, 15, 'ሥጋችሁ የክርስቶስ አካል እንደ ሆነ አታውቁምን? እንግዲህ የክርስቶስን አካል ወስዳችሁ የአመንዝራ አካል ታደርጉታላችሁን? አይገባም።'),
  ('cafbd027-3790-5475-af7a-201f990a3614', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 5, 16, 'ከአመንዝራ ጋር የተገናኘ ከእርስዋ ጋር አንድ አካል እንዲሆን አታውቁምን? መጽሐፍ፥ “ሁለቱ አንድ አካል ይሆናሉ” ብሎአልና።'),
  ('8aee4ba3-4ac6-50df-ab58-f441ff673f3a', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 6, 17, 'ከእግዚአብሔር ጋር የተዋሐደ ግን ከእርሱ ጋር አንድ መንፈስ ይሆናል።'),
  ('9eb39410-2506-57cc-a1cf-4f7b9266cad9', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 7, 18, 'ከዝሙት ራቁ፤ ኀጢአት የሚሠራ ሰው ሁሉ ከሥጋው ውጭ ይሠራልና፤ ዝሙትን የሚሠራ ግን ራሱ በሥጋው ላይ ኀጢአትን ይሠራል።'),
  ('8aaa1913-b902-58b2-aa4c-04427d2e093e', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 8, 19, 'ሥጋችሁ ከእግዚአብሔር ለተቀበላችሁት በእናንተ አድሮ ላለ ለመንፈስ ቅዱስ ቤተ መቅደስ እንደ ሆነ አታውቁምን? ለራሳችሁም አይደላችሁም።'),
  ('873fc7df-717c-5014-a9af-12aa6e7dcade', 'eb6f8eb3-cf02-5183-ab5b-e947f8f287f5', '217ce3dc-bee6-58ff-a12f-244a88b81552', 9, 20, 'በዋጋ ተገዝታችኋልና፤ ስለዚህም እግዚአብሔርን በሥጋችሁ አክብሩት።'),
  ('4a94b26f-02a8-563f-aa08-3ad92f899ebf', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 1, 1, 'ስለ ጻፋችሁልኝስ ለሰው ወደ ሴት አለመቅረብ ይሻለዋል።'),
  ('d5519baa-9ba8-5bcd-aafa-912892fb8aa1', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 2, 2, 'ነገር ግን እንዳትሴስኑ ሰው ሁሉ በሚስቱ ይወሰን፤ ሴትም ሁላ በባልዋ ትወሰን።'),
  ('46af9d13-6417-52a1-aa3a-2aba051083ee', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 3, 3, 'ለሚስትም ባልዋ የሚገባትን ያድርግላት፤ እንዲሁ ሚስትም ለባልዋ የሚገባውን ታድርግለት።'),
  ('ad001158-d5fb-5d70-a073-120d79a5b2b2', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 4, 4, 'ሚስት በራስዋ አካል ሥልጣን የላትም፤ ሥልጣን ለባልዋ ነው እንጂ፤ እንዲሁም ባል በራሱ አካል ሥልጣን የለውም፤ ሥልጣን ለሚስቱ ነው እንጂ።'),
  ('050b131c-2797-5a6e-a75c-aeed452a9f05', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 5, 5, 'ለጸሎት እንድትተጉ ከምትስማሙበት ጊዜ ብቻ በቀር፥ ባልና ሚስት አትለያዩ፤ ዳግመኛ ሰይጣን ድል እንዳያደርጋችሁ በአንድነት ኑሩ፤ ሰውነታችሁ ደካማ ነውና ።'),
  ('f9db332e-f0ea-54a6-a1cd-64143712cdd5', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 6, 6, 'ይህንም የምላችሁ እንደ ፈቃድ ነው እንጂ፥ ላዝዛችሁ አይደለም።'),
  ('00a3b613-58de-5eef-ac3c-99ac17cd18c1', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 7, 7, 'ሰው ሁሉ እንደ እኔ ሊሆን እወዳለሁና፤ ነገር ግን ሰው ሁሉ እግዚአብሔር እንደ አደለው ጸጋ ይኑር፤ ግብሩ እንዲህ የሆነ አለና፤ ግብሩ ሌላ የሆነም አለና።'),
  ('50565f1f-c290-554e-a54e-01d3fc3e763a', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 8, 8, 'ነገር ግን ያላገቡትንና አግብተው የፈቱትን እንደ እኔ ሆነው ቢኖሩ ይሻላቸዋል እላለሁ።'),
  ('e7ddfba9-214e-5d1f-a98f-50c3a82de75f', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 9, 9, 'መታገሥ ባይችሉ ግን ያግቡ፤ በፍትወት ከመቃጠል ማግባት ይሻላልና።'),
  ('cf91492a-a34b-5947-a725-6c50cd652c8e', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 10, 10, 'ያገቡትንም በእግዚአብሔር ትእዛዝ አዝዛቸዋለሁ፤ በራሴ ትእዛዝም አይደለም፤ ሚስትም ከባልዋ አትፋታ።'),
  ('0198c2a3-c348-5486-a63c-64922e985626', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 11, 11, 'ከተፋታችም ብቻዋን ትኑር፤ ያለዚያ ከባልዋ ጋር ትታረቅ፤ ባልም ሚስቱን አይፍታ።'),
  ('f9fc32e7-ccaa-58ef-ad78-b62f921ae07a', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 12, 12, 'ሌላውን ግን ከራሴ እናገራለሁ፤ ከጌታችንም አይደለም፤ ከወንድሞቻችን መካከል የማታምን፥ ባልዋንም የምታፈቅር ከእርሱም ጋር ለመኖር የምትወድ ሚስት ያለችው ሰው ቢኖር ሚስቱን አይፍታ።'),
  ('2191b3f1-2ba0-5fa3-a3ce-dc3194dd80fc', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 13, 13, 'ሴቲቱም የማያምንና ሚስቱንም የሚያፈቅር ከእርስዋም ጋር ሊኖር የሚወድ ባል ቢኖራት ባልዋን አትፍታ።'),
  ('eb186c59-9666-5dc4-a736-5c4ddcbfce8c', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 14, 14, 'የማያምን ባል በሚስቱ ይቀደሳልና፤ የማታምን ሚስትም በባልዋ ትቀደሳለችና፤ ያለዚያማ ልጆቻቸው ርኩሳን ይሆናሉ፤ አሁን ግን ቅዱሳን ናቸው።'),
  ('413965f8-f02c-51e5-a217-cf5180470391', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 15, 15, 'የማያምን ግን ቢፈታ ይፍታ፤ ወንድምና እኅት እግዚአብሔር ለሰላም ስለ ጠራቸው እንደዚህ ላለ ግብር አይገዙምና።'),
  ('03d1aa8b-9864-5ded-a079-0a56e41b7229', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 16, 16, 'ሚስትም ባልዋን ታድነው እንደ ሆነ አታውቅምና፤ ባልም ሚስቱን ያድናት እንደ ሆነ አያውቅምና።'),
  ('eadafd05-834d-5d36-aa78-69ee84792ae3', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 17, 17, 'ነገር ግን ሁሉ እግዚአብሔር እንደ አደለው፥ ሁሉም እግዚአብሔር እንደ ጠራው እንዲሁ ይኑር፤ ለአብያተ ክርስቲያናትም ሁሉ እንዲህ ሥርዐት እንሠራለን።'),
  ('be8c9976-f2f1-5e23-a4e5-6d5ffc385aa1', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 18, 18, 'ተገዝሮ ሳለ የተጠራ ቢኖር አለመገዘርን አይመኝ፤ ያልተገዘረም ቢጠራ ከዚያ ወዲያ አይገዘር።'),
  ('15429946-9fa0-5033-a96d-de9bd53623f2', '7545778b-3777-574e-a978-f078d03acdc8', '2b47264a-5b5a-516f-a7ab-98fb8e6e5eb8', 19, 19, 'የእግዚአብሔርን ትእዛዝ መጠበቅ ነው እንጂ መገዘርም አይጠቅምም፤ አለመገዘርም አይጎዳም።'),
  ('b8889944-f7ba-5bb6-a5ea-7471d5c30e21', '7545778b-3777-574e-a978-f078d03acdc8', '3a8baf5f-1e6f-534e-acaa-23bf569f2c72', 1, 20, 'ሁሉ እንደ ተጠራ እንዲሁ ይኑር።'),
  ('6e72823b-d1f7-50d5-a017-5240146af26d', '7545778b-3777-574e-a978-f078d03acdc8', '3a8baf5f-1e6f-534e-acaa-23bf569f2c72', 2, 21, 'አንተ ባርያ ሳለህ ብታምን አያሳዝንህ፤ የሚቻልህ ከሆነ ግን ነጻነትህን አግኝ።'),
  ('1d438bc8-d5a9-5d5d-a474-881b4869ba52', '7545778b-3777-574e-a978-f078d03acdc8', '3a8baf5f-1e6f-534e-acaa-23bf569f2c72', 3, 22, 'የተጠራ ባሪያ በእግዚአብሔር ዘንድ ነጻነት ያለው ነውና፤ እንዲሁ ነጻነት ያለውም ከተጠራ የክርስቶስ ባርያ ነው።'),
  ('3fb51945-04bf-53eb-aac7-2dd3bd65f738', '7545778b-3777-574e-a978-f078d03acdc8', '3a8baf5f-1e6f-534e-acaa-23bf569f2c72', 4, 23, 'በዋጋ ገዝቶአችኋልና የሰው ተገዦች አትሁኑ።'),
  ('7b43bdfd-2723-5584-a235-43f7d0c3a2ec', '7545778b-3777-574e-a978-f078d03acdc8', '3a8baf5f-1e6f-534e-acaa-23bf569f2c72', 5, 24, 'ወንድሞቻችን ሁላችሁም በተጠራችሁበት እንዲሁ በእግዚአብሔር ኑሩ።'),
  ('01bf32af-01fa-5b35-ae13-410c7b072800', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 1, 25, 'ስለ ደናግልም የምነግራችሁ የእግዚአብሔር ትእዛዝ አይደለም፤ ታማኝ እንድሆን እግዚአብሔር ይቅር ያለኝ እንደ መሆኔ ምክሬን እነግራችኋለሁ እንጂ።'),
  ('13e8e61b-2121-5bf0-ae33-f87e1c22f827', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 2, 26, 'ነገር ግን እንዲህ ይመስለኛል፤ በግድ ይህ ሊመረጥ ይሻላልና እንዲህ ሆኖ ቢኖር ለሰው ይሻለዋል።'),
  ('315a3d7d-6702-58a6-a6fb-3e87c6481a55', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 3, 27, 'ከሚስትህ ጋር ሳለህ ከእርስዋ መፋታትን አትሻ፤ ሚስት ከሌለህ ግን ሚስትን አትሻ።'),
  ('b1d1b83c-7281-58fd-ab14-588123ed090d', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 4, 28, 'ብታገባም ኀጢአት አይሆንብህም፤ ድንግሊቱም ባል ብታገባ ኀጢአት አይሆንባትም፤ ያገቡ ግን ለራሳቸው ድካምን ይሻሉ፤ እኔም ይህን የምላችሁ ስለማዝንላችሁ ነው።'),
  ('73230e13-3679-5218-a117-e6ab49f17868', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 5, 29, 'ነገር ግን ወንድሞቻችን እንዲህ ይቀናል፤ የዚህ ዓለም ኑሮ ሁሉ ሊያልፍ ቀርቦአልና፤ አሁንም ያገቡ እንዳላገቡ ይሆናሉ።'),
  ('a86bf9f7-a898-5b3f-a47c-3f7927b8fae7', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 6, 30, 'ያለቀሱ እንዳላለቀሱ ይሆናሉ፤ ደስ ያላቸውም ደስ እንዳላላቸው ይሆናሉ፤ የሸጡም እንዳልሸጡ ይሆናሉ፤ የገዙም እንዳልገዙ ይሆናሉ።'),
  ('3026ce54-2dbc-5006-a474-1d9d223cad25', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 7, 31, 'የበሉ እንዳልበሉ ይሆናሉ፤ የጠጡም እንዳልጠጡ ይሆናሉ፤ የዚህ ዓለም ተድላ ሁሉ ያልፋልና።'),
  ('d637632a-9e91-52fc-ab14-1e8874d3aad1', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 8, 32, 'እኔስ ያለ አሳብ ልትኖሩ እወዳለሁ፤ ያላገባ እግዚአብሔርን ደስ ሊያሰኘው የእግዚአብሔርን ነገር ያስባልና።'),
  ('86f1c6cf-cc98-5025-a822-af6a2c52c3ab', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 9, 33, 'ያገባ ግን ሚስቱን ደስ ሊያሰኝ የዚህን ዓለም ኑሮ ያስባል።'),
  ('bfdd7239-de02-512d-aad7-dcdbed5bf480', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 10, 34, 'እንዲህ ከሆነ ግን ተለያየ፤ አግብታ የፈታች ሴትም ያላገባች ድንግልም ብትሆን ነፍስዋም ሥጋዋም ይቀደስ ዘንድ እግዚአብሔርን ታስበዋለች፤ ያገባች ግን ባልዋን ደስ ልታሰኝ የዚህን ዓለም ኑሮ ታስባለች።'),
  ('d240b751-21ae-5407-a36f-a0e67780cb93', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 11, 35, 'ይህንም የምላችሁ እንዲጠቅማችሁ ነው፤ ላጠምዳችሁ ግን አይደለም፤ ኑሮአችሁ አንድ ወገን እንዲሆንና እግዚአብሔርን ያለመጠራጠር እንድታገለግሉት ነው እንጂ።'),
  ('9d5766be-2e48-5498-a62c-8b82fe8d65fd', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 12, 36, 'በሸመገለ ጊዜ ስለ ድንግልናው እንደሚያፍር የሚያስብ ሰው ቢኖር እንዲህ ሊሆን ይገባል፤ የወደደውን ያድርግ፤ ቢያገባም ኀጢአት የለበትም።'),
  ('e4cfc4b3-de20-5451-a46e-f3624afff9ed', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 13, 37, 'በልቡ የቈረጠና ያላወላወለ ግን የወደደውን ሊያደርግ ይችላል፤ ግድም አይበሉት፤ ድንግልናውንም ይጠብቅ ዘንድ በልቡ ቢጸና መልካም አደረገ።'),
  ('54670706-398b-5a92-a2c7-1facd320993e', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 14, 38, 'ድንግሊቱን ያገባ መልካም አደረገ፤ ያላገባ ግን የምትሻለውን አደረገ።'),
  ('85099c9f-1990-55f6-a0b3-f795ae0705be', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 15, 39, 'ሴት ባልዋ በሕይወት ሳለ የታሠረች ናት፤ ባልዋ የሞተ እንደ ሆነ ግን ነጻ ናት፤ የወደደችውን ታግባ፤ ነገር ግን በእግዚአብሔር ይሁን።'),
  ('c3feed1b-af96-5188-a4e3-9752334a874b', '7545778b-3777-574e-a978-f078d03acdc8', '4667394b-daef-512a-a0c0-53416573f615', 16, 40, 'በምክሬ ጸንታ እንዲሁ ብትኖር ግን ብፅዕት ናት፤ የእግዚአብሔርም መንፈስ በእኔ ላይ ያለ ይመስለኛል።'),
  ('4b8e2b5e-0f8c-5e6b-a99d-4c045c7773f5', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 1, 1, 'ለጣዖታት ስለሚሠዉ መሥዋዕቶች ሁላችንም ዕውቀት እንዳለን እናውቃለን፤ ዕውቀት ያስታብያል፤ ፍቅር ግን ያንጻል።'),
  ('95052559-9016-53d4-ab52-3dc8c8dca473', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 2, 2, 'ዐወቅሁ የሚል ቢኖር፥ ሊያውቅ የሚገባውን ገና አላወቀም።'),
  ('2f31ccf6-91e2-5594-a0eb-ef0f083f0cd5', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 3, 3, 'እግዚአብሔርን የሚወድ ሰው ግን እርሱ በእርሱ ዘንድ በእውነት የታወቀ ነው።'),
  ('93d7bbc8-344c-54b1-a40b-2a65dc74fedb', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 4, 4, 'ለጣዖታት የተሠዋውን ስለመብላት ግን ጣዖት ሁሉ በዓለም ከንቱ እንደሆነ፥ ከአንድ እግዚአብሔርም በቀር ሌላ አምላክ እንደሌለ እናውቃለን።'),
  ('4cb31849-7b3f-5da1-aaad-35605dda36aa', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 5, 5, 'አማልክት የሚሉአቸው ነገሮች አሉና፤ በሰማይም ቢሆን፥ በምድርም ቢሆን፥ ብዙ አማልክትና ብዙ ጌቶች ቢኖሩ፥'),
  ('82494b4f-dab1-58b9-adce-4c04dff683bf', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 6, 6, 'ለእኛስ ሁሉ ከእርሱ የሆነ፥ እኛም ለእርሱ የሆን አንድ እግዚአብሔር አብ አለን፤ ሁሉ በእርሱ የሆነ፥ እኛም በእርሱ የሆን አንድ ጌታ ኢየሱስ ክርስቶስም አለን።'),
  ('5daa2d2b-96b9-570a-a10a-f761c55fcf84', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 7, 7, 'ነገር ግን ሁሉ የሚያውቀው አይደለም፤ እስከ ዛሬ በጣዖታት ልማድ፥ ለጣዖት የተሠዋውን የሚበሉ አሉ፤ ኅሊናቸውም ደካማ ስለሆነ ይረክሳል።'),
  ('08c39fb6-a024-5d75-a9c0-88b9bf4c54c8', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 8, 8, 'መብል ግን ወደ እግዚአብሔር አያደርሰንም፤ ብንበላም አይረባንም፤ ባንበላም አይጎዳንም።'),
  ('30f36772-b3ae-511b-aa58-12b0f96a6b0e', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 9, 9, 'ነገር ግን እናንተን በማየት ሌላው እንዳይሰናከል ተጠንቀቁ።'),
  ('1d6ec6ec-62ed-546f-a473-5c142257d989', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 10, 10, 'አንተ አማኙ በጣዖት ቤት በማዕድ ተቀምጠህ ያየህ ቢኖር ያ ልቡ ደካማ የሆነ ሰው ወዲያው ለጣዖት የተሠዋውን ደፍሮ ይበላል።'),
  ('dd4a5116-7845-5425-a798-fb29f268a569', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 11, 11, 'ክርስቶስ ስለ እርሱ የሞተለት ያ ደካማ ወንድም አንተን በማየት ይጎዳል።'),
  ('d3f8002d-2f9d-5bb0-a8eb-0f40847c70b4', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 12, 12, 'በባልንጀሮቻችሁ ላይ እንዲህ የምትበድሉ ከሆነ ደካማ ሕሊናቸውንም የምታቈስሉ ከሆነ ክርስቶስን ትበድላላችሁ።'),
  ('660f1e3d-12d7-5dc3-a1ad-75b15315cd34', 'c624bd83-8714-5c4a-ac28-47f405a1f7a1', 'b48fff75-d4df-54d8-a516-5a3dddab52a5', 13, 13, 'ነገር ግን በመብል ምክንያት ወንድሜ የሚሰናከል ከሆነ ወንድሜን እንዳላሰናክል ለዘለዓለም ሥጋን አልበላም።'),
  ('92cc997e-8595-562b-a121-09227fdda37f', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 1, 1, 'እኔ ነጻ አይደለሁምን? ሐዋርያስ አይደለሁምን? ጌታችን ኢየሱስ ክርስቶስን ያየሁ አይደለሁምን? እናንተስ በጌታችን ሥራዬ አይደላችሁምን?'),
  ('35fdf675-3967-5951-a0ce-0d3f9b80fa17', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 2, 2, 'ለሌሎች ሐዋርያቸው ባልሆንም ለእናንተስ ሐዋርያችሁ እኔ ነኝ፤ በጌታችን የሐዋርያነቴ ማኅተም እናንተ ናችሁና።'),
  ('8906853a-13a2-5676-af3f-21f6a37b41a7', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 3, 3, 'ለሚከራከሩኝ መልሴ እንዲህ ነው።'),
  ('a60eec2a-1659-58a9-ab9b-71c069435fe2', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 4, 4, 'በውኑ ልንበላና ልንጠጣ አይገባንምን?'),
  ('c1fb336d-645c-5439-aaed-05159bb6318b', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 5, 5, 'እንደ ሌሎች ሐዋርያት ሁሉና፥ እንደ ጌታችን ወንድሞች እንደ ኬፋም ከሴቶች እኅታችንን ይዘን ልንዞር አይገባንምን?'),
  ('4f2d2cec-bcbf-5491-a35a-e1ff340b7600', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 6, 6, 'ወይስ ሥራን ለመተው መብት የሌለን እኔና በርናባስ ብቻ ነን?'),
  ('d58bce81-2556-505b-ab6c-ff17623d16da', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 7, 7, 'የሚያገለግልም ምግቡን ያገኝ ዘንድ ነው፤ ወይን ተክሎ ፍሬውን የማይበላ ማን ነው? መንጋውንስ ጠብቆ ወተቱን የማይጠጣ ማን ነው?'),
  ('da5d97a6-312b-5668-a565-162dabb4ac73', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 8, 8, 'በውኑ ለሰው ይምሰል እናገራለሁን? የሙሴ መጽሐፍ ኦሪትስ እንዲህ ብሎ የለምን፦'),
  ('c98a3cf1-3a0d-5375-ae97-0e72951671ff', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 9, 9, '“እህልህን በምታበራይበት ጊዜ የበሬውን አፉን አትሰረው።” እንግዲህ ይህን የጻፈ ለእግዚአብሔር በሬ አሳዝኖት ነውን?'),
  ('9b5ff0a0-2ad6-5c56-a6d9-88b482c5979b', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 10, 10, 'ይህን የሚለው ፈጽሞ ስለ እኛ አይደለምን? የሚያርስ በተስፋ ሊያርስ፥ የሚያበራይም እንዲካፈል በተስፋ ሊያበራይ ስለሚገባው በእውነት ስለ እኛ ተጽፎአል።'),
  ('62580ff4-a3f7-51ae-a9ef-9a26a3a414b5', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 11, 11, 'እኛ መንፈሳዊውን ነገር ከዘራንላችሁ ሥጋዊውን ነገር ብናጭድ ታላቅ ነገር ነውን?'),
  ('085c49f9-0579-55cd-ab6e-e302f1c3f771', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 12, 12, 'በእኛ ሹመት ሌላ የሚቀድመን ከሆነ የሚሻላችሁን እናንተ ታውቃላችሁ፤ እኔ ይህን አልፈለግሁትም፤ ነገር ግን የክርስቶስን ትምህርት እንዳላሰናክል በሁሉ እታገሣለሁ።'),
  ('3866b9f8-8884-5a0a-a60c-2c86ebf25dfb', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 13, 13, 'የጣዖታቱ ካህናት የጣዖታቱን መባ እንደሚበሉ አታውቁምን? መሠዊያውን የሚያገለግሉም መሥዋዕቱን እንደሚካፈሉ አታውቁምን? ለቤተ እግዚአብሔር ሹሞች መተዳደሪያቸው የቤተ እግዚአብሔር መባ ነው።'),
  ('af0d7f39-bb40-5ebb-ac6c-61c45bd33df4', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 14, 14, 'ጌታችንም እንዲሁ ወንጌልን ለሚያስተምሩ ሰዎች ለሕይወታቸው መተዳደሪያ በዚያው ወንጌልን በማስተማር ይሆን ዘንድ አዘዘ።'),
  ('88712113-4d15-5247-a03f-fbc0605ffc41', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 15, 15, 'እኔ ግን ይህንም ቢሆን አልፈቀድሁትም፤ ይህን የጻፍሁም ይህን እንዳገኝ ብዬ አይደለም፤ እኔ ግን ምስጋናዬ ከሚቀርብኝ ሞት ይሻለኛል።'),
  ('2ac120c7-5424-5212-a5a4-d12417dd55aa', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 16, 16, 'ወንጌልን ባስተምርም መመስገን አይገባኝም፤ ታዝዤ አድርጌዋለሁና፤ ወንጌልን ባላስተምር ደግሞ ወዮልኝ።'),
  ('090e1599-ca55-5902-afd5-48638a4dfa60', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 17, 17, 'ይህንስ በፈቃዴ አድርጌው ብሆን ዋጋዬን ባገኘሁ ነበር፤ በግድ ከሆነ ግን በተሰጠኝ መጋቢነት አገለገልሁ።'),
  ('522da1c9-bc7b-5e36-a77d-fec4abcc3dc3', '84b13f90-8fad-5fbe-a689-37cbb113f676', '9a4c875e-79ca-5644-ac65-56fdfea97942', 18, 18, 'እንግዲህ ዋጋዬ ምንድን ነው? ወንጌልን ባስተምርም በሹመቴ የማገኘው ሳይኖር ወንጌልን ያለ ዋጋ እንዳስተምር ባደርግ ነው።'),
  ('ddbfc205-535c-55a6-a4f4-07794940fcea', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 1, 19, 'እኔ ከሁሉ ይልቅ ነጻ ስሆን ብዙዎችን ወደ ሃይማኖት እሰበስባቸው ዘንድ እንደ ባሪያ ራሴን ለሁሉ አስገዛሁ።'),
  ('fce2c142-ce1d-53e1-a28f-d4011f48dbe6', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 2, 20, 'አይሁድን እጠቅማቸው ዘንድ ለአይሁድ እንደ አይሁዳዊ ሆንሁላቸው፤ ከኦሪት በታች ያሉትን እጠቅም ዘንድ እኔ ራሴ ከኦሪት በታች ሳልሆን ከኦሪት በታች ላሉት ከኦሪት በታች እንዳለ ሰው ሆንሁላቸው።'),
  ('b9468126-b9d3-5a24-a924-32a7aeae88f1', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 3, 21, 'የእግዚአብሔርን ሕግ የዘነጋሁ ሳልሆን፥ በክርስቶስ ሕግም ሳለሁ ሕግ የሌላቸውን እጠቅማቸው ዘንድ ሕግ ለሌላቸው ሕግ እንደሌለው ሆንሁላቸው።'),
  ('3c966622-f628-5236-a99f-b1528153a202', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 4, 22, 'ደካሞችንም እጠቅማቸው ዘንድ ለደካሞች እንደ ደካማ ሆንሁላቸው፤ በሁሉ መንገድ አንዳንዶቹን አድን ዘንድ ከሁሉ ጋር በሁሉ ነገር እንደ እነርሱ ሆንሁ።'),
  ('ecf1eea7-baec-5be9-a46e-d72f6518ab93', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 5, 23, 'በወንጌልም ትምህርት አንድነት ይኖረኝ ዘንድ ስለ ወንጌል ትምህርት ሁሉን አደርጋለሁ።'),
  ('8044e743-34d3-5ed6-ab30-a13632f0c167', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 6, 24, 'በእሽቅድምድም ስፍራ የሚሽቀዳደሙ ሁሉ እንደሚፋጠኑ አታውቁምን? ለቀደመው የሚደረግለት ዋጋ አለ፤ እንዲሁ እናንተም እንድታገኙ ፈጽማችሁ ሩጡ።'),
  ('8489d9ff-4760-5b72-ad5f-0f278cab2be8', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 7, 25, 'የሚታገል ሁሉ በሁሉ ነገር ይታገሣል፤ እነርሱስ የሚጠፋውንና የሚያልፈውን የምስጋናቸውን ዋጋ አክሊል ያገኙ ዘንድ ይበረታሉ፤ እኛ ግን የማያልፈውን አክሊል ለማግኘት እንታገሣለን።'),
  ('ccbdfa2b-2fa6-57ee-a5a9-08f70c72bf20', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 8, 26, 'እኔ ያለ አሳብ እንደሚሮጥ ሁሉ እንዲሁ አልሮጥም፤ ነፋስንም እንደሚጐስም ሁሉ እንዲሁ አልጋደልም።'),
  ('095a2f48-d06a-5585-aff9-9f9cc8d8f936', '84b13f90-8fad-5fbe-a689-37cbb113f676', '78fb184c-4378-5f76-a309-8ef11bb88708', 9, 27, 'ነገር ግን ለሌላ ሳስተምር፥ እኔ ለራሴ የተናቅሁ እንዳልሆን ሰውነቴን አስጨንቃታለሁ፥ ሥጋዬንም አስገዛዋለሁ።'),
  ('7b9bf75a-dee5-5e99-a99d-1b96a76f679c', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 1, 1, 'ወንድሞቻችን ሆይ፥ አባቶቻችን ሁሉ ደመና እንደ ጋረዳቸው ሁሉም በባሕር መካከል አልፈው እንደ ሄዱ ልታውቁ እወዳለሁ።'),
  ('961890b1-cb4c-5fb5-a5e8-3d12262226b9', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 2, 2, 'ሁሉንም ሙሴ በደመናና በባሕር አጠመቃቸው።'),
  ('96c81e40-5e8d-5a7f-a857-4957f45f3a29', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 3, 3, 'ሁሉም ያን መንፈሳዊ ምግብ ተመገቡ።'),
  ('66d92122-9872-52d5-aa25-cf36a0cadc35', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 4, 4, 'ሁሉም ያን መንፈሳዊ መጠጥ ጠጡ፤ ይኸውም በኋላቸው ከሚሄደው ከመንፈሳዊ ዐለት የጠጡት ነው፤ ያም ዐለት ክርስቶስ ነበረ።'),
  ('1501155a-4b5c-5bce-a100-e90072c38017', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 5, 5, 'እግዚአብሔር ግን ከእነርሱ በሁሉም ደስ አላለውም፤ ብዙዎቹ በምድረ በዳ ወድቀዋልና።'),
  ('8982df76-4aac-5ed5-a34a-3600de4326c4', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 6, 6, 'እነርሱ እንደ ተመኙ እኛ ደግሞ ክፉ እንዳንመኝ እነርሱ ለእኛ ምሳሌ ሆኑልን።'),
  ('e8d375d5-2d65-5100-a79f-21f0f770ac74', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 7, 7, '“አሕዛብ ተቀመጡ፤ ይበሉና ይጠጡም ጀመር፤ ሊዘፍኑም ተነሡ” ብሎ መጽሐፍ እንደ ተናገረ ከእነርሱ አንዳንዶቹ እንደ አመለኩ ጣዖትን የምታመልኩ አትሁኑ።'),
  ('5ae4c86c-fb4c-546b-ac84-43d252947e6a', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 8, 8, 'ከእነርሱም አንዳንዶቹ እንደ ሴሰኑ፥ በአንድ ቀንም ሃያ ሦስት ሺህ ሰዎች እንደ ወደቁ አንሴስን።'),
  ('7ef4bc36-fb0f-5b63-a2d4-ac26b54ca597', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 9, 9, 'ከእነርሱም አንዳንዶቹ እግዚአብሔርን እንደ ተፈታተኑት፥ ነዘር እባብም እንደ አጠፋቸው እግዚአብሔርን አንፈታተን።'),
  ('bf926ada-8820-593c-af08-1ade90f60473', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 10, 10, 'ከእነርሱም አንዳንዶቹ እንዳንጐራጐሩበት፥ በመቅሠፍትም እንደጠፉ አናንጐራጕር።'),
  ('b4592d91-d97d-5eda-a049-3a0d739da61f', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 11, 11, 'እነርሱን ያገኛቸው ይህ ሁሉ ነገር በኋላ ዘመን ለምንነሣው ለእኛ ትምህርትና ምክር ሊሆነን ምሳሌ ሆኖ ተጻፈ።'),
  ('210c1239-194d-59a9-aa92-f89d3133b714', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 12, 12, 'አሁንም ያ ቆሜአለሁ ብሎ በራሱ የሚታመን ሰው እርሱ እንዳይወድቅ ይጠንቀቅ።'),
  ('8beb6c93-34b7-5311-ae69-88a78c071245', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'e4f6745d-f82e-59a3-adf2-c96962873665', 13, 13, 'በሰው ላይ እንደሚደርሰው ያለ ፈተና ነው እንጂ ሌላ ፈተና አያገኛችሁም። በምትችሉት መከራ ነው እንጂ በማትችሉት መከራ ትፈተኑ ዘንድ ያልተዋችሁ እግዚአብሔር የተመሰገነ ነው፤ እርሱም ከፈተና ትድኑ ዘንድ በመከራ ጊዜ ይረዳችኋል።'),
  ('27afa942-4943-570d-a304-a83d95c2f134', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 1, 14, 'ወንድሞች! አሁንም ጣዖት ከማምለክ ሽሹ።'),
  ('2c6a4a52-d31b-5631-ac7f-9fe91f4871f7', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 2, 15, 'ለዐዋቂዎች እንደሚነገር እነግራችኋለሁ፤ ትክክለኛውንም እናንተ ራሳችሁ ፍረዱ።'),
  ('7a1d2845-6f5b-5eb2-a5e8-167fc2f42766', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 3, 16, 'ይህ የምንባርከው የበረከት ጽዋ ከክርስቶስ ደም ጋር አንድ አይደለምን? የምንፈትተው ይህስ ኅብስት ከክርስቶስ ሥጋ ጋር አንድ አይደለምን?'),
  ('2f604fc5-67c1-5688-a6da-779c1c4ac53c', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 4, 17, 'ኅብስቱ አንድ እንደ ሆነ እንዲሁ እኛም ብዙዎች ስንሆን አንድ አካል ነን፤ ሁላችን ከአንድ ኅብስት እንቀበላለንና።'),
  ('05190844-0a12-55ab-a2e3-986cab2adce8', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 5, 18, 'እስራኤል ዘሥጋን ተመልከቱ፤ መሥዋዕቱን ይበላሉ፤ ከመሠዊያውም ጋር አንድ ይሆኑ አልነበረምን?'),
  ('2fd4ff39-1cf9-5c39-a277-c1aa60f1f725', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 6, 19, 'እንግዲህ ምን እንላለን? ለጣዖታት የሚሠዋ መሥዋዕት ከንቱ ነው፤ ጣዖቶቻቸውም ከንቱ ናቸው።'),
  ('7dbba69f-cbea-58ba-ac25-4eb9022b0923', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 7, 20, 'አሕዛብም የሚሠዉ ለአጋንንት ነው እንጂ ለእግዚአብሔር አይደለም፤ ነገር ግን የአጋንንት ተባባሪዎች እንድትሆኑ አልፈቅድላችሁም።'),
  ('d76f1155-1b95-55a0-a666-c8fe452ac9e8', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 8, 21, 'የእግዚአብሔርን ጽዋና የአጋንንትን ጽዋ አንድ አድርጋችሁ መጠጣት አትችሉም፤ የእግዚአብሔርን ማዕድና የአጋንንትንም ማዕድ በአንድነት ልትበሉ አትችሉም።'),
  ('797cece7-eeaa-5b62-ac7a-808a23eb25ec', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 9, 22, 'እንግዲህ እግዚአብሔርን እናስቀናውን? በውኑ እኛ ከእርሱ እንበረታለን?'),
  ('34a9e29e-1b41-57a5-a156-3d863689b9cd', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 10, 23, 'ሁሉ ተፈቅዶልኛል፤ ነገር ግን ሁሉ የሚጠቅም አይደለም፤ ሁሉ ተፈቅዶልኛል፤ ነገር ግን ሁሉ የሚያንጽ አይደለም።'),
  ('079ec362-c8a4-5f45-ac2d-f3baea7c0691', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 11, 24, 'ለባልንጀራችሁ እንጂ ለራሳችሁ አታድሉ።'),
  ('393b3db7-1727-5ff5-aa36-0f92564d8422', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 12, 25, 'ደግሞም በሥጋ ገበያ የሚሸጡትን ሁሉ ከሕሊና የተነሣ ሳትመራመሩ ብሉ።'),
  ('48daa519-8436-55f0-a2dc-37763c6da125', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 13, 26, '“ምድር በመላዋ የእግዚአብሔር ናትና።”'),
  ('555c39f0-691c-5964-a478-969b6164f9e6', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 14, 27, 'ያላመነ ሰው ቢጠራችሁ፥ ልትሄዱም ብትወዱ ያቀረቡላችሁን ሁሉ ከሕሊና የተነሣ ሳትመራመሩ ብሉ።'),
  ('8af81bd3-ed5a-5db1-a6b1-039e96d57b40', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 15, 28, 'እንግዲህ “ይህ ለጣዖት የተሠዋ ነው” ያላችሁ ቢኖር ግን፥ ስለ ነገራችሁና ባልንጀራችሁም የሚጠራጠር ስለሆነ አትብሉ።'),
  ('de302755-6f13-5801-ad18-eb24df91f8ec', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 16, 29, 'ነጻነታችሁን እንዳይነቅፉአት አስረድተዋችኋልና።'),
  ('56ee5738-e449-5aa2-a185-806975d06c36', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 17, 30, 'በጸጋ ብበላ ግን በነገሩ ስለማመሰግን ለምን ይነቅፉኛል።'),
  ('e74bd33b-dd47-5b91-ae7d-6b49244a7081', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 18, 31, 'ብትበሉም፥ ብትጠጡም የምታደርጉትን ሁሉ ለእግዚአብሔር ክብር አድርጉት።'),
  ('1fc42f99-4478-5dd6-ad6f-971376d668d0', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 19, 32, 'ለአይሁድም፥ ለአረማውያንም፥ ለእግዚአብሔር ቤተ ክርስቲያንም ያለ ማሰናከል አርአያ ሁኑአቸው።'),
  ('083c745f-1e41-5a27-a1d6-6d573bee9367', '2099df7a-4e02-52cf-a98e-19bc6247f945', 'd6bb36d9-2aef-5851-a662-1708b4af80c3', 20, 33, 'እኔም ሁሉን በሁሉ ነገር ደስ እንዳሰኝ ይድኑ ዘንድ የብዙዎችን ተድላ እሻለሁ እንጂ የራሴን ተድላ የምሻ አይደለሁምና።'),
  ('e0c43514-b95d-5c06-a87f-52b0dfc29e3c', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'd91eecc0-08d4-557b-a095-09baac0ae764', 1, 1, 'እኔ ክርስቶስን እንደምመስለው እኔን ምሰሉ።'),
  ('0768d9e7-ac50-5d95-a1f0-57642f1d3c13', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'd91eecc0-08d4-557b-a095-09baac0ae764', 2, 2, 'ወንድሞች ሆይ፥ አመሰግናችኋለሁ፤ ዘወትር ታስቡኛላችሁና፤ ያስተማርኋችሁንም ትምህርት ጠብቃችኋልና።'),
  ('97ac7806-4c2c-5282-ace9-89310705aadd', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'd91eecc0-08d4-557b-a095-09baac0ae764', 3, 3, 'ነገር ግን የወንድ ሁሉ ራሱ ክርስቶስ፥ የሴትም ራስዋ ወንድ፤ የክርስቶስም ራሱ እግዚአብሔር እንደ ሆነ ልታውቁ እወድዳለሁ።'),
  ('4c0e04e1-9091-5415-a7fc-3a7d67dde580', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 1, 4, 'ራሱን ተከናንቦ የሚጸልይ ወይም የሚያስተምር ወንድ ሁሉ ራሱን ያዋርዳል።'),
  ('e95118e1-19d5-59ec-a998-4440bed6fc1d', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 2, 5, 'ራስዋን ሳትከናነብ የምትጸልይ ወይም የምታስተምር ሴት ሁላ ራስዋን ታዋርዳለች፤ ራስዋን እንደ ተላጨች መሆንዋ ነውና።'),
  ('0d6e26eb-f5ab-5a4d-abb9-30d3269a9ac5', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 3, 6, 'ሴት ካልተከናነበች ትላጭ ወይም ጠጕርዋን ትቈረጥ፤ ለሴት ጠጕርዋን መቈረጥ ወይም መላጨት ውርደት ከሆነ ትከናነብ።'),
  ('18611a78-a3b6-538c-ac69-a9f2f49897ff', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 4, 7, 'ወንድ በሚጸልይበት ጊዜ ሊከናነብ አይገባውም፤ የእግዚአብሔር አርአያውና አምሳሉ ነውና፤ ሴትም ለባልዋ ክብር ናት።'),
  ('fabce681-1ad7-52b7-abde-e57d7d2635dc', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 5, 8, 'ሴት ከወንድ ተገኝታለችና፤ ወንድ ግን ከሴት የተገኘ አይደለም።'),
  ('46321856-b1c8-567d-acfa-2ef0521fa38c', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 6, 9, 'ወንድ ስለ ሴት አልተፈጠረም፤ ሴት ስለ ወንድ ተፈጠረች እንጂ።'),
  ('9e599313-69cd-5857-a9b7-ef9f03c2f3b9', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 7, 10, 'ስለዚህም ሴት ስለ መላእክት፥ ሥልጣን ለራስዋ ሊሆን ይገባል፤'),
  ('0929f96b-ca90-5b97-ab65-821c93040a8d', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 8, 11, 'ነገር ግን አሁን ሴት ከባሏ አትለይ፤ ወንድም ከሚስቱ አይለይ፤ ሁላችሁም በጌታችን ኑሩ።'),
  ('59ed83f6-bbf8-5a30-a170-8255cc3e8f79', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 9, 12, 'ሴት ከወንድ እንደ ተገኘች እንዲሁ ወንድ ከሴት ተገኘ፤ ነገር ግን ሁሉ ከእግዚአብሔር ነው።'),
  ('7b7dee80-87a0-50d0-a241-dfb1c281b61e', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 10, 13, 'እስኪ እናንተ ራሳችሁ ፍረዱ፤ ሴት ወደ እግዚአብሔር በምትጸልይበት ጊዜ ልትከናነብ አይገባምን?'),
  ('b1fbef3d-5c1f-5ec2-a281-44f9b8681618', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 11, 14, 'ተፈጥሮዋስ አያስረዳችሁምን? ወንድ ግን ጠጕሩን ቢያሳድግ ነውር ነው።'),
  ('7a6bbcbd-4017-5720-a756-941f9a103817', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 12, 15, 'ለሴት ግን ጠጕርዋን ብታሳድግ ክብርዋ ነው፤ ለሴት ጠጕርዋ እንደ ቀጸላ ሆኖ ተሰጥቶአታልና።'),
  ('0058a006-4837-5ba8-a85e-25f841c0516f', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '8481d182-2d35-50a8-a971-5355cce13aa1', 13, 16, 'ነገር ግን የሚጠራጠር ቢኖር እኛ ወይም የእግዚአብሔር ቤተ ክርስቲያን እንዲህ ያለ ልማድ የለንም።'),
  ('fb5e62d0-a74a-56e6-a8ce-d8e7c0cb2b80', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'f8a2fac2-7e09-5e38-a55e-aecae184f5fe', 1, 17, 'ይህንም የነገርኋችሁ ላመሰግናችሁ አይደለም፤ በምትሰበሰቡበት ጊዜ ወደ ዝቅተኛ እንጂ ወደሚሻል ግብር አትሄዱምና።'),
  ('44eb84d7-308e-5553-a6db-deeae52638a7', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'f8a2fac2-7e09-5e38-a55e-aecae184f5fe', 2, 18, 'ከሁሉ አስቀድሞ በቤተ ክርስቲያን በምትሰበሰቡ ጊዜ እንደምትጣሉና እንደምትከራከሩ ሰምቻለሁ፤ የማምነውም አለኝ።'),
  ('1a3767db-e743-5370-a3a1-ffa21cfb1000', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'f8a2fac2-7e09-5e38-a55e-aecae184f5fe', 3, 19, 'ከእናንተ የተመረጡት ወንድሞች ተለይተው እንዲታወቁ ትለያዩ ዘንድ ግድ ነው።'),
  ('529b2601-2c35-5d99-a30a-3f9653cbbc94', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'f8a2fac2-7e09-5e38-a55e-aecae184f5fe', 4, 20, 'እንግዲህ እናንተም በምትሰበሰቡበት ጊዜ የምትበሉና የምትጠጡ ለጌታችን ቀን እንደሚገባ አይደለም።'),
  ('a1f263c6-b7e9-5323-a1a2-2c3b6f081d22', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'f8a2fac2-7e09-5e38-a55e-aecae184f5fe', 5, 21, 'ወደ ምግብ ትሽቀዳደማላችሁ፤ የተራቡ በአጠገባችሁ እያሉ እናንተ ትበላላችሁ፤ ትጠግባላችሁ፤ ትሰክራላችሁም።'),
  ('0971a83b-7bf1-5e84-a90c-95f31fb9c9a6', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', 'f8a2fac2-7e09-5e38-a55e-aecae184f5fe', 6, 22, 'በውኑ የምትበሉበትና የምትጠጡበት ቤት የላችሁምን? ወይስ የእግዚአብሔርን ቤተ ክርስቲያን ታስነቅፋላችሁን? ነዳያንንስ ታሳፍሩአቸዋላችሁን? ምን እላለሁ? በዚህ አመሰግናችኋለሁን? አላመሰግናችሁም።'),
  ('cfcfd171-f4f4-520f-a3dc-53afc759658e', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 1, 23, 'ከእግዚአብሔር እንደ ተማርሁ አስተምሬአችኋለሁና፤ ጌታችን ኢየሱስ ክርስቶስ እርሱን ራሱን በያዙባት በዚያች ሌሊት ኅብስቱን አነሣ።'),
  ('c0b50257-9205-508e-a60b-636db5d1a12c', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 2, 24, 'አመሰገነ፤ ባረከ፤ ፈተተ፤ እንዲህም አላቸው፥ “እንኩ ብሉ፤ ስለ እናንተ የሚሰጠው ሥጋዬ ይህ ነው፤ መታሰቢያዬንም እንዲሁ አድርጉ።”'),
  ('0c486d93-a08f-512a-acf9-7ae1d7cee98e', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 3, 25, 'እንዲሁም ኅብስቱን ከተቀበሉ በኋላ ጽዋውን አንሥቶ፥ “አዲስ ሥርዐት የሚጸናበት ይህ ጽዋ ደሜ ነው እንዲህ አድርጉ፤ በምትጠጡበትም ጊዜ አስቡኝ” አላቸው።'),
  ('d9bc5741-6d8c-5d9f-a573-f7695a33689d', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 4, 26, 'ይህን ኅብስት በምትበሉበት፥ ይህንም ጽዋ በምትጠጡበት ጊዜ ሁሉ ጌታችን እስከሚመጣበት ቀን ድረስ ሞቱን ትናገራላችሁ።'),
  ('c0860468-9a3c-5254-a346-720364198a47', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 5, 27, 'አሁንም ሳይገባው ይህን ኅብስት የበላ፥ ይህንም ጽዋ የጠጣ የጌታችን ሥጋውና ደሙ ስለሆነ ዕዳ አለበት።'),
  ('c8b338fd-faf7-5212-a68a-3f16bc1075ac', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 6, 28, 'አሁንም ሰው ራሱን መርምሮና አንጽቶ ከዚህ ኅብስት ይብላ፤ ከዚህም ጽዋ ይጠጣ።'),
  ('4623a18e-5e81-5839-aff8-91b657475c21', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 7, 29, 'ሳይገባው፥ የጌታችን ሥጋም እንደ ሆነ ሳያውቅ፥ ሰውነቱንም ሳያነጻ፥ የሚበላና የሚጠጣ ለራሱ ፍርዱንና መቅሠፍቱን ይበላል፤ ይጠጣልም።'),
  ('ac720ff9-10db-577c-a39b-73523da5e103', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 8, 30, 'ስለዚህ ከመካከላችሁ የደከሙና የታመሙ ብዙዎች ናቸው፤ ብዙዎችም በድንገት አንቀላፍተዋል።'),
  ('ee7a6b0a-883b-54ff-a3b7-e235d911c2a9', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 9, 31, 'እኛ በራሳችን ብንፈርድ ኖሮ ባልተፈረደብንም ነበር።'),
  ('a439ef66-266a-5d1a-a283-256e3abd4e15', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 10, 32, 'ነገር ግን በተፈረደብን ጊዜ ከዓለም ጋር እንዳንኰነን በጌታ እንገሠጻለን።'),
  ('5931f922-791b-54f9-a472-aff234dbdce6', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 11, 33, 'አሁንም ወንሞቻችን ሆይ፥ ለምሳ በምትሰበሰቡበት ጊዜ እርስ በርሳችሁ ተጠባበቁ፤'),
  ('bb091018-9761-5952-ae69-486e71bd3e9b', '45249bb1-68e0-5f10-a284-4882bf6d7dd7', '87085085-23c5-5090-a309-de73d9320918', 12, 34, 'መሰብሰባችሁ ለፍዳ እንዳይሆን፥ የተራበ ቢኖር በቤቱ ይብላ፤ አትነቃቀፉም፤ ሌላውን ሥርዐት ግን መጥቼ እሠራላችኋለሁ።'),
  ('12d70639-0da7-54da-a7d9-8453b9484d97', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 1, 1, 'ወንድሞቻችን ሆይ፥ ስለ መንፈስ ቅዱስ ስጦታም ታውቁ ዘንድ እንጂ አላዋቆች ልትሆኑ አንወድድም።'),
  ('282acbff-c4c9-5460-a2da-356bc250905c', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 2, 2, 'ቀድሞም እናንተ አሕዛብ በነበራችሁ ጊዜ ዲዳዎች ጣዖታትን ታመልኩ እንደ ነበር፥ ጣዖትም በማምለክ ረክሳችሁ እንደ ነበር፥ ወደ ወሰዱአችሁም ትሄዱ እንደ ነበር ታውቃላችሁ።'),
  ('f06fd87a-62ef-5356-a496-0cf9579f03f8', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 3, 3, 'ስለዚህም ማንም በእግዚአብሔር መንፈስ ሲናገር፥ “ኢየሱስ ውጉዝ ነው” የሚል እንደሌለ፥ በመንፈስ ቅዱስም ካልሆነ በቀር “ኢየሱስ ጌታ ነው” ሊል አንድስ እንኳን እንዳይችል አስታውቃችኋለሁ።'),
  ('b39e6c24-195c-5f39-a817-40451387fccb', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 4, 4, 'መንፈስ ቅዱስ አንድ ሲሆን ስጦታው ልዩ ልዩ ነው።'),
  ('7fc2aa57-0260-51bf-ab16-0031f354106a', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 5, 5, 'ጌታም አንድ ሲሆን ልዩ ልዩ አገልግሎቶች አሉ።'),
  ('6974a208-adc1-5ada-a0d8-e757eb97cf0b', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 6, 6, 'ሁሉን በሁሉ የሚያደርግ እግዚአብሔርም አንድ ሲሆን ልዩ ልዩ አሠራር አለ።'),
  ('c634c8a0-a568-5622-a77f-f7e8fb30a108', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 7, 7, 'ለሁሉም ጌታ እየረዳ በየዕድሉ እንደሚገባውና እንደሚጠቅመው ለእያንዳንዱ በግልጥ ይሰጠዋል፤'),
  ('b450dee5-b389-5222-a74d-35448cebd9d0', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 8, 8, 'በመንፈስ ቅዱስ የጥበብ ቃል የሚሰጠው አለ፤ በመንፈስ ቅዱስም የዕውቀት ቃል የሚሰጠው አለ።'),
  ('3c8c654a-483d-56f0-aa4a-9ec0a50c8dd0', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 9, 9, 'ለአንዱም በዚያው መንፈስ እምነት፥ ለአንዱም በአንዱ መንፈስ የመፈወስ ስጦታ፥'),
  ('7576b5cc-b1a1-5342-add1-420c2c4113d2', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 10, 10, 'ለአንዱም ተአምራትን ማድረግ፥ ለአንዱም ትንቢትን መናገር፥ ለአንዱም መናፍስትን መለየት፥ ለአንዱም በልዩ ዓይነት ልሳን መናገር፥ ለአንዱም በልሳኖች የተነገረውን መተርጐም ይሰጠዋል።'),
  ('3d7f8327-62eb-514a-a768-31d7232f14bb', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 11, 11, 'በዚህም ሁሉ ያው አንዱ መንፈስ ቅዱስ ሁሉን ይረዳል፤ ለሁሉም እንደ ወደደ ያድላቸዋል።'),
  ('eec95488-be0f-5578-a13f-5a6ccd7207ff', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 12, 12, 'አካል አንድ እንደ ሆነ ብዙ የአካል ክፍሎችም እንደ አሉበት፥ ነገር ግን የአካል ክፍሎች ሁሉ ብዙዎች ሳሉ አንድ አካል እንደ ሆኑ ክርስቶስ ደግሞ እንዲሁ ነው፤'),
  ('35606e3a-2be9-5d25-a003-21f5b751e2db', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 13, 13, 'እኛ ሁላችንም በአንድ መንፈስ አንድ አካል ለመሆን ተጠምቀናል፤ አይሁድ ብንሆን፥ አረማውያንም ብንሆን፥ ባሪያዎችም ብንሆን፥ ነጻዎችም ብንሆን ሁላችን አንድ መንፈስ ጠጥተናልና።'),
  ('00c19c6d-8cdd-5e80-a37f-616a1c235eb3', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 14, 14, 'የአካላችንም ክፍሉ ብዙ ነው እንጂ አንድ አይደለም።'),
  ('5c2d7c7f-1488-5ea5-acdf-4b8d5cb5f8f4', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 15, 15, 'እግርም፥ “እኔ እጅ አይደለሁምና የአካል ክፍል አይደለሁም” ብትል ይህን በማለቷ የአካል ክፍል መሆንዋ ይቀራልን?'),
  ('dacf9738-c8b6-50a6-aa06-f9391ccd499f', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 16, 16, 'ጆሮም፥ “እኔ ዐይን አይደለሁምና የአካል ክፍል አይደለሁም” ብትል ይህን በማለቷ የአካል ክፍል መሆንዋ ይቀራልን?'),
  ('f7105277-cb8b-5129-a61d-b9d6ca8a9b34', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 17, 17, 'አካል ሁሉ ዐይን ቢሆን ኖሮ መስማት ከየት በተገኘ ነበር፤ አካልስ ሁሉ ጆሮ ቢሆን ኖሮ ማሽተት ከየት በተገኘ ነበር?'),
  ('e3b6e564-b8e2-5ac6-adde-311cadb87103', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 18, 18, 'አሁን ግን እግዚአብሔር የአካላችንን ክፍል በሰውነታችን ውስጥ እርሱ እንደ ወደደ እየራሱ አከናውኖ መደበው።'),
  ('7e28e298-e57a-5b83-a87d-9a18e45b92f1', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 19, 19, 'የአካል ክፍሉ አንድ ቢሆን ኖሮ አካል የት በተገኘ ነበር?'),
  ('0315dad1-7249-5ad8-a851-f95ba89c26ba', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 20, 20, 'አሁንም የአካል ክፍሎች ብዙዎች ናቸው ፤ አካሉ ግን አንድ ነው።'),
  ('94c503b4-f99a-55b4-a02e-511fda3f5f2d', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 21, 21, 'ዐይን እጅን፥ “አልፈልግሽም” ልትላት አትችልም፤ ራስም፥ “እግሮችን አልፈልጋችሁም” ልትላቸው አትችልም።'),
  ('cceca58f-0a04-51e2-acea-0911d97724a8', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 22, 22, 'ደካሞች የሚመስሉህ የአካል ክፍሎች ይልቁን የሚያስፈልጉህ ናቸው።'),
  ('97399c20-54c3-5906-a3bc-6c1a8382844d', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 23, 23, 'ከአካልም ክፍሎች የተናቁ ለሚመስሉን ክብርን እንጨምርላቸዋለን፤ ለምናፍርባቸውም የአካል ክፍሎች ክብር ይጨመርላቸዋል።'),
  ('83ed76bc-8785-520e-a32e-6cb9abd19db0', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 24, 24, 'ለከበረው የአካላችን ክፍል ክብርን አንሻለትም፤ እግዚአብሔር ግን ሰውነታችንን አስማምቶታል፤ ይልቁንም ታናሹን የአካል ክፍል አክብሮታል።'),
  ('175c6dd7-a17d-51b0-a377-f1e51ee148c1', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 25, 25, 'የአካላችን ክፍሎች እርስ በርሳቸው እንዳይለያዩ፥ አካላችን ሳይነጣጠል በክብር እንዲተካከል አስማማው።'),
  ('68c2ef63-43ff-51f3-ae5b-3ae71ed087ec', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 26, 26, 'አንዱ የአካል ክፍል ቢታመም ከእርሱ ጋር የአካል ክፍሎች ሁሉ ይታመማሉ፤ አንዱ የአካል ክፍል ደስ ቢለውም የአካል ክፍሎች ሁሉ ከእርሱ ጋር ደስ ይላቸዋል።'),
  ('482a4ca7-5389-5598-af26-80fa85411ee2', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 27, 27, 'እንግዲህ እናንተ የክርስቶስ አካሉ ናችሁ፤ እያንዳንዳችሁም የአካሉ ክፍሎች ናችሁ።'),
  ('b48c9368-f472-5a17-ad2f-42d1e65feb90', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 28, 28, 'እግዚአብሔር ለቤተ ክርስቲያን የሾማቸው አስቀድሞ ሐዋርያትን፥ ሁለተኛም ነቢያትን፥ ሦስተኛም መምህራንን፥ ከዚህም በኋላ ተአምራትና ኀይል ማድረግ የተሰጣቸውን፥ ቀጥሎም የመፈወስ ሀብት የተሰጣቸውን፥ የመርዳትም ሀብት የተሰጣቸውን፥ የመምራትና ቋንቋን የመናገር ሀብት የተሰጣቸውን ነው።'),
  ('fb70cd66-bb98-5c67-ae98-764f6302f805', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 29, 29, 'በውኑ ሁሉ ሐዋርያትን ይሆናሉን? ሁሉስ ነቢያትን ይሆናሉን? ሁሉስ መምህራንን ይሆናሉን? ለሁሉስ ተአምራትን የማድረግ ኀይል ይሰጣልን?'),
  ('a49866f3-8ada-57ee-a34a-bca7d7a3738b', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 30, 30, 'ለሁሉስ የመፈወስ ሀብት ይሰጣልን? ሁሉስ በቋንቋ ይናገራሉን? ሁሉስ ይተረጕማሉን?'),
  ('e041fd11-9bdd-548a-a2c4-a09358cad4db', '1fde8eb7-5f91-58b7-ae61-42048d28fee7', '728c677f-e363-5490-abb1-154511c4c1e8', 31, 31, 'ነገር ግን ለምትበልጠው ጸጋ ቅኑ፤ ደግሞም የምትሻለውን መንገድ አስተምራችኋለሁ።'),
  ('a314f059-4374-586e-acd6-9e832706e47e', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 1, 1, 'የሰውን ሁሉ ቋንቋ ባውቅ፥ የመላእክትንም ሁሉ ቋንቋ ባውቅ፥ ነገር ግን ፍቅር ከሌለኝ እንደሚጮህ ነሐስ፥ ወይም እንደሚመታ ከበሮ መሆኔ ነው።'),
  ('16eb2671-73eb-5e79-af08-ce78846c715b', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 2, 2, 'ትንቢት ብናገር፥ የተሰውረውን ሁሉ፥ ጥበብንም ሁሉ ባውቅ፥ ተራራ እስከ ማፍለስ የሚያደርስ ፍጹም እምነትም ቢኖረኝ ፍቅር ከሌለኝ ከንቱ ነኝ።'),
  ('a84f4953-fa83-5daf-a8b9-63ce133e6c9a', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 3, 3, 'ገንዘቤን ሁሉ ለምጽዋት ብሰጥ፥ ሥጋዬንም ለእሳት መቃጠል ብሰጥ፥ ነገር ግን ፍቅር ከሌለኝ ምንም አይጠቅመኝም።'),
  ('3629f803-bb71-55c9-a436-2cf9da0f7332', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 4, 4, 'ፍቅር ያስታግሣል፤ ፍቅር ያስተዛዝናል፤ ፍቅር አያቀናናም፤ ፍቅር አያስመካም፤ ፍቅር ልቡናን አያስታብይም።'),
  ('1f7a3946-3b20-59f7-ab54-3f0c4a3387f8', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 5, 5, 'ብቻዬን ይድላኝ አያሰኝም፤ አያበሳጭም፤ ክፉ ነገርንም አያሳስብም።'),
  ('267e5046-6038-5e46-a168-c00669e16f60', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 6, 6, 'ጽድቅን በመሥራት ደስ ያሰኛል እንጂ፥ ግፍን በመሥራት ደስ አያሰኝም።'),
  ('a2c98e96-52b0-585e-adfd-df7a3b264b31', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 7, 7, 'በሁሉ ያቻችላል፤ በሁሉም ያስተማምናል፤ በሁሉም ተስፋ ያስደርጋል፥ በሁሉም ያስታግሣል።'),
  ('76d3d565-e7d7-534d-a1b3-5c6c1d263d3c', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 8, 8, 'ፍቅር ለዘወትር አይጥልም፤ ትንቢት የሚናገርም ያልፋል፤ ይሻራልም፤ በልዩ ልዩ ቋንቋ የሚናገርም ያልፋል፤ ይቀራል፤ የሚራቀቅም ያልፋል፤ ይጠፋል።'),
  ('c32b45c7-699d-5803-ab79-20db1871a055', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 9, 9, 'በየገጹ ጥቂት ጥቂት እናውቃለንና፤ ጥቂት ጥቂት ትንቢትም እንናገራለንና።'),
  ('dc0e7d9e-48b2-5bcd-a7e5-a53f2b037a0c', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 10, 10, 'ፍጹም የሆነ ሲመጣ ግን ያ ተከፍሎ የነበረው ይሻራል።'),
  ('4b4589d1-fdce-5b36-ad15-b07b21eac7f4', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 11, 11, 'እኔ ልጅ በነበርሁ ጊዜ እንደ ልጅ እናገር ነበር፤ እንደ ልጅም አስብ ነበር፤ እንደ ልጅም እመክር ነበር፤ በአደግሁ ጊዜ ግን የልጅነትን ጠባይ ሁሉ ሻርሁ።'),
  ('b2b255c7-1244-5150-ac41-de7aa07d187a', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 12, 12, 'አሁን ግን ታወቀኝ፤ በግልጥም ተረዳኝ፤ በመስታወትም እንደሚያይ ሰው ዛሬ በድንግዝግዝታ እናያለን፤ ያን ጊዜ ግን ፊት ለፊት እናያለን፤ አሁን በከፊል፥ ኋላ ግን እንደ ተገለጠልኝ መጠን ሁሉን አውቃለሁ።'),
  ('9c085984-5285-535c-ae04-3b15835db016', '32cd39e5-1b09-5162-a193-fc6fa6581efa', '4e51f7e7-15fa-588f-ac69-6b770ab06010', 13, 13, 'አሁንም እነዚህ ሦስቱ እምነት፥ ተስፋና ፍቅር ጸንተው ይኖራሉ፤ ከሁሉ ግን ፍቅር ይበልጣል።'),
  ('d35681f7-5351-588a-a268-5bae8802c8ec', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 1, 1, 'ፍቅርን ተከተሏት፤ ለመንፈሳዊ ስጦታ፥ ይልቁንም ትንቢት ለመናገር ተፎካከሩ።'),
  ('10c85cdb-6002-5fe2-ac5b-8f75fa2d7333', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 2, 2, 'በቋንቋ የሚናገር ለእግዚአብሔር እንጂ ለሰው የሚናገር አይደለም። የሚናገረውን የሚሰማው የለምና፥ ነገር ግን በመንፈስ ምሥጢርን ይናገራል።'),
  ('50716ebe-0588-54ac-a26d-ae155f3af7bd', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 3, 3, 'ትንቢትን የሚናገር ግን ለማነጽና ለመምከር፥ ለማረጋጋትም ለሰው ይናገራል።'),
  ('c32a6691-543a-5402-ab10-71e0f113c812', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 4, 4, 'በቋንቋ የሚናገር ራሱን ያንጻል፤ የሚተረጕም ግን የክርስቲያን ማኅበርን ያንጻል።'),
  ('b4d18cce-4f28-5848-aaa8-970ac164b61e', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 5, 5, 'ሁላችሁም በቋንቋ ልትናገሩ እወዳለሁ፤ ይልቁንም ትንቢት ልትናገሩ እወዳለሁ፤ ሳይተረጕም በቋንቋ ከሚናገር ይልቅ ትንቢት የሚናገር እጅግ ይበልጣልና፤ ቢተረጕም ግን ማኅበሩን ያንጻል።'),
  ('16b7702d-1c14-5ac1-a00a-09793d7fd0ce', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 6, 6, 'አሁንም ወንድሞች ሆይ፥ ወደ እናንተ መጥቼ በማታውቁት ቋንቋ ባነጋግራችሁ፥ የጥበብ ነገርንም ቢሆን፥ የትንቢትንም ነገር ቢሆን፥ የማስተማር ሥራንም ቢሆን ገልጬ ካልነገርኋችሁ የምጠቅማችሁ ጥቅም ምንድን ነው?'),
  ('a767dc52-c1bb-5b76-a6e2-0d004589f2d9', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 7, 7, 'ነፍስ የሌለው ድምፅ የሚሰጥ እንደ መሰንቆ፥ ወይም እንደ ክራር ያለ መሣሪያ በስልት ካልተመታ መሰንቆው ወይም ክራሩ የሚለውን ማን ያውቃል?'),
  ('3d182ec9-8cfc-5bb4-a9a1-95cd501e7ac1', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 8, 8, 'መለከት የሚነፋም በታወቀው ስልት ካልነፋ ለጦርነት ማን ይዘጋጃል?'),
  ('8a853dcf-e838-5227-a7a8-d1d3d98dc78b', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 9, 9, 'እንዲሁም እናንተ በማይታወቅ ቋንቋ ብትናገሩ፥ ይህንኑም ገልጣችሁ ባትተረጕሙ የምትሉትንና የምትናገሩትን ማን ያውቃል? ከነፋስ ጋር እንደምትነጋገሩ ትሆናላችሁ።'),
  ('55d036dc-d4c3-5dcd-a5c5-35b134c17092', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 10, 10, 'በዓለም ልዩ ልዩ ቋንቋዎች አሉ፤ ከእነርሱም ትርጕም የሌለው አንድም የለም።'),
  ('9980ecf6-2ca0-5011-a2ec-9037cc5c8462', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 11, 11, 'የቋንቋውን ትርጓሜ ካላወቅሁ እኔ ለሚያነጋግረኝ እንደ እንግዳ እሆንበታለሁ፤ የሚያነጋግረኝ እርሱም ለእኔ እንደ እንግዳ ይሆናል።'),
  ('2296e4c0-5749-510d-a661-cf3603d21948', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 12, 12, 'እንዲሁ እናንተም ለመንፈስ ቅዱስ ስጦታ ተፎካከሩ፤ ትበዙም ዘንድ ማኅበሩ የሚታነጽበትን ፈልጉ።'),
  ('e32068ae-ea5f-5aaf-a8e5-d540334132c6', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 13, 13, 'በማያውቀው ቋንቋ የሚናገር ሰውም መተርጐም እንዲችል ይጸልይ።'),
  ('0d466e3f-f780-5b66-a050-b441b5dde8a1', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 14, 14, 'በማላውቀው ቋንቋ የምጸልይ ከሆንሁ ቃሌ ብቻ ይጸልያል፤ ልቤ ግን ባዶ ነው።'),
  ('fdffe08e-9a14-5f3f-a68e-502616dc4788', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 15, 15, 'እንግዲህ ምን አደርጋለሁ በመንፈስ እጸልያለሁ፤ በማስተዋልም እማልዳለሁ፤ በመንፈሴ እዘምራለሁ፤ በማስተዋልም እዘምራለሁ።'),
  ('b786ed92-c09c-51ec-ab8c-054d9de4e56d', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 16, 16, 'አንተ በመንፈስ ብታመሰግን፥ ያ የቆመው ያልተማረው በአንተ ምስጋና ላይ እንዴት አሜን ይላል? የምትናገረውንና የምትጸልየውን አያውቅምና።'),
  ('58f1ea74-f58d-5390-a83f-3fc6656222f7', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 17, 17, 'እነሆ፥ አንተስ መልካም ታመሰግናለህ፤ ነገር ግን ሌላው እንዴት ይታነጻል?'),
  ('39742e5e-8e31-5c0d-a601-49c89d14a252', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 18, 18, 'እግዚአብሔርን አመሰግነዋለሁ፤ ከሁላችሁ ይልቅ እኔ በቋንቋዎች እናገራለሁና።'),
  ('ea2236f3-3809-5976-a2ad-ccb2e09d04df', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 19, 19, 'ነገር ግን ሌሎችን አስተምር ዘንድ፥ በቋንቋ ከሚነገር ብዙ ቃል ይልቅ በቤተ ክርስቲያን በአእምሮዬ አምስት ቃላትን ልናገር እሻለሁ።'),
  ('9c0c9b7c-96c7-54bc-a37f-f71b68521dcf', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 20, 20, 'ወንድሞቻችን ሆይ፥ በአእምሮ እንደ ሕፃናት አትሁኑ፤ ነገር ግን ለክፉ ነገር እንደ ሕፃናት ሁኑ፤ በዕውቀትም ፍጹማን ሁኑ።'),
  ('5c7f9ffb-03b8-59e7-abf6-0d2a8c06269e', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 21, 21, 'በኦሪትም፥ “ይህን ሕዝብ በሌሎች ቋንቋዎችና በሌላ አንደበት እናገራቸዋለሁ፤ እንዲሁም ሆኖ አይሰሙኝም ይላል እግዚአብሔር” ብሎአል።'),
  ('bea39326-4081-5806-ad2e-22ccc5b1bde3', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 22, 22, 'አሁንም ቋንቋ መናገር ለማያምኑ ሰዎች ለምልክት ነው፤ ለሚያምኑ ግን አይደለም፤ ትንቢትም ለሚያምኑ ነው እንጂ ለማያምኑ አይደለም።'),
  ('02f738dd-b4bf-5baf-a9d1-dd6cac2c1dd9', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 23, 23, 'ሕዝቡ ሁሉ በአንድነት ቢሰበሰቡ፥ ሁሉም በልዩ ልዩ ቋንቋ ቢናገሩ፥ አላዋቂዎች፥ ወይም የማያምኑ ቢመጡ አብደዋል ይሉአቸው የለምን?'),
  ('fe99f0bf-1faf-5b5f-a7f8-6ce77d93de3a', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 24, 24, 'ሁሉም ትንቢት ቢናገሩ ግን የማያምኑ ወይም አላዋቂዎች ቢመጡ ሁሉ ይከራከሩአቸው የለምን? ሁሉስ ያሳፍሩአቸው የለምን?'),
  ('c2defd03-3bd5-5717-a3a4-582069d1e7ee', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', '1d2ee2f3-f118-5548-a744-d9d3761e5296', 25, 25, 'በልባቸው የደበቁትም ይገለጣል፤ ከዚህ በኋላ ያ የማያምነው ተመልሶ ይጸጸታል፤ በግንባሩም ወድቆ ለእግዚአብሔር ይሰግዳል፥ በእውነት እግዚአብሔር ከእናንተ ጋር እንዳለም ይናገራል።'),
  ('14c0636a-4cd1-512c-a87e-4be038a06305', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 1, 26, 'አሁንም ወንድሞቻችን ሆይ፥ ሁላችሁ በምትሰበሰቡበት ጊዜ መዝሙር አላችሁ፤ ትምህርት አላችሁ፤ መግለጥ አላችሁ፤ በቋንቋ መናገር አላችሁ፤ መተርጐምም አላችሁ፤ ሁሉም ለሚታነጽበት ጥቅም አድርጉት።'),
  ('c3abff40-1515-59dd-a6a7-cce521f19648', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 2, 27, 'በቋንቋ የሚናገር ቢኖር ሁለት ሁለት፥ ወይም ቢበዛ ሦስት ሦስት እየሆኑ በተራ ይናገሩ፤ ሌላውም ይተርጕምለት።'),
  ('03bfe729-911a-52dd-aa65-8956f892b2a7', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 3, 28, 'የሚተረጕም ከሌለ ግን በቤተ ክርስቲያን በቋንቋ የሚናገረው ዝም ይበል፤ በእግዚአብሔር መካከልና በእርሱ መካከል ይናገር።'),
  ('5457bc3c-3d62-5a0b-a8e3-ca566ad81410', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 4, 29, 'ነቢያትም ቃላቸው ለቤተ ክርስቲያን ይታወቅ ዘንድ ሁለት ሁለት፥ ወይም ሦስት ሦስት ሆነው ይናገሩ።'),
  ('7342c5d0-3fe2-503b-aa0c-7f890b172454', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 5, 30, 'ተቀምጦ ሳለ ምሥጢር የተገለጠለት ቢኖር ፊተኛው ዝም ይበል።'),
  ('e956edc5-034a-583f-a6ea-0a4578609280', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 6, 31, 'ሁሉ እንዲማር፥ ሁሉም ደስ እንዲለው፥ እንዲጸናም ሁላችሁ እያንዳንዳችሁ ትንቢት ልትናገሩ ትችላላችሁና።'),
  ('8d4c59a7-c8a1-51f9-a540-40821de8cc59', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 7, 32, 'የነቢያት ሀብት ለነቢያት ይሰጣልና።'),
  ('60d7562d-12f3-5370-a332-03f3cea4dca1', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 8, 33, 'በቅዱሳን ጉባኤ ሁሉ እንደሚደረግ፥ እግዚአብሔር የሰላም አምላክ እንጂ የሁከት አምላክ አይደለምና።'),
  ('c6515f6d-fe14-5ea2-aaa7-97accda48c8d', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 9, 34, 'ሴቶችም በቤተ ክርስቲያን ዝም ይበሉ፤ ሊታዘዙ እንጂ ሊናገሩ አልተፈቀደምና፤ ኦሪትም እንዲህ ብሎአልና።'),
  ('d47ff553-9387-5821-aee0-9ae9cc0ef9a4', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 10, 35, 'ለሴት በቤተ ክርስቲያን መናገር ክልክል ነው፤ ሊማሩ ከወደዱ ደግሞ በቤታቸው ባሎቻቸውን ይጠይቁ።'),
  ('08b79d30-22e7-5327-abb4-b5bf7ccf98b8', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 11, 36, 'የእግዚአብሔር ቃል ከእናንተ ብቻ ወጥቶአልን? ወይስ የእግዚአብሔር ቃል ወደ እናንተ ብቻ ደርሶአልን?')
